INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('845cc6fd-3f0c-59fd-a597-7fd65821f635', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 11, 11, 'Yahweh said to Moses, "They shall offer their offering, each prince on his day, for the dedication of the altar."'),
  ('86119af1-74b4-50f3-a14c-4989108a5123', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 12, 12, 'He who offered his offering the first day was Nahshon the son of Amminadab, of the tribe of Judah,'),
  ('a4be7e68-26f1-5de9-adfd-45a5e97e08e9', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 13, 13, 'and his offering was: one silver platter, the weight of which was one hundred thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('7bd5befc-d876-5b18-a89b-6f8b2f1880a3', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 14, 14, 'one golden ladle of ten shekels, full of incense;'),
  ('60fa4111-c685-5049-ad8c-2c959b26a788', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 15, 15, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('50d5bba0-ba18-5fee-abf2-f489e1ca2430', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 16, 16, 'one male goat for a sin offering;'),
  ('b40b1dc9-c26a-5d4d-add7-83d918e1649e', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 17, 17, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, and five male lambs a year old. This was the offering of Nahshon the son of Amminadab.'),
  ('e1ce19ed-6764-55f4-a99a-8616eec1822e', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 18, 18, 'On the second day Nethanel the son of Zuar, prince of Issachar, gave his offering.'),
  ('c53d1ca4-55d4-55fb-a1ac-e3b57244b8ed', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 19, 19, 'He offered for his offering: one silver platter, the weight of which was one hundred thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('f5c4240c-ec5a-5e26-a1db-1ca21c51a752', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 20, 20, 'one golden ladle of ten shekels, full of incense;'),
  ('717d6477-676e-51f1-a5c1-f5fc34bb9c17', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 21, 21, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('14895ba0-8abb-5e73-a5bb-babae3aa8452', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 22, 22, 'one male goat for a sin offering;'),
  ('fcd26a2e-cca8-5f34-aaf4-f38f3e6a81b5', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 23, 23, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, five male lambs a year old. This was the offering of Nethanel the son of Zuar.'),
  ('c5021f5f-815d-5031-aacd-af1ec06a05bb', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 24, 24, 'On the third day Eliab the son of Helon, prince of the children of Zebulun'),
  ('e8142e48-7d1d-5483-a5c2-13a79de94619', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 25, 25, 'gave his offering: one silver platter, the weight of which was a hundred and thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('5396e151-00a6-52a0-a001-3a3201c661c1', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 26, 26, 'one golden ladle of ten shekels, full of incense;'),
  ('7af9a3fc-bb67-5b69-a457-a04f4c97f12a', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 27, 27, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('a95cdc92-7c73-56c0-ab24-7f3ef0130b74', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 28, 28, 'one male goat for a sin offering;'),
  ('ae82ef54-6524-5b28-a452-330650e733a2', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 29, 29, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, and five male lambs a year old. This was the offering of Eliab the son of Helon.'),
  ('3157eb66-198b-5922-a25c-a3a288c54335', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 30, 30, 'On the fourth day Elizur the son of Shedeur, prince of the children of Reuben'),
  ('a1b73b27-5e47-5e58-adfc-f24931276ed5', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 31, 31, 'gave his offering: one silver platter, the weight of which was one hundred thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('7a91b307-4fac-5df8-a7c5-711a036645ca', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 32, 32, 'one golden ladle of ten shekels, full of incense;'),
  ('61d298f4-d5da-5de2-a647-1f17e903679f', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 33, 33, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('f0f3c669-ab82-5546-aa64-b67e4e9bf249', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 34, 34, 'one male goat for a sin offering;'),
  ('61170076-c1d6-5f13-a1f8-29402b7a44a6', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 35, 35, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, and five male lambs a year old. This was the offering of Elizur the son of Shedeur.'),
  ('36e7f1b5-9b34-55ba-a7b6-0f4e50a9fbd5', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 36, 36, 'On the fifth day Shelumiel the son of Zurishaddai, prince of the children of Simeon'),
  ('e6fbd4db-aa12-5b1b-a832-2b397de05c43', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 37, 37, 'gave his offering: one silver platter, the weight of which was one hundred thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('2581656d-9284-5960-a875-fd94c91ef659', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 38, 38, 'one golden ladle of ten shekels, full of incense;'),
  ('e81eb3ae-ebc6-523f-af47-a16fcfd2dd3c', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 39, 39, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('18aba8a9-2372-58d3-a640-be951d67e72f', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 40, 40, 'one male goat for a sin offering;'),
  ('12833785-ad0a-5d71-af1e-35cf2ccf2564', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 41, 41, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, and five male lambs a year old: this was the offering of Shelumiel the son of Zurishaddai.'),
  ('f1a38c30-9126-5e76-a429-93f8ed18baa2', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 42, 42, 'On the sixth day, Eliasaph the son of Deuel, prince of the children of Gad'),
  ('16270d75-0431-554d-ab19-c4c7ce5ff996', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 43, 43, 'gave his offering: one silver platter, the weight of which was one hundred thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('6a787ab8-9dd1-5238-a5f5-018369be8752', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 44, 44, 'one golden ladle of ten shekels, full of incense;'),
  ('a2c63478-bada-5c7c-ab0d-467f7fcc08bf', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 45, 45, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('60a8d28f-904b-5208-a70e-1f703194cda5', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 46, 46, 'one male goat for a sin offering;'),
  ('cbbaaa65-5841-575b-a90d-a62a4f203338', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 47, 47, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, and five male lambs a year old. This was the offering of Eliasaph the son of Deuel.'),
  ('5853bd3e-985f-5859-a33e-4e1e411d302d', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 48, 48, 'On the seventh day Elishama the son of Ammihud, prince of the children of Ephraim'),
  ('cda9e323-b552-588a-a9ae-b2621ab64282', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 49, 49, 'gave his offering: one silver platter, the weight of which was one hundred thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('e4c0e973-2f87-5e90-a7c5-730933fc3bef', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 50, 50, 'one golden ladle of ten shekels, full of incense;'),
  ('baf64784-91c9-5677-adb8-97ae637133dd', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 51, 51, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('d7f57025-f635-53e4-a83c-5f9a313903b7', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 52, 52, 'one male goat for a sin offering;'),
  ('afffc5a2-9262-5b2f-a447-c39b0d728149', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 53, 53, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, and five male lambs a year old. This was the offering of Elishama the son of Ammihud.'),
  ('1dd4db40-19c0-5d4f-ae5b-fb91a58ec907', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 54, 54, 'On the eighth day Gamaliel the son of Pedahzur, prince of the children of Manasseh'),
  ('75debfb1-471f-5e92-ab21-9598c0aaf13a', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 55, 55, 'gave his offering: one silver platter, the weight of which was one hundred thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('7cf20d7a-8a79-5b60-ad2f-47c607172782', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 56, 56, 'one golden ladle of ten shekels, full of incense;'),
  ('7beb50b8-1a4e-5b5d-aa90-c37e688765be', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 57, 57, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('e78464eb-d4e0-5af0-ac79-fe4c96313af1', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 58, 58, 'one male goat for a sin offering;'),
  ('b6be6444-b434-5999-a812-d1cd1c95f992', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 59, 59, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, and five male lambs a year old. This was the offering of Gamaliel the son of Pedahzur.'),
  ('f866029d-5e15-5b63-a01a-410acb5171b3', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 60, 60, 'On the ninth day Abidan the son of Gideoni, prince of the children of Benjamin'),
  ('eaeab084-2b3e-52e9-a0d9-6fb2b3913fb4', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 61, 61, 'gave his offering: one silver platter, the weight of which was one hundred thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('050ea6f0-8caa-52bb-acae-75d9e26c420d', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 62, 62, 'one golden ladle of ten shekels, full of incense;'),
  ('355a93fa-f6af-51e3-a850-9fed4d548318', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 63, 63, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('b4174013-ac78-54bf-ae27-999c5cd7d9c1', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 64, 64, 'one male goat for a sin offering;'),
  ('39c08a79-dbde-5563-afc0-2d319951f494', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 65, 65, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, and five male lambs a year old. This was the offering of Abidan the son of Gideoni.'),
  ('5c65e370-ef27-5d3a-a310-f657222745c2', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 66, 66, 'On the tenth day Ahiezer the son of Ammishaddai, prince of the children of Dan'),
  ('c132c738-425d-5a09-a373-c3b533898957', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 67, 67, 'gave his offering: one silver platter, the weight of which was one hundred thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('19b7ee3e-ca37-5ba3-ae01-4831eba85ac1', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 68, 68, 'one golden ladle of ten shekels, full of incense;'),
  ('307504d0-4a4b-5b19-a195-beae92655baa', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 69, 69, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('48ab92d2-a2ec-5ac7-ab82-afb876e22e33', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 70, 70, 'one male goat for a sin offering;'),
  ('6744fade-0f0e-5766-a566-08db6f145e21', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 71, 71, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, and five male lambs a year old. This was the offering of Ahiezer the son of Ammishaddai.'),
  ('d46c86b3-3549-558b-a69f-eae5b1e85f89', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 72, 72, 'On the eleventh day Pagiel the son of Ochran, prince of the children of Asher'),
  ('ed1d0c65-5997-52f7-a110-46c693fe6ecf', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 73, 73, 'gave his offering: one silver platter, the weight of which was one hundred thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('439de075-25bc-51b7-a23f-9b1af6a3e338', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 74, 74, 'one golden ladle of ten shekels, full of incense;'),
  ('80264b58-300f-5c0e-a05c-7d52244d8ce4', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 75, 75, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('3c60d37b-2234-5bbc-a32f-c9dace17509e', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 76, 76, 'one male goat for a sin offering;'),
  ('81a95d59-44ce-55e4-adf8-ca1f39b84d33', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 77, 77, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, and five male lambs a year old. This was the offering of Pagiel the son of Ochran.'),
  ('be02d5bd-778b-5de6-ae38-5d7980d296ff', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 78, 78, 'On the twelfth day Ahira the son of Enan, prince of the children of Naphtali'),
  ('33ed0a2b-fdd6-59a3-a842-10ec6c84f35c', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 79, 79, 'gave his offering: one silver platter, the weight of which was one hundred thirty shekels, one silver bowl of seventy shekels, after the shekel of the sanctuary; both of them full of fine flour mixed with oil for a meal offering;'),
  ('ab9ff7cb-7ded-5304-ac87-54867aae77ef', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 80, 80, 'one golden spoon of ten shekels, full of incense;'),
  ('9ca5a4ca-38e6-52a8-a224-f556328c0c16', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 81, 81, 'one young bull, one ram, one male lamb a year old, for a burnt offering;'),
  ('73179e8b-86e3-56a5-ab16-56d6ae7ad061', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 82, 82, 'one male goat for a sin offering;'),
  ('5d61984f-e61a-57cd-a0d2-ac3d58edd295', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 83, 83, 'and for the sacrifice of peace offerings, two head of cattle, five rams, five male goats, and five male lambs a year old. This was the offering of Ahira the son of Enan.'),
  ('16dc04a6-7e76-5a8c-a889-a8685b69c69a', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 84, 84, 'This was the dedication of the altar, on the day when it was anointed, by the princes of Israel: twelve silver platters, twelve silver bowls, twelve golden ladles;'),
  ('955d6ac8-bcc6-5f09-a92a-db1492072e7c', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 85, 85, 'each silver platter weighing one hundred thirty shekels, and each bowl seventy; all the silver of the vessels two thousand four hundred shekels, after the shekel of the sanctuary;'),
  ('1203f274-3ffb-5940-a716-6e459a0dc26b', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 86, 86, 'the twelve golden ladles, full of incense, weighing ten shekels apiece, after the shekel of the sanctuary; all the gold of the ladles weighed one hundred twenty shekels;'),
  ('dd3b36fc-de1f-595d-abc9-c770b4843bf4', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 87, 87, 'all the cattle for the burnt offering twelve bulls, the rams twelve, the male lambs a year old twelve, and their meal offering; and the male goats for a sin offering twelve;'),
  ('ef375dcf-d9d3-5ad4-a9cc-c1e9f0cab67a', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 88, 88, 'and all the cattle for the sacrifice of peace offerings twenty-four bulls, the rams sixty, the male goats sixty, the male lambs a year old sixty. This was the dedication of the altar, after it was anointed.'),
  ('2dda6587-a96d-5e09-a226-e085ab580564', '4dfcb08d-9fdc-5330-abc0-ebd127f75250', NULL, 89, 89, 'When Moses went into the Tent of Meeting to speak with Yahweh, he heard his voice speaking to him from above the mercy seat that was on the ark of the Testimony, from between the two cherubim: and he spoke to him.'),
  ('c459aa42-1b4c-5dc1-af21-4f99762b3eed', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('6c903726-930f-5f28-a6e5-1421883051e0', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 2, 2, '"Speak to Aaron, and tell him, ''When you light the lamps, the seven lamps shall give light in front of the lampstand.''"'),
  ('ea593560-6319-5841-a293-429f9c1c54e5', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 3, 3, 'Aaron did so. He lit its lamps to light the area in front of the lampstand, as Yahweh commanded Moses.'),
  ('b8439a2b-f74e-577b-ad5d-ca625d71dd04', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 4, 4, 'This was the workmanship of the lampstand, beaten work of gold. From its base to its flowers, it was beaten work: according to the pattern which Yahweh had shown Moses, so he made the lampstand.'),
  ('6c33e3f0-37d2-5d29-a6f8-37817068a6e3', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 5, 5, 'Yahweh spoke to Moses, saying,'),
  ('c2d66045-8ca6-53e3-a42b-d7da5afd0ec3', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 6, 6, '"Take the Levites from among the children of Israel, and cleanse them.'),
  ('593de396-f86f-5f65-a6d5-27a4044512a1', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 7, 7, 'You shall do this to them, to cleanse them: sprinkle the water of cleansing on them, let them shave their whole bodies with a razor, and let them wash their clothes, and cleanse themselves.'),
  ('75d2d28b-8b08-525d-aa1d-b9aa09d4432c', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 8, 8, 'Then let them take a young bull, and its meal offering, fine flour mixed with oil; and another young bull you shall take for a sin offering.'),
  ('2df95054-2187-5a68-a7e0-e632933f7340', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 9, 9, 'You shall present the Levites before the Tent of Meeting. You shall assemble the whole congregation of the children of Israel.'),
  ('84fce57a-478a-5325-ae0a-aa59970f840e', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 10, 10, 'You shall present the Levites before Yahweh. The children of Israel shall lay their hands on the Levites,'),
  ('9b40520f-2f14-513d-adf0-2278bcea2635', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 11, 11, 'and Aaron shall offer the Levites before Yahweh for a wave offering, on the behalf of the children of Israel, that it may be theirs to do the service of Yahweh.'),
  ('9e26fb01-8c29-54f2-ae20-5dd0af8d7842', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 12, 12, '"The Levites shall lay their hands on the heads of the bulls, and you shall offer the one for a sin offering, and the other for a burnt offering to Yahweh, to make atonement for the Levites.'),
  ('3877ff24-a288-5c66-a172-d178adcfa86a', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 13, 13, 'You shall set the Levites before Aaron, and before his sons, and offer them as a wave offering to Yahweh.'),
  ('ba3aa6d1-7375-5837-a126-aa7af6949f79', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 14, 14, 'Thus you shall separate the Levites from among the children of Israel, and the Levites shall be mine.'),
  ('c2643f03-58ee-5845-aa89-835d9edaf1fb', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 15, 15, '"After that, the Levites shall go in to do the service of the Tent of Meeting: and you shall cleanse them, and offer them as a wave offering.'),
  ('8e665864-f289-5058-afbc-7f03469f9d68', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 16, 16, 'For they are wholly given to me from among the children of Israel; instead of all who open the womb, even the firstborn of all the children of Israel, I have taken them to me.'),
  ('1296c7b8-4a1a-5388-af47-bf00209e49da', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 17, 17, 'For all the firstborn among the children of Israel are mine, both man and animal. On the day that I struck all the firstborn in the land of Egypt, I sanctified them for myself.'),
  ('ee42484a-5d16-559d-a922-2f924975808d', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 18, 18, 'I have taken the Levites instead of all the firstborn among the children of Israel.'),
  ('e91ea943-e639-5e9b-a732-a424dfc389ed', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 19, 19, 'I have given the Levites as a gift to Aaron and to his sons from among the children of Israel, to do the service of the children of Israel in the Tent of Meeting, and to make atonement for the children of Israel; that there be no plague among the children of Israel, when the children of Israel come near to the sanctuary."'),
  ('51861de5-5bc5-5ec4-ab3b-85091c33d2a4', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 20, 20, 'Moses, and Aaron, and all the congregation of the children of Israel did so to the Levites. According to all that Yahweh commanded Moses concerning the Levites, so the children of Israel did to them.'),
  ('5f687ad2-fd50-5d5a-a28d-fe36f12b6e1e', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 21, 21, 'The Levites purified themselves from sin, and they washed their clothes; and Aaron offered them for a wave offering before Yahweh; and Aaron made atonement for them to cleanse them.'),
  ('c752761e-4cc2-53e3-ad34-4d644d55cec9', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 22, 22, 'After that, the Levites went in to do their service in the Tent of Meeting before Aaron, and before his sons: as Yahweh had commanded Moses concerning the Levites, so they did to them.'),
  ('dfbcb64a-5674-5137-a21c-95c340017a5f', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 23, 23, 'Yahweh spoke to Moses, saying,'),
  ('28edefc3-2364-5b01-af18-2a8f53476101', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 24, 24, '"This is that which belongs to the Levites: from twenty-five years old and upward they shall go in to wait on the service in the work of the Tent of Meeting;'),
  ('a512d5be-4012-56a8-a201-3042aeb1bede', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 25, 25, 'and from the age of fifty years they shall cease waiting on the work, and shall serve no more,'),
  ('4c4315d5-007e-58e2-a305-0757c2418c2c', 'b6820bc1-a047-5e8d-aa2c-0a47f4755b1a', NULL, 26, 26, 'but shall minister with their brothers in the Tent of Meeting, to perform the duty, and shall do no service. You shall do thus to the Levites concerning their duties."'),
  ('b344d812-a864-548c-a0e8-45a1e0cc84cc', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 1, 1, 'Yahweh spoke to Moses in the wilderness of Sinai, in the first month of the second year after they had come out of the land of Egypt, saying,'),
  ('da2e61fd-6d29-5c2c-a4de-5766d0417dbd', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 2, 2, '"Moreover let the children of Israel keep the Passover in its appointed season.'),
  ('3a9c0444-99ea-5b32-afa3-14c4a00ac4f1', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 3, 3, 'On the fourteenth day of this month, at evening, you shall keep it in its appointed season--according to all its statutes, and according to all its ordinances, you shall keep it."'),
  ('88d58f82-252f-5923-af40-a78bd3ae8bf9', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 4, 4, 'Moses spoke to the children of Israel, that they should keep the Passover.'),
  ('470b07ef-2131-5d92-a584-803e7f9f635e', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 5, 5, 'They kept the Passover in the first month, on the fourteenth day of the month, at evening, in the wilderness of Sinai. According to all that Yahweh commanded Moses, so the children of Israel did.'),
  ('2d2d0836-a41a-5347-ab91-2465a4239931', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 6, 6, 'There were certain men, who were unclean because of the dead body of a man, so that they could not keep the Passover on that day, and they came before Moses and before Aaron on that day.'),
  ('fee12721-4bd8-5847-ab9e-b86f1c1a15d1', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 7, 7, 'Those men said to him, "We are unclean because of the dead body of a man. Why are we kept back, that we may not offer the offering of Yahweh in its appointed season among the children of Israel?"'),
  ('28d6f430-b355-53e7-a2f7-5ec244b073fe', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 8, 8, 'Moses answered them, "Wait, that I may hear what Yahweh will command concerning you."'),
  ('1f7c70bb-99ba-5b6f-a99a-ba7a0fb4feda', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 9, 9, 'Yahweh spoke to Moses, saying,'),
  ('c4e26521-6cbf-52b6-a3bb-14a60cfca50b', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 10, 10, '"Say to the children of Israel, ''If any man of you or of your generations is unclean by reason of a dead body, or is on a journey far away, he shall still keep the Passover to Yahweh.'),
  ('e198cc81-2202-5212-a8aa-74a94a79a9dc', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 11, 11, 'In the second month, on the fourteenth day at evening they shall keep it; they shall eat it with unleavened bread and bitter herbs.'),
  ('dc7fc6c2-f0e4-5df2-a791-6f52df8354cb', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 12, 12, 'They shall leave none of it until the morning, nor break a bone of it. According to all the statute of the Passover they shall keep it.'),
  ('78375cd4-e5cc-5469-af2c-53ba40d203ab', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 13, 13, 'But the man who is clean, and is not on a journey, and fails to keep the Passover, that soul shall be cut off from his people. Because he didn''t offer the offering of Yahweh in its appointed season, that man shall bear his sin.'),
  ('252c8966-e9a6-5063-a054-f86605e9beae', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 14, 14, '"''If a foreigner lives among you, and desires to keep the Passover to Yahweh; according to the statute of the Passover, and according to its ordinance, so shall he do. You shall have one statute, both for the foreigner, and for him who is born in the land.''"'),
  ('c1d659db-c18b-5900-a0ed-83a29da9dfdc', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 15, 15, 'On the day that the tabernacle was raised up, the cloud covered the tabernacle, even the Tent of the Testimony: and at evening it was over the tabernacle as it were the appearance of fire, until morning.'),
  ('4a22c118-00be-5c5f-a4c5-2cdbd7f859e7', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 16, 16, 'So it was continually. The cloud covered it, and the appearance of fire by night.'),
  ('f1ec2622-8eb9-5767-a199-bc75a3ec2a5f', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 17, 17, 'Whenever the cloud was taken up from over the Tent, then after that the children of Israel traveled; and in the place where the cloud remained, there the children of Israel encamped.'),
  ('cf1b3ff1-50aa-571e-aba7-ae0594f25d4d', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 18, 18, 'At the commandment of Yahweh, the children of Israel traveled, and at the commandment of Yahweh they encamped. As long as the cloud remained on the tabernacle they remained encamped.'),
  ('d71cd058-7f29-5423-a56a-4d0b52bd7cb9', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 19, 19, 'When the cloud stayed on the tabernacle many days, then the children of Israel kept Yahweh''s command, and didn''t travel.'),
  ('32097e35-1e01-5479-a166-01bb925e1e76', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 20, 20, 'Sometimes the cloud was a few days on the tabernacle; then according to the commandment of Yahweh they remained encamped, and according to the commandment of Yahweh they traveled.'),
  ('f1af71a9-bf23-5240-a496-a627abb84a22', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 21, 21, 'Sometimes the cloud was from evening until morning; and when the cloud was taken up in the morning, they traveled: or by day and by night, when the cloud was taken up, they traveled.'),
  ('1b9e59d2-6372-57d3-aba7-68831082db49', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 22, 22, 'Whether it was two days, or a month, or a year that the cloud stayed on the tabernacle, remaining on it, the children of Israel remained encamped, and didn''t travel; but when it was taken up, they traveled.'),
  ('cbc21b65-5953-532e-a27d-74254513478a', '04e51168-088c-585c-acad-f3dc3dfeb93a', NULL, 23, 23, 'At the commandment of Yahweh they encamped, and at the commandment of Yahweh they traveled. They kept Yahweh''s command, at the commandment of Yahweh by Moses.'),
  ('5b07837e-1a18-5707-a78c-0e95b63b3ae2', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('cb5beb4e-efa8-5598-a568-2310e8d7155b', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 2, 2, '"Make two trumpets of silver. You shall make them of beaten work. You shall use them for the calling of the congregation, and for the journeying of the camps.'),
  ('8266d145-ec43-53ee-ad65-1bad56500698', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 3, 3, 'When they blow them, all the congregation shall gather themselves to you at the door of the Tent of Meeting.'),
  ('12938771-cc35-51f0-a470-891e771c967d', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 4, 4, 'If they blow just one, then the princes, the heads of the thousands of Israel, shall gather themselves to you.'),
  ('46b0891e-035e-5b66-acbe-184b81d20b1e', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 5, 5, 'When you blow an alarm, the camps that lie on the east side shall go forward.'),
  ('d865f3b0-736c-5521-a6c0-54bef68aacba', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 6, 6, 'When you blow an alarm the second time, the camps that lie on the south side shall go forward. They shall blow an alarm for their journeys.'),
  ('1d5d8d37-0f00-542d-ac8a-a50ba91942dd', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 7, 7, 'But when the assembly is to be gathered together, you shall blow, but you shall not sound an alarm.'),
  ('82649c59-1734-5913-ae75-dbc2b7e12622', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 8, 8, '"The sons of Aaron, the priests, shall blow the trumpets. This shall be to you for a statute forever throughout your generations.'),
  ('a149c2a0-c7a4-57d2-a773-557eda593714', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 9, 9, 'When you go to war in your land against the adversary who oppresses you, then you shall sound an alarm with the trumpets. Then you will be remembered before Yahweh your God, and you will be saved from your enemies.'),
  ('030d10ac-2d5e-5ab1-af51-3a73666e9b04', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 10, 10, '"Also in the day of your gladness, and in your set feasts, and in the beginnings of your months, you shall blow the trumpets over your burnt offerings, and over the sacrifices of your peace offerings; and they shall be to you for a memorial before your God. I am Yahweh your God."'),
  ('6d774946-036b-5a14-ae95-e0d2dc60ef81', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 11, 11, 'It happened in the second year, in the second month, on the twentieth day of the month, that the cloud was taken up from over the tabernacle of the testimony.'),
  ('5b868ebb-75c9-5d16-a3c7-efc674569a45', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 12, 12, 'The children of Israel went forward according to their journeys out of the wilderness of Sinai; and the cloud stayed in the wilderness of Paran.'),
  ('15b41888-4300-5f2c-a648-2887bb8d5a92', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 13, 13, 'They first went forward according to the commandment of Yahweh by Moses.'),
  ('37808fcb-93c4-58cb-afc0-62f8c52eef0e', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 14, 14, 'First, the standard of the camp of the children of Judah went forward according to their armies. Nahshon the son of Amminadab was over his army.'),
  ('2c8b8dc9-5328-5925-aadb-f53c3aa43b52', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 15, 15, 'Nethanel the son of Zuar was over the army of the tribe of the children of Issachar.'),
  ('ba23c33a-540d-5718-a968-485c74a1d4fa', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 16, 16, 'Eliab the son of Helon was over the army of the tribe of the children of Zebulun.'),
  ('546bfca1-a330-5ab5-a8cd-a7225f28d532', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 17, 17, 'The tabernacle was taken down; and the sons of Gershon and the sons of Merari, who bore the tabernacle, went forward.'),
  ('0d129191-a144-5f40-a87f-94485210a427', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 18, 18, 'The standard of the camp of Reuben went forward according to their armies. Elizur the son of Shedeur was over his army.'),
  ('850d5dbf-63a6-500c-a8d6-a5af43d79df5', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 19, 19, 'Shelumiel the son of Zurishaddai was over the army of the tribe of the children of Simeon.'),
  ('74c0d6f6-0623-52a7-a8f6-bfb61e4766b2', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 20, 20, 'Eliasaph the son of Deuel was over the army of the tribe of the children of Gad.'),
  ('328d20a9-b4aa-5c32-adc0-0c1ac63b26bc', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 21, 21, 'The Kohathites set forward, bearing the sanctuary. The others set up the tabernacle before they arrived.'),
  ('eff60c1e-2ff1-53b1-a790-6852347c4c90', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 22, 22, 'The standard of the camp of the children of Ephraim set forward according to their armies. Elishama the son of Ammihud was over his army.'),
  ('d2cc0c5e-35d4-5911-ab56-f02257016435', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 23, 23, 'Gamaliel the son of Pedahzur was over the army of the tribe of the children of Manasseh.'),
  ('1d2efc09-d808-516c-a688-27747e7e706d', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 24, 24, 'Abidan the son of Gideoni was over the army of the tribe of the children of Benjamin.'),
  ('b4212dad-28f4-595a-a629-3d6c670c9282', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 25, 25, 'The standard of the camp of the children of Dan, which was the rear guard of all the camps, set forward according to their armies. Ahiezer the son of Ammishaddai was over his army.'),
  ('f4106de3-27e1-5d9b-afe2-2580c6a44396', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 26, 26, 'Pagiel the son of Ochran was over the army of the tribe of the children of Asher.'),
  ('d7a56cfb-226a-583c-ae76-b9c60424357e', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 27, 27, 'Ahira the son of Enan was over the army of the tribe of the children of Naphtali.'),
  ('fca6cad6-afaa-56de-aaff-b6e877748f29', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 28, 28, 'Thus were the travels of the children of Israel according to their armies; and they went forward.'),
  ('f4f2fe0f-0333-5cc0-a097-27f83abd6eb5', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 29, 29, 'Moses said to Hobab, the son of Reuel the Midianite, Moses'' father-in-law, "We are journeying to the place of which Yahweh said, ''I will give it to you.'' Come with us, and we will treat you well; for Yahweh has spoken good concerning Israel."'),
  ('75d5898a-1c09-5858-a26a-1f53e002c120', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 30, 30, 'He said to him, "I will not go; but I will depart to my own land, and to my relatives."'),
  ('28194a16-e90c-5507-a97c-07b949d859fb', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 31, 31, 'He said, "Don''t leave us, please; because you know how we are to encamp in the wilderness, and you can be our eyes.'),
  ('a579ffd7-bf91-58e3-abe6-62fdc7ee39c6', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 32, 32, 'It shall be, if you go with us, yes, it shall be, that whatever good Yahweh does to us, we will do the same to you."'),
  ('356432a1-b7c0-5b98-ac50-a868a7a08a5e', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 33, 33, 'They set forward from the Mount of Yahweh three days'' journey. The ark of the covenant of Yahweh went before them three days'' journey, to seek out a resting place for them.'),
  ('a51c4189-f12f-5d56-a10c-727bfa2fd490', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 34, 34, 'The cloud of Yahweh was over them by day, when they set forward from the camp.'),
  ('bcacabd6-b51a-5cbe-a531-f7a9ce5d85be', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 35, 35, 'It happened, when the ark went forward, that Moses said, "Rise up, Yahweh, and let your enemies be scattered! Let those who hate you flee before you!"'),
  ('17618a87-3ba3-5a97-af9b-7351965bfd11', 'ee87aea3-e31d-5f6c-a631-3cb36dceb4f7', NULL, 36, 36, 'When it rested, he said, "Return, Yahweh, to the ten thousands of the thousands of Israel."'),
  ('20eb700a-ad78-5c62-a757-7d19ec52b8fe', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 1, 1, 'The people were complaining in the ears of Yahweh. When Yahweh heard it, his anger was kindled; and Yahweh''s fire burnt among them, and consumed some of the outskirts of the camp.'),
  ('ce4d64c3-0753-5e06-ac2e-924f61721e19', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 2, 2, 'The people cried to Moses; and Moses prayed to Yahweh, and the fire abated.'),
  ('e74a258f-bd6b-5c41-a065-ef77343ffff3', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 3, 3, 'The name of that place was called Taberah, because Yahweh''s fire burnt among them.'),
  ('b28fca4a-1e48-590b-af55-54e5005ded0e', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 4, 4, 'The mixed multitude that was among them lusted exceedingly: and the children of Israel also wept again, and said, "Who will give us flesh to eat?'),
  ('1aaf0f93-4c70-5e5c-a822-b498a65a6ade', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 5, 5, 'We remember the fish, which we ate in Egypt for nothing; the cucumbers, and the melons, and the leeks, and the onions, and the garlic;'),
  ('6bcfd5ff-c29e-583c-a501-66006ec5fa84', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 6, 6, 'but now we have lost our appetite. There is nothing at all except this manna to look at."'),
  ('f6f28d50-a18d-53d7-a46b-2b48c821fda8', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 7, 7, 'The manna was like coriander seed, and its appearance like the appearance of bdellium.'),
  ('93a49df0-a3bf-548a-afe5-6fa16b742a7b', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 8, 8, 'The people went around, gathered it, and ground it in mills, or beat it in mortars, and boiled it in pots, and made cakes of it. Its taste was like the taste of fresh oil.'),
  ('e4813210-c7e7-50c9-aa19-12d69faee3ba', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 9, 9, 'When the dew fell on the camp in the night, the manna fell on it.'),
  ('03f1e02b-8df9-51c1-a3c2-e8e120816791', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 10, 10, 'Moses heard the people weeping throughout their families, every man at the door of his tent; and the anger of Yahweh was kindled greatly; and Moses was displeased.'),
  ('7b9685c4-a4d4-5123-aa12-2271e89ba0e2', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 11, 11, 'Moses said to Yahweh, "Why have you treated with your servant so badly? Why haven''t I found favor in your sight, that you lay the burden of all this people on me?'),
  ('b0e0075f-67a0-508c-a60a-ce0c222a0d55', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 12, 12, 'Have I conceived all this people? Have I brought them forth, that you should tell me, ''Carry them in your bosom, as a nurse carries a nursing infant, to the land which you swore to their fathers?'''),
  ('05dbe5f8-da8f-567b-a264-68dce6cb14b3', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 13, 13, 'Where could I get meat to give to all this people? For they weep to me, saying, ''Give us meat, that we may eat.'''),
  ('36f499f1-ffa0-5a0b-a50c-fcab64462384', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 14, 14, 'I am not able to bear all this people alone, because it is too heavy for me.'),
  ('76e2aeb5-61d3-5f46-aa85-77638a99a239', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 15, 15, 'If you treat me this way, please kill me right now, if I have found favor in your sight; and don''t let me see my wretchedness."'),
  ('6c88191f-0316-5f91-a23c-0bf17f8f2d50', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 16, 16, 'Yahweh said to Moses, "Gather to me seventy men of the elders of Israel, whom you know to be the elders of the people, and officers over them; and bring them to the Tent of Meeting, that they may stand there with you.'),
  ('2c123316-337d-590d-ad7f-538700e0ccf1', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 17, 17, 'I will come down and talk with you there. I will take of the Spirit which is on you, and will put it on them; and they shall bear the burden of the people with you, that you not bear it yourself alone.'),
  ('699a72ef-5eb9-5213-a5de-34d15c3063ff', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 18, 18, '"Say to the people, ''Sanctify yourselves against tomorrow, and you will eat flesh; for you have wept in the ears of Yahweh, saying, "Who will give us flesh to eat? For it was well with us in Egypt." Therefore Yahweh will give you flesh, and you will eat.'),
  ('4b95bf5f-d231-512c-acd7-69e93a065b04', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 19, 19, 'You will not eat one day, nor two days, nor five days, neither ten days, nor twenty days,'),
  ('79717b93-01ed-54da-a4cd-1c7015a71f79', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 20, 20, 'but a whole month, until it come out at your nostrils, and it is loathsome to you; because that you have rejected Yahweh who is among you, and have wept before him, saying, "Why did we come out of Egypt?"''"'),
  ('cf67c38a-f339-509f-ac53-4ddfde9914c2', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 21, 21, 'Moses said, "The people, among whom I am, are six hundred thousand men on foot; and you have said, ''I will give them flesh, that they may eat a whole month.'''),
  ('a12ef946-a057-5267-a859-6de15b3ab3ae', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 22, 22, 'Shall flocks and herds be slaughtered for them, to be sufficient for them? Shall all the fish of the sea be gathered together for them, to be sufficient for them?"'),
  ('26845e6c-ae2d-5c86-a17b-e2693c15c2ca', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 23, 23, 'Yahweh said to Moses, "Has Yahweh''s hand grown short? Now you will see whether my word will happen to you or not."'),
  ('8a55c9fd-15fa-5c8a-ac51-abd21dd16e36', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 24, 24, 'Moses went out, and told the people the words of Yahweh; and he gathered seventy men of the elders of the people, and set them around the Tent.'),
  ('61645125-467d-5e72-ae74-ca56cf9b303b', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 25, 25, 'Yahweh came down in the cloud, and spoke to him, and took of the Spirit that was on him, and put it on the seventy elders: and it happened that when the Spirit rested on them, they prophesied, but they did so no more.'),
  ('31052a3e-48fe-53f5-adab-ef6b3777efda', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 26, 26, 'But two men remained in the camp. The name of one was Eldad, and the name of the other Medad: and the Spirit rested on them; and they were of those who were written, but had not gone out to the Tent; and they prophesied in the camp.'),
  ('7c208911-7776-5196-a605-33eda4d751f1', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 27, 27, 'A young man ran, and told Moses, and said, "Eldad and Medad are prophesying in the camp!"'),
  ('aec00bba-5d54-5f86-a76a-4372083ad975', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 28, 28, 'Joshua the son of Nun, the servant of Moses, one of his chosen men, answered, "My lord Moses, forbid them!"'),
  ('251d68bd-a05d-505b-a30d-1924a21f3443', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 29, 29, 'Moses said to him, "Are you jealous for my sake? I wish that all Yahweh''s people were prophets, that Yahweh would put his Spirit on them!"'),
  ('15bbdb68-3c01-58e0-a057-7dc9f0e3cc84', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 30, 30, 'Moses went into the camp, he and the elders of Israel.'),
  ('361af387-9f81-58da-a423-22637e6feb51', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 31, 31, 'A wind from Yahweh went out and brought quails from the sea, and let them fall by the camp, about a day''s journey on this side, and a day''s journey on the other side, around the camp, and about two cubits above the surface of the earth.'),
  ('4b572363-cd64-5e52-a49b-72f7aade49d6', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 32, 32, 'The people rose up all that day, and all the night, and all the next day, and gathered the quails. He who gathered least gathered ten homers; and they spread them all abroad for themselves around the camp.'),
  ('12e2bede-3d37-561f-a4a2-2e98d4043469', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 33, 33, 'While the flesh was yet between their teeth, before it was chewed, the anger of Yahweh was kindled against the people, and Yahweh struck the people with a very great plague.'),
  ('ebda94f3-2325-58d2-a57b-95e8e08616c9', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 34, 34, 'The name of that place was called Kibroth Hattaavah, because there they buried the people who lusted.'),
  ('9ab0dd91-fa53-5aff-ab09-d9b126abea09', '29c97e6c-9c1e-5269-adf9-3001f2cb892f', NULL, 35, 35, 'From Kibroth Hattaavah the people traveled to Hazeroth; and they stayed at Hazeroth.'),
  ('25ae2821-47f3-55d2-acb4-0358ebe845a1', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 1, 1, 'Miriam and Aaron spoke against Moses because of the Cushite woman whom he had married; for he had married a Cushite woman.'),
  ('6baaf007-60e2-5ffc-a118-c750e5374265', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 2, 2, 'They said, "Has Yahweh indeed spoken only with Moses? Hasn''t he spoken also with us?" And Yahweh heard it.'),
  ('a0578387-95b4-5c8e-a2d4-e03a6e68441f', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 3, 3, 'Now the man Moses was very humble, above all the men who were on the surface of the earth.'),
  ('c06ea338-915e-5cde-a664-09af74363e20', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 4, 4, 'Yahweh spoke suddenly to Moses, to Aaron, and to Miriam, "You three come out to the Tent of Meeting!" The three of them came out.'),
  ('6e8fafa3-fd5f-5ede-a3ba-f9222223d98b', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 5, 5, 'Yahweh came down in a pillar of cloud, and stood at the door of the Tent, and called Aaron and Miriam; and they both came forward.'),
  ('47c2a715-efe9-5f31-a83c-0e7aba3adf2d', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 6, 6, 'He said, "Hear now my words. If there is a prophet among you, I Yahweh will make myself known to him in a vision. I will speak with him in a dream.'),
  ('934f4dd2-f59e-59aa-a16b-897281df44bb', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 7, 7, 'My servant Moses is not so. He is faithful in all my house.'),
  ('fe2a4bf5-e2aa-57d5-ad2b-44d15343e2eb', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 8, 8, 'With him I will speak mouth to mouth, even plainly, and not in riddles; and he shall see Yahweh''s form. Why then were you not afraid to speak against my servant, against Moses?"'),
  ('601950a6-e1cc-50c9-ae09-848d9e44d3e1', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 9, 9, 'The anger of Yahweh was kindled against them; and he departed.'),
  ('3bde3cd6-ded9-591f-af40-105e8eaecc1b', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 10, 10, 'The cloud departed from over the Tent; and behold, Miriam was leprous, as white as snow. Aaron looked at Miriam, and behold, she was leprous.'),
  ('175ef49d-d224-5e18-a912-92ea2633769a', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 11, 11, 'Aaron said to Moses, "Oh, my lord, please don''t count this sin against us, in which we have done foolishly, and in which we have sinned.'),
  ('d35b9ff7-c96f-52c5-acae-6f28e8fe86f1', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 12, 12, 'Let her not, I pray, be as one dead, of whom the flesh is half consumed when he comes out of his mother''s womb."'),
  ('3d54363c-7d1b-5d59-a3c3-ac95e8335383', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 13, 13, 'Moses cried to Yahweh, saying, "Heal her, God, I beg you!"'),
  ('ddcdf8d3-5e5a-5170-a42a-296d6fa45a54', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 14, 14, 'Yahweh said to Moses, "If her father had but spit in her face, shouldn''t she be ashamed seven days? Let her be shut up outside of the camp seven days, and after that she shall be brought in again."'),
  ('54da6abd-4fdd-5626-af3e-7bd70bac8baa', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 15, 15, 'Miriam was shut up outside of the camp seven days, and the people didn''t travel until Miriam was brought in again.'),
  ('efae69fb-7073-5d20-a0a1-269c1f9a1cc4', '2274c997-6e27-5e14-a166-f161cd06f007', NULL, 16, 16, 'Afterward the people traveled from Hazeroth, and encamped in the wilderness of Paran.'),
  ('7d937e59-210d-54ad-a455-40cdf1afedc8', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('112b1695-c66f-5d18-a808-30135009a25b', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 2, 2, '"Send men, that they may spy out the land of Canaan, which I give to the children of Israel. Of every tribe of their fathers, you shall send a man, every one a prince among them."'),
  ('59028d23-d6e1-5e31-a4a0-2f2421d5dd2a', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 3, 3, 'Moses sent them from the wilderness of Paran according to the commandment of Yahweh: all of them men who were heads of the children of Israel.'),
  ('41d9f550-d532-5a7b-afda-a4adf1aa51cd', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 4, 4, 'These were their names: Of the tribe of Reuben, Shammua the son of Zaccur.'),
  ('c000efff-f32c-5ddb-a4e5-3408709b873d', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 5, 5, 'Of the tribe of Simeon, Shaphat the son of Hori.'),
  ('3f37a340-2017-5e77-a3de-8ee8b2bd7d0d', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 6, 6, 'Of the tribe of Judah, Caleb the son of Jephunneh.'),
  ('02995fbd-9022-5715-a532-90469c65bfb8', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 7, 7, 'Of the tribe of Issachar, Igal the son of Joseph.'),
  ('89579b6f-42a3-51a6-a485-b4f15e0fe7bb', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 8, 8, 'Of the tribe of Ephraim, Hoshea the son of Nun.'),
  ('f3589d72-3027-5bac-a9cc-613e7f665cab', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 9, 9, 'Of the tribe of Benjamin, Palti the son of Raphu.'),
  ('2ec32926-ea37-5ef0-a473-544d84f0c9b7', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 10, 10, 'Of the tribe of Zebulun, Gaddiel the son of Sodi.'),
  ('a70af74d-cae7-5afb-a4f0-19149184f52f', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 11, 11, 'Of the tribe of Joseph, [namely], of the tribe of Manasseh, Gaddi the son of Susi.'),
  ('6ba135b3-67a8-5405-acd9-d7294df8da1a', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 12, 12, 'Of the tribe of Dan, Ammiel the son of Gemalli.'),
  ('5f6c9c9b-6f5e-5526-a65b-8c2344790ed1', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 13, 13, 'Of the tribe of Asher, Sethur the son of Michael.'),
  ('abeb322d-e651-500d-a867-fba1e18231b1', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 14, 14, 'Of the tribe of Naphtali, Nahbi the son of Vophsi.'),
  ('02955bf2-99d6-5edd-abbe-0b15166e3f76', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 15, 15, 'Of the tribe of Gad, Geuel the son of Machi.'),
  ('0ea84631-0b4e-5237-acf5-801e91fb5130', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 16, 16, 'These are the names of the men who Moses sent to spy out the land. Moses called Hoshea the son of Nun Joshua.'),
  ('931a7e1c-9ca5-53e4-a713-c8b3c1fbed97', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 17, 17, 'Moses sent them to spy out the land of Canaan, and said to them, "Go up this way by the South, and go up into the hill country:'),
  ('54187dfb-0f4a-555e-a53b-8f0d3b863f56', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 18, 18, 'and see the land, what it is; and the people who dwell therein, whether they are strong or weak, whether they are few or many;'),
  ('d7528114-b208-5c3c-a135-3e6fb7140632', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 19, 19, 'and what the land is that they dwell in, whether it is good or bad; and what cities they are that they dwell in, whether in camps, or in strongholds;'),
  ('1023194b-e3c4-526e-a0fa-d158989e09e9', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 20, 20, 'and what the land is, whether it is fat or lean, whether there is wood therein, or not. Be courageous, and bring of the fruit of the land. Now the time was the time of the first-ripe grapes."'),
  ('19dd32e4-d0f3-57cb-a169-6a1bdc7f549e', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 21, 21, 'So they went up, and spied out the land from the wilderness of Zin to Rehob, to the entrance of Hamath.'),
  ('28f3d1c9-0426-568d-a9d2-c0b27c141c70', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 22, 22, 'They went up by the South, and came to Hebron; and Ahiman, Sheshai, and Talmai, the children of Anak, were there. (Now Hebron was built seven years before Zoan in Egypt.)'),
  ('13ea3b9e-e286-5cd5-a508-1d7066ae8691', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 23, 23, 'They came to the valley of Eshcol, and cut down from there a branch with one cluster of grapes, and they bore it on a staff between two; [they brought] also of the pomegranates, and of the figs.'),
  ('7e822e6d-d00d-5426-a457-fc36eeb920f6', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 24, 24, 'That place was called the valley of Eshcol, because of the cluster which the children of Israel cut down from there.'),
  ('f69cf7e7-45e2-5b3c-a726-5ac62a8a42d8', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 25, 25, 'They returned from spying out the land at the end of forty days.'),
  ('99d9d1f6-02c1-5ff0-aed9-eb65adc5b42e', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 26, 26, 'They went and came to Moses, and to Aaron, and to all the congregation of the children of Israel, to the wilderness of Paran, to Kadesh; and brought back word to them, and to all the congregation, and showed them the fruit of the land.'),
  ('bb55d9fb-2792-5e22-abf8-0be9202cfbc5', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 27, 27, 'They told him, and said, "We came to the land where you sent us; and surely it flows with milk and honey; and this is its fruit.'),
  ('f2eee6e9-7e3e-539a-ac6b-5570adda05c1', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 28, 28, 'However the people who dwell in the land are strong, and the cities are fortified, [and] very great: and moreover we saw the children of Anak there.'),
  ('d1e91db8-b92b-5621-a107-071b7cbeeb48', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 29, 29, 'Amalek dwells in the land of the South: and the Hittite, and the Jebusite, and the Amorite, dwell in the hill country; and the Canaanite dwells by the sea, and along by the side of the Jordan."'),
  ('0b67b690-fa57-5c9c-aa0f-20c58b694263', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 30, 30, 'Caleb stilled the people before Moses, and said, "Let us go up at once, and possess it; for we are well able to overcome it."'),
  ('0a93e286-2a51-5778-a3b2-870169e83866', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 31, 31, 'But the men who went up with him said, "We aren''t able to go up against the people; for they are stronger than we."'),
  ('bca0bc19-1539-5c74-a7a3-5e3ec2ec6198', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 32, 32, 'They brought up an evil report of the land which they had spied out to the children of Israel, saying, "The land, through which we have gone to spy it out, is a land that eats up its inhabitants; and all the people who we saw in it are men of great stature.'),
  ('8ad7038c-43f3-5a8c-ab14-695d746a01d1', 'a98fc2d3-99e7-5f85-a679-f7752f169968', NULL, 33, 33, 'There we saw the Nephilim, the sons of Anak, who come of the Nephilim: and we were in our own sight as grasshoppers, and so we were in their sight."'),
  ('062b6095-817c-5534-a62b-e1d8be62871b', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 1, 1, 'All the congregation lifted up their voice, and cried; and the people wept that night.'),
  ('d7e654e5-5e86-5e4e-a402-3c8571593e62', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 2, 2, 'All the children of Israel murmured against Moses and against Aaron: and the whole congregation said to them, "Would that we had died in the land of Egypt! or would that we had died in this wilderness!')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('50983e4e-ec1e-5e0c-aeb4-5b9624617022', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 3, 3, 'Why does Yahweh bring us to this land, to fall by the sword? Our wives and our little ones will be a prey: wouldn''t it be better for us to return into Egypt?"'),
  ('ba7a081a-322d-5970-a679-fd02855c58e6', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 4, 4, 'They said one to another, "Let us make a captain, and let us return into Egypt."'),
  ('1195ee80-172a-54bd-ad4a-7464377f99c6', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 5, 5, 'Then Moses and Aaron fell on their faces before all the assembly of the congregation of the children of Israel.'),
  ('9a3a6d03-e0f2-55ba-a1b8-300fb4eeb7ea', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 6, 6, 'Joshua the son of Nun and Caleb the son of Jephunneh, who were of those who spied out the land, tore their clothes:'),
  ('07142205-9000-5500-a36d-9da89ef629c8', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 7, 7, 'and they spoke to all the congregation of the children of Israel, saying, "The land, which we passed through to spy it out, is an exceeding good land.'),
  ('ada22920-44cd-574a-a6aa-9377008f8c47', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 8, 8, 'If Yahweh delights in us, then he will bring us into this land, and give it to us; a land which flows with milk and honey.'),
  ('9d6d8341-e118-53cc-a475-31694c857610', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 9, 9, 'Only don''t rebel against Yahweh, neither fear the people of the land; for they are bread for us: their defense is removed from over them, and Yahweh is with us. Don''t fear them."'),
  ('12d501b5-6375-5f1a-a046-c8b303071622', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 10, 10, 'But all the congregation threatened to stone them with stones. The glory of Yahweh appeared in the Tent of Meeting to all the children of Israel.'),
  ('bd5b9f65-6c33-5f7c-a67d-9a97812524ae', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 11, 11, 'Yahweh said to Moses, "How long will this people despise me? and how long will they not believe in me, for all the signs which I have worked among them?'),
  ('e003694c-c16f-54dd-a32c-334c0511e7a0', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 12, 12, 'I will strike them with the pestilence, and disinherit them, and will make of you a nation greater and mightier than they."'),
  ('519a4825-2697-5ab3-a67e-d2ac6e107b58', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 13, 13, 'Moses said to Yahweh, "Then the Egyptians will hear it; for you brought up this people in your might from among them;'),
  ('a990cb24-c8d9-5038-aa6c-f2b7bf687798', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 14, 14, 'and they will tell it to the inhabitants of this land. They have heard that you Yahweh are in the midst of this people; for you Yahweh are seen face to face, and your cloud stands over them, and you go before them, in a pillar of cloud by day, and in a pillar of fire by night.'),
  ('8296f380-a919-5f2a-a966-d2754d3f1e5f', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 15, 15, 'Now if you killed this people as one man, then the nations which have heard the fame of you will speak, saying,'),
  ('53370f6c-310f-52f7-a65a-0c35d2cef695', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 16, 16, '''Because Yahweh was not able to bring this people into the land which he swore to them, therefore he has slain them in the wilderness.'''),
  ('ea22a1b3-0d6c-5590-ac79-51fdc36bb948', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 17, 17, 'Now please let the power of the Lord be great, according as you have spoken, saying,'),
  ('65fd75e1-feb5-5966-aa63-6ecec6551a76', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 18, 18, '''Yahweh is slow to anger, and abundant in loving kindness, forgiving iniquity and disobedience; and that will by no means clear [the guilty], visiting the iniquity of the fathers on the children, on the third and on the fourth generation.'''),
  ('2a62ad77-5b45-5671-a6bf-c3554280509e', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 19, 19, 'Please pardon the iniquity of this people according to the greatness of your loving kindness, and according as you have forgiven this people, from Egypt even until now."'),
  ('62ac3321-4f45-5f36-ab13-3881a2d9d2bf', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 20, 20, 'Yahweh said, "I have pardoned according to your word:'),
  ('c63709db-da06-52de-ad4e-07f7c4d4decb', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 21, 21, 'but in very deed, as I live, and as all the earth shall be filled with the glory of Yahweh;'),
  ('9026ce81-e601-5613-a9e2-dc58314250a3', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 22, 22, 'because all those men who have seen my glory, and my signs, which I worked in Egypt and in the wilderness, yet have tempted me these ten times, and have not listened to my voice;'),
  ('f530471a-4d75-5347-a628-a8312b56f32e', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 23, 23, 'surely they shall not see the land which I swore to their fathers, neither shall any of those who despised me see it:'),
  ('21975fb5-2a4f-56fa-aa40-5e20d60ac340', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 24, 24, 'but my servant Caleb, because he had another spirit with him, and has followed me fully, him will I bring into the land into which he went; and his seed shall possess it.'),
  ('ca206c81-44a9-5c37-a46b-5ffe5f827c56', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 25, 25, 'Now the Amalekite and the Canaanite dwell in the valley: tomorrow turn, and go into the wilderness by the way to the Red Sea."'),
  ('cb0c83e3-9b11-578e-ae5f-43fd2fd9c445', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 26, 26, 'Yahweh spoke to Moses and to Aaron, saying,'),
  ('55f6495b-9d88-5058-af48-72bb0109b7cc', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 27, 27, '"How long [shall I bear] with this evil congregation, that murmur against me? I have heard the murmurings of the children of Israel, which they murmur against me.'),
  ('b194464d-b6ca-58a0-a999-d51a00342a17', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 28, 28, 'Tell them, ''As I live, says Yahweh, surely as you have spoken in my ears, so will I do to you:'),
  ('f26d5660-860b-5b2c-a432-683eef061b98', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 29, 29, 'your dead bodies shall fall in this wilderness; and all who were numbered of you, according to your whole number, from twenty years old and upward, who have murmured against me,'),
  ('c74bcf0b-ec9b-5fa3-aad4-ccdc7f8aa9c3', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 30, 30, 'surely you shall not come into the land, concerning which I swore that I would make you dwell therein, except Caleb the son of Jephunneh, and Joshua the son of Nun.'),
  ('98b3314d-a4ea-56a2-a9c0-4dfd9008af62', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 31, 31, 'But your little ones, that you said should be a prey, them will I bring in, and they shall know the land which you have rejected.'),
  ('60ada058-a600-5972-a2fd-fcf99e99e6bc', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 32, 32, 'But as for you, your dead bodies shall fall in this wilderness.'),
  ('57c1e19b-b126-560f-abda-aa8ad30a6544', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 33, 33, 'Your children shall be wanderers in the wilderness forty years, and shall bear your prostitution, until your dead bodies be consumed in the wilderness.'),
  ('c0e90e51-4fbe-5a28-a35c-cd0e74e2714c', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 34, 34, 'After the number of the days in which you spied out the land, even forty days, for every day a year, you will bear your iniquities, even forty years, and you will know my alienation.'''),
  ('c292f5e1-8a06-50e7-ad2d-bef3d237dc66', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 35, 35, 'I, Yahweh, have spoken, surely this will I do to all this evil congregation, who are gathered together against me: in this wilderness they shall be consumed, and there they shall die."'),
  ('614e28a1-204d-5317-a192-efca02d6e1d1', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 36, 36, 'The men, whom Moses sent to spy out the land, who returned, and made all the congregation to murmur against him, by bringing up an evil report against the land,'),
  ('a4b4cce3-6f17-5a61-ac78-f4c9d0655422', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 37, 37, 'even those men who did bring up an evil report of the land, died by the plague before Yahweh.'),
  ('e4a21711-2842-5614-a4e0-457fef10fc9d', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 38, 38, 'But Joshua the son of Nun, and Caleb the son of Jephunneh, remained alive of those men who went to spy out the land.'),
  ('97bd9986-2897-530e-a6a4-9e49eb1493f3', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 39, 39, 'Moses told these words to all the children of Israel: and the people mourned greatly.'),
  ('957c3f15-fe76-53c9-ab2e-4561cdf6b7c9', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 40, 40, 'They rose up early in the morning, and went up to the top of the mountain, saying, "Behold, we are here, and will go up to the place which Yahweh has promised: for we have sinned."'),
  ('e629bef5-706e-5a73-a388-73ec91ddfaa5', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 41, 41, 'Moses said, "Why now do you disobey the commandment of Yahweh, since it shall not prosper?'),
  ('cedd53bb-b14e-5345-a952-a3a54d6989a3', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 42, 42, 'Don''t go up, for Yahweh isn''t among you; that you not be struck down before your enemies.'),
  ('290f1fd8-e57d-589e-ac58-3258695bbb7f', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 43, 43, 'For there the Amalekite and the Canaanite are before you, and you shall fall by the sword: because you are turned back from following Yahweh, therefore Yahweh will not be with you."'),
  ('69bf3856-65fc-599f-abd7-4eb9bf320b59', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 44, 44, 'But they presumed to go up to the top of the mountain: nevertheless the ark of the covenant of Yahweh, and Moses, didn''t depart out of the camp.'),
  ('a665426e-73ce-5ba5-abad-212b12174cb3', '632cc15d-2d96-5bee-a323-5f5693e88269', NULL, 45, 45, 'Then the Amalekite came down, and the Canaanite who lived in that mountain, and struck them and beat them down, even to Hormah.'),
  ('b6f1aac9-9766-5df6-a13b-13cba079e02c', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('5f20067f-8c1f-508b-a3d5-98a1eff0ae37', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 2, 2, '"Speak to the children of Israel, and tell them, ''When you have come into the land of your habitations, which I give to you,'),
  ('2777075e-c0e2-5137-a33b-2dc40e533edc', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 3, 3, 'and will make an offering by fire to Yahweh, a burnt offering, or a sacrifice, to accomplish a vow, or as a freewill offering, or in your set feasts, to make a pleasant aroma to Yahweh, of the herd, or of the flock;'),
  ('a873a8a5-f808-5c8f-a140-8b2a78b38955', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 4, 4, 'then he who offers his offering shall offer to Yahweh a meal offering of a tenth part [of an ephah] of fine flour mixed with the fourth part of a hin of oil:'),
  ('79af663f-68d5-5382-a657-c931bf097492', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 5, 5, 'and wine for the drink offering, the fourth part of a hin, you shall prepare with the burnt offering, or for the sacrifice, for each lamb.'),
  ('90ab55f0-3a5b-5747-a65a-50938a36e819', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 6, 6, '"''Or for a ram, you shall prepare for a meal offering two tenth parts [of an ephah] of fine flour mixed with the third part of a hin of oil:'),
  ('94bee6c0-80c5-58bb-a705-71b57a209d38', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 7, 7, 'and for the drink offering you shall offer the third part of a hin of wine, of a pleasant aroma to Yahweh.'),
  ('d0b6826d-e732-5917-a2f4-5629f895bf72', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 8, 8, 'When you prepare a bull for a burnt offering, or for a sacrifice, to accomplish a vow, or for peace offerings to Yahweh;'),
  ('963e2f5c-102e-5ea1-a1fe-4722e93c4506', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 9, 9, 'then shall he offer with the bull a meal offering of three tenth parts [of an ephah] of fine flour mixed with half a hin of oil:'),
  ('f7f49058-bb58-548a-a4ce-d7b47c59f4c7', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 10, 10, 'and you shall offer for the drink offering half a hin of wine, for an offering made by fire, of a pleasant aroma to Yahweh.'),
  ('a356197a-0347-5831-a1ec-e18e8363e0e8', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 11, 11, 'Thus shall it be done for each bull, or for each ram, or for each of the male lambs, or of the young goats.'),
  ('8bbb605f-a03d-56b0-a81b-b49f7fdf5dbe', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 12, 12, 'According to the number that you shall prepare, so you shall do to everyone according to their number.'),
  ('8cd70e8d-a458-5a24-a6ba-796b7fe9d65b', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 13, 13, '"''All who are native-born shall do these things in this way, in offering an offering made by fire, of a pleasant aroma to Yahweh.'),
  ('d1212145-dc02-5faf-a159-55f2e5b56cd4', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 14, 14, 'If a stranger lives as a foreigner with you, or whoever may be among you throughout your generations, and will offer an offering made by fire, of a pleasant aroma to Yahweh; as you do, so he shall do.'),
  ('8713e810-fd90-5679-ab21-d48225e3c3ae', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 15, 15, 'For the assembly, there shall be one statute for you, and for the stranger who lives as a foreigner [with you], a statute forever throughout your generations: as you are, so shall the foreigner be before Yahweh.'),
  ('c4b02267-d745-5bb7-a2e4-9c4c5fac8c98', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 16, 16, 'One law and one ordinance shall be for you, and for the stranger who lives as a foreigner with you.''"'),
  ('814c3449-b660-52fc-a135-2a014b80fb31', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 17, 17, 'Yahweh spoke to Moses, saying,'),
  ('5124ce75-39b2-5453-ae85-27ad1de2fff4', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 18, 18, '"Speak to the children of Israel, and tell them, ''When you come into the land where I bring you,'),
  ('f542df51-5962-5b1b-a16e-8959aac9e3b2', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 19, 19, 'then it shall be that when you eat of the bread of the land, you shall offer up a wave offering to Yahweh.'),
  ('9ff3350e-cfe0-5bc3-a756-f81cc1bfd797', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 20, 20, 'Of the first of your dough you shall offer up a cake for a wave offering: as the wave offering of the threshing floor, so you shall heave it.'),
  ('d13b1378-2fec-5673-a465-0e42e9af4de0', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 21, 21, 'Of the first of your dough you shall give to Yahweh a wave offering throughout your generations.'),
  ('3a1c0104-9209-5e66-a74f-5ba51096996e', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 22, 22, '"''When you shall err, and not observe all these commandments, which Yahweh has spoken to Moses,'),
  ('fa647572-5052-5a71-a9e6-3161fcda06f6', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 23, 23, 'even all that Yahweh has commanded you by Moses, from the day that Yahweh gave commandment, and onward throughout your generations;'),
  ('2ee5799d-bfbc-54f6-ab6a-727aa8cd507b', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 24, 24, 'then it shall be, if it be done unwittingly, without the knowledge of the congregation, that all the congregation shall offer one young bull for a burnt offering, for a pleasant aroma to Yahweh, with the meal offering of it, and the drink offering of it, according to the ordinance, and one male goat for a sin offering.'),
  ('853cf759-74d0-5d7d-a007-7ff42fba4282', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 25, 25, 'The priest shall make atonement for all the congregation of the children of Israel, and they shall be forgiven; for it was an error, and they have brought their offering, an offering made by fire to Yahweh, and their sin offering before Yahweh, for their error:'),
  ('86da216d-ea1f-5721-a515-df8b02a96882', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 26, 26, 'and all the congregation of the children of Israel shall be forgiven, and the stranger who lives as a foreigner among them; for in respect of all the people it was done unwittingly.'),
  ('e7fe8424-329a-571a-ae26-a0ae154c9582', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 27, 27, '"''If one person sins unwittingly, then he shall offer a female goat a year old for a sin offering.'),
  ('caa86f83-692b-5176-a041-2c1a33bc4877', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 28, 28, 'The priest shall make atonement for the soul who errs, when he sins unwittingly, before Yahweh, to make atonement for him; and he shall be forgiven.'),
  ('cf752e9e-072c-5207-a2bb-ef9b916c140e', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 29, 29, 'You shall have one law for him who does anything unwittingly, for him who is native-born among the children of Israel, and for the stranger who lives as a foreigner among them.'),
  ('18f95f53-6e74-5c8a-a2d5-40f358a54f63', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 30, 30, '"''But the soul who does anything with a high hand, whether he is native-born or a foreigner, the same blasphemes Yahweh; and that soul shall be cut off from among his people.'),
  ('e54155ef-8267-51db-adbb-060e58866dfc', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 31, 31, 'Because he has despised the word of Yahweh, and has broken his commandment, that soul shall utterly be cut off; his iniquity shall be on him.''"'),
  ('bbf001f4-9f4b-525b-abc7-f2edaf848b02', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 32, 32, 'While the children of Israel were in the wilderness, they found a man gathering sticks on the Sabbath day.'),
  ('3b626711-1ba4-54c8-ae45-1a5c1097bc16', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 33, 33, 'Those who found him gathering sticks brought him to Moses and Aaron, and to all the congregation.'),
  ('6cf71e1a-d033-5edf-a79e-42e7852993bb', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 34, 34, 'They put him in custody, because it had not been declared what should be done to him.'),
  ('8e25d7a6-c8b6-53f4-a729-f5bdcb399f7c', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 35, 35, 'Yahweh said to Moses, "The man shall surely be put to death: all the congregation shall stone him with stones outside of the camp."'),
  ('dc16799a-3c01-558b-aeef-5f842751be79', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 36, 36, 'All the congregation brought him outside of the camp, and stoned him to death with stones; as Yahweh commanded Moses.'),
  ('3df2c64a-54dd-5e83-a839-91a28e58d01a', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 37, 37, 'Yahweh spoke to Moses, saying,'),
  ('d8da18d6-5b41-5b2a-aebf-9da2b7824a94', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 38, 38, '"Speak to the children of Israel, and tell them that they should make themselves fringes in the borders of their garments throughout their generations, and that they put on the fringe of each border a cord of blue:'),
  ('624a8add-4919-52d1-ae9a-879f47743ad1', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 39, 39, 'and it shall be to you for a fringe, that you may look on it, and remember all the commandments of Yahweh, and do them; and that you not follow after your own heart and your own eyes, after which you use to play the prostitute;'),
  ('67292f30-5059-5bfb-a961-e4708e163f15', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 40, 40, 'that you may remember and do all my commandments, and be holy to your God.'),
  ('3f07bcf8-e959-5b37-a773-2fbe58314059', '17ba08f8-04ec-5196-a92b-cfc6a999f232', NULL, 41, 41, 'I am Yahweh your God, who brought you out of the land of Egypt, to be your God: I am Yahweh your God."'),
  ('110cd90e-d1b1-5b8e-a3c9-124f1f01ba7d', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 1, 1, 'Now Korah, the son of Izhar, the son of Kohath, the son of Levi, with Dathan and Abiram, the sons of Eliab, and On, the son of Peleth, sons of Reuben, took [men]:'),
  ('03df4cf4-3912-5719-a640-1a84ee1c0725', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 2, 2, 'and they rose up before Moses, with certain of the children of Israel, two hundred fifty princes of the congregation, called to the assembly, men of renown;'),
  ('45032756-3ac3-51d2-a2da-98af52137870', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 3, 3, 'and they assembled themselves together against Moses and against Aaron, and said to them, "You take too much on yourself, since all the congregation are holy, everyone of them, and Yahweh is among them: why then lift yourselves up above the assembly of Yahweh?"'),
  ('078f379e-2ece-5426-a00c-97c0271967c3', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 4, 4, 'When Moses heard it, he fell on his face:'),
  ('30811998-39da-535b-acf5-7b088165c5f6', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 5, 5, 'and he spoke to Korah and to all his company, saying, "In the morning Yahweh will show who are his, and who is holy, and will cause him to come near to him: even him whom he shall choose he will cause to come near to him.'),
  ('4b7fcadf-77c0-5aec-a03e-fd67cfcef90a', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 6, 6, 'Do this: take censers, Korah, and all his company;'),
  ('f2442015-86b6-5482-ac93-d366d21a6147', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 7, 7, 'and put fire in them, and put incense on them before Yahweh tomorrow: and it shall be that the man whom Yahweh chooses, he shall be holy. You have gone too far, you sons of Levi!"'),
  ('28f4d229-e85b-5a19-ac5e-aa6d67bca6f0', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 8, 8, 'Moses said to Korah, "Hear now, you sons of Levi!'),
  ('d691ee97-75c7-5839-a10a-0aa5e76284a6', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 9, 9, 'Is it a small thing to you, that the God of Israel has separated you from the congregation of Israel, to bring you near to himself, to do the service of the tabernacle of Yahweh, and to stand before the congregation to minister to them;'),
  ('3f044b28-73e1-568d-ac74-9e0cdbdb2a05', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 10, 10, 'and that he has brought you near, and all your brothers the sons of Levi with you? and do you seek the priesthood also?'),
  ('8abc3c59-dda4-5165-a1c2-acb267e7bbad', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 11, 11, 'Therefore you and all your company are gathered together against Yahweh: and Aaron, what is he that you murmur against him?"'),
  ('abe7c936-f398-5d1c-a46f-a30a1e79d87d', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 12, 12, 'Moses sent to call Dathan and Abiram, the sons of Eliab; and they said, "We won''t come up:'),
  ('08dfe22c-df24-5f7f-a586-c882e7843b49', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 13, 13, 'is it a small thing that you have brought us up out of a land flowing with milk and honey, to kill us in the wilderness, but you must also make yourself a prince over us?'),
  ('6e4aeab5-8b5e-58aa-abee-3051abfa73e2', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 14, 14, 'Moreover you haven''t brought us into a land flowing with milk and honey, nor given us inheritance of fields and vineyards: will you put out the eyes of these men? We won''t come up."'),
  ('ba2dd041-1465-5ff6-a416-b9124ab397b6', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 15, 15, 'Moses was very angry, and said to Yahweh, "Don''t respect their offering: I have not taken one donkey from them, neither have I hurt one of them."'),
  ('5c58e956-cd89-5a5a-a8b6-ab9e70230e2b', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 16, 16, 'Moses said to Korah, "You and all your company go before Yahweh, you, and they, and Aaron, tomorrow:'),
  ('9ee5c277-538e-5d9c-a1b6-0c502cbcd03e', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 17, 17, 'and each man take his censer, and put incense on them, and each man bring before Yahweh his censer, two hundred fifty censers; you also, and Aaron, each his censer."'),
  ('ec7be4d8-705f-56ad-ae80-406e02d91c62', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 18, 18, 'They each took his censer, and put fire in them, and laid incense thereon, and stood at the door of the Tent of Meeting with Moses and Aaron.'),
  ('f7f6e4ae-7394-580d-a68e-588501ba3771', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 19, 19, 'Korah assembled all the congregation against them to the door of the Tent of Meeting: and the glory of Yahweh appeared to all the congregation.'),
  ('4b96eabf-0411-565c-af31-f060713661e0', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 20, 20, 'Yahweh spoke to Moses and to Aaron, saying,'),
  ('f89ebbe5-0776-57e6-adda-f0e05cdc6810', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 21, 21, '"Separate yourselves from among this congregation, that I may consume them in a moment!"'),
  ('840d11fb-1988-5ac6-abca-cf22663e4bfd', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 22, 22, 'They fell on their faces, and said, "God, the God of the spirits of all flesh, shall one man sin, and will you be angry with all the congregation?"'),
  ('61c2bf80-acd1-577e-a3a3-09d6b4aecad5', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 23, 23, 'Yahweh spoke to Moses, saying,'),
  ('6449c79c-8edf-5561-ad68-8eef61709ac4', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 24, 24, '"Speak to the congregation, saying, ''Get away from around the tent of Korah, Dathan, and Abiram!''"'),
  ('a77791f7-806c-542d-a7fc-cc7f38058fcc', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 25, 25, 'Moses rose up and went to Dathan and Abiram; and the elders of Israel followed him.'),
  ('fb1b6eba-48ae-56f2-a5fb-a1ea8ae5829d', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 26, 26, 'He spoke to the congregation, saying, "Depart, please, from the tents of these wicked men, and touch nothing of theirs, lest you be consumed in all their sins!"'),
  ('58362ae8-1898-5430-aa38-89ed9b6e0e34', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 27, 27, 'So they went away from the tent of Korah, Dathan, and Abiram, on every side: and Dathan and Abiram came out, and stood at the door of their tents, and their wives, and their sons, and their little ones.'),
  ('0a51f993-80e6-566d-a01e-30e62916b180', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 28, 28, 'Moses said, "Hereby you shall know that Yahweh has sent me to do all these works; for [I have] not [done them] of my own mind.'),
  ('f48acab3-134b-55c4-ad37-a9f3ff065ad4', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 29, 29, 'If these men die the common death of all men, or if they be visited after the visitation of all men; then Yahweh hasn''t sent me.'),
  ('03861c3c-4321-570a-a470-41bc0dfb3499', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 30, 30, 'But if Yahweh make a new thing, and the ground open its mouth, and swallow them up, with all that appertain to them, and they go down alive into Sheol; then you shall understand that these men have despised Yahweh."'),
  ('c31071c4-441e-54f5-a512-785c28601eeb', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 31, 31, 'It happened, as he made an end of speaking all these words, that the ground split apart that was under them;'),
  ('97b484ca-e7be-5bb8-a21e-c6ecb4bc6b41', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 32, 32, 'and the earth opened its mouth, and swallowed them up, and their households, and all the men who appertained to Korah, and all their goods.'),
  ('237e1c80-ed90-54b0-a64e-1a03b718c9f6', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 33, 33, 'So they, and all that appertained to them, went down alive into Sheol: and the earth closed on them, and they perished from among the assembly.'),
  ('18acf328-adbf-5911-a88a-61c44d89ac33', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 34, 34, 'All Israel that were around them fled at the cry of them; for they said, "Lest the earth swallow us up!"'),
  ('0a70f3f8-5ae3-554b-ad9e-c3531e3f2546', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 35, 35, 'Fire came forth from Yahweh, and devoured the two hundred fifty men who offered the incense.'),
  ('2ab9ace6-4616-5bbd-a074-cd4dc7654e7e', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 36, 36, 'Yahweh spoke to Moses, saying,'),
  ('a8642b3f-6d06-566b-a65c-e81c68e1703c', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 37, 37, '"Speak to Eleazar the son of Aaron the priest, that he take up the censers out of the burning, and scatter the fire yonder; for they are holy,'),
  ('cbf390ed-d82b-51b1-aaff-1fa18dd52110', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 38, 38, 'even the censers of these sinners against their own lives; and let them be made beaten plates for a covering of the altar: for they offered them before Yahweh; therefore they are holy; and they shall be a sign to the children of Israel."'),
  ('36df9c4c-6184-563c-a092-f5487e17d43d', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 39, 39, 'Eleazar the priest took the bronze censers, which those who were burnt had offered; and they beat them out for a covering of the altar,'),
  ('613fdd05-d1a0-569c-a729-f315a8318554', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 40, 40, 'to be a memorial to the children of Israel, to the end that no stranger, who isn''t of the seed of Aaron, comes near to burn incense before Yahweh; that he not be as Korah, and as his company: as Yahweh spoke to him by Moses.'),
  ('d48c8f5f-8914-5e16-a060-06b71c644509', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 41, 41, 'But on the next day all the congregation of the children of Israel murmured against Moses and against Aaron, saying, "You have killed Yahweh''s people!"'),
  ('a440e5a5-133a-55b6-a7d6-4116ed4ebaf5', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 42, 42, 'It happened, when the congregation was assembled against Moses and against Aaron, that they looked toward the Tent of Meeting: and behold, the cloud covered it, and the glory of Yahweh appeared.'),
  ('2e3f51c2-d8de-58d5-a371-a0db1121f93e', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 43, 43, 'Moses and Aaron came to the front of the Tent of Meeting.'),
  ('80c20653-e507-52d7-aa71-b9f54f3c9f07', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 44, 44, 'Yahweh spoke to Moses, saying,'),
  ('c9f13780-8bb2-527d-ad4c-202656cfcb41', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 45, 45, '"Get away from among this congregation, that I may consume them in a moment!" They fell on their faces.'),
  ('43875ede-eb0f-5a5e-a8fe-5c0593fc31b5', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 46, 46, 'Moses said to Aaron, "Take your censer, and put fire from off the altar in it, and lay incense on it, and carry it quickly to the congregation, and make atonement for them; for wrath has gone out from Yahweh! The plague has begun."'),
  ('c1d676f0-a0d5-57e0-a6d8-1cffde04f01e', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 47, 47, 'Aaron did as Moses said, and ran into the midst of the assembly; and behold, the plague has begun among the people: and he put on the incense, and made atonement for the people.'),
  ('dfb96cf0-79ca-5d86-ab20-c7ccb3639ade', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 48, 48, 'He stood between the dead and the living; and the plague was stayed.'),
  ('879de0ec-7359-5ef8-a371-7de0fd51a3fb', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 49, 49, 'Now those who died by the plague were fourteen thousand and seven hundred, besides those who died about the matter of Korah.'),
  ('e9578b4f-209c-501c-a1c1-337e8e0a7114', 'f8ac98a7-14b5-5b15-ab1c-bed61409ca25', NULL, 50, 50, 'Aaron returned to Moses to the door of the Tent of Meeting: and the plague was stayed.'),
  ('739436a1-ca75-5010-a806-dd8d73556f9b', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('263cdde0-bfaf-5120-ae80-67a159bfe3f9', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 2, 2, '"Speak to the children of Israel, and take of them rods, one for each fathers'' house, of all their princes according to their fathers'' houses, twelve rods: write every man''s name on his rod.'),
  ('0b8d40dc-6688-5585-a721-7e5ee6da3346', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 3, 3, 'You shall write Aaron''s name on the rod of Levi; for there shall be one rod for each head of their fathers'' houses.'),
  ('10d78670-3e93-5abb-a96a-2ae8f04f44e7', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 4, 4, 'You shall lay them up in the Tent of Meeting before the testimony, where I meet with you.'),
  ('129ef939-6aa0-54a4-a52b-695232267d43', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 5, 5, 'It shall happen, that the rod of the man whom I shall choose shall bud: and I will make to cease from me the murmurings of the children of Israel, which they murmur against you."'),
  ('a4aa0fc5-2b95-5998-a5c7-bdab305418f0', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 6, 6, 'Moses spoke to the children of Israel; and all their princes gave him rods, for each prince one, according to their fathers'' houses, even twelve rods: and the rod of Aaron was among their rods.'),
  ('83649c4d-ebff-5f8d-aaab-faa5fed979c6', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 7, 7, 'Moses laid up the rods before Yahweh in the tent of the testimony.'),
  ('e2fda104-2622-505a-ad5c-a3044d071076', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 8, 8, 'It happened on the next day, that Moses went into the tent of the testimony; and behold, the rod of Aaron for the house of Levi was budded, and put forth buds, and produced blossoms, and bore ripe almonds.'),
  ('81d10462-cc68-5b49-a617-831eb6bedc78', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 9, 9, 'Moses brought out all the rods from before Yahweh to all the children of Israel: and they looked, and took every man his rod.'),
  ('b4fb00be-4de6-53f8-a7e7-7d8e0c2b3045', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 10, 10, 'Yahweh said to Moses, "Put back the rod of Aaron before the testimony, to be kept for a token against the children of rebellion; that you may make an end of their murmurings against me, that they not die."'),
  ('6a0a30fd-d0e7-545e-a30e-1409a5a9120f', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 11, 11, 'Moses did so. As Yahweh commanded him, so he did.'),
  ('1398162d-b0b3-50d9-a44c-8c3ffa27070f', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 12, 12, 'The children of Israel spoke to Moses, saying, "Behold, we perish! We are undone! We are all undone!'),
  ('88e41f3a-fa94-54d3-a460-d16c86bf20c8', 'ad22841d-f8a3-5079-a5cd-4ce880a9e1e3', NULL, 13, 13, 'Everyone who comes near, who comes near to the tabernacle of Yahweh, dies! Will we all perish?"'),
  ('d1d4d476-4ad0-5e95-ad64-0588e2dee8e4', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 1, 1, 'Yahweh said to Aaron, "You and your sons and your fathers'' house with you shall bear the iniquity of the sanctuary; and you and your sons with you shall bear the iniquity of your priesthood.'),
  ('f8c589d2-ccbd-5ddf-a075-fd9976b8b0bb', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 2, 2, 'Your brothers also, the tribe of Levi, the tribe of your father, bring near with you, that they may be joined to you, and minister to you: but you and your sons with you shall be before the tent of the testimony.'),
  ('7f6043ab-c3ea-5103-a063-a1c11b99ed9a', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 3, 3, 'They shall keep your commands, and the duty of all the Tent: only they shall not come near to the vessels of the sanctuary and to the altar, that they not die, neither they, nor you.'),
  ('bc3a49ca-258a-5cab-a85a-36e1a338e2f5', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 4, 4, 'They shall be joined to you, and keep the responsibility of the Tent of Meeting, for all the service of the Tent: and a stranger shall not come near to you.'),
  ('b7298ae2-119f-57a2-adbc-236a732ec0b9', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 5, 5, '"You shall perform the duty of the sanctuary, and the duty of the altar; that there be wrath no more on the children of Israel.'),
  ('0e8d528b-551e-5527-a28e-bf9688b1cc63', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 6, 6, 'I, behold, I have taken your brothers the Levites from among the children of Israel: to you they are a gift, given to Yahweh, to do the service of the Tent of Meeting.'),
  ('a024bb99-c213-58df-a3ca-10c7c2b68b3a', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 7, 7, 'You and your sons with you shall keep your priesthood for everything of the altar, and for that within the veil; and you shall serve: I give you the priesthood as a service of gift: and the stranger who comes near shall be put to death."'),
  ('76281f54-4137-571e-a0e0-d52a121c196a', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 8, 8, 'Yahweh spoke to Aaron, "I, behold, I have given you the command of my wave offerings, even all the holy things of the children of Israel; to you have I given them by reason of the anointing, and to your sons, as a portion forever.'),
  ('670e8cb3-0b64-55e7-a5ed-17fa7c526933', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 9, 9, 'This shall be yours of the most holy things, [reserved] from the fire: every offering of theirs, even every meal offering of theirs, and every sin offering of theirs, and every trespass offering of theirs, which they shall render to me, shall be most holy for you and for your sons.'),
  ('98828696-e9ba-5749-ad3f-2eb205335f9b', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 10, 10, 'You shall eat of it like the most holy things. Every male shall eat of it. It shall be holy to you.'),
  ('75723441-531b-545d-a33d-06250e6af665', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 11, 11, '"This is yours, too: the wave offering of their gift, even all the wave offerings of the children of Israel. I have given them to you, and to your sons and to your daughters with you, as a portion forever. Everyone who is clean in your house shall eat of it.'),
  ('e081baaf-1637-5f94-ad15-4854df5ac6dc', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 12, 12, '"All the best of the oil, and all the best of the vintage, and of the grain, the first fruits of them which they give to Yahweh, to you have I given them.'),
  ('fe6877b0-a0bb-55cb-a8df-6e36da644b27', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 13, 13, 'The first-ripe fruits of all that is in their land, which they bring to Yahweh, shall be yours; everyone who is clean in your house shall eat of it.'),
  ('b416355c-7371-54db-a4ee-5e214d2534b8', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 14, 14, '"Everything devoted in Israel shall be yours.'),
  ('26bae4c8-5abf-5afa-a9b1-dc101585dc8b', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 15, 15, 'Everything that opens the womb, of all flesh which they offer to Yahweh, both of man and animal shall be yours: nevertheless you shall surely redeem the firstborn of man, and you shall redeem the firstborn of unclean animals.'),
  ('c181f106-c252-5b42-ae7d-648cd6b6529c', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 16, 16, 'You shall redeem those who are to be redeemed of them from a month old, according to your estimation, for five shekels of money, after the shekel of the sanctuary (the same is twenty gerahs).'),
  ('9d4f6aa5-8ace-53bd-a2de-8b1811189464', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 17, 17, '"But you shall not redeem the firstborn of a cow, or the firstborn of a sheep, or the firstborn of a goat. They are holy. You shall sprinkle their blood on the altar, and shall burn their fat for an offering made by fire, for a pleasant aroma to Yahweh.'),
  ('a2c7d3ed-31df-5dc0-aea1-49edf96b749a', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 18, 18, 'Their flesh shall be yours, as the wave offering breast and as the right thigh, it shall be yours.'),
  ('87039c8b-c725-5962-a289-914c3cda2e81', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 19, 19, 'All the wave offerings of the holy things, which the children of Israel offer to Yahweh, have I given you, and your sons and your daughters with you, as a portion forever: it is a covenant of salt forever before Yahweh to you and to your seed with you."'),
  ('d83b09ba-4ecb-5909-a18c-97d8fd7da9a0', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 20, 20, 'Yahweh said to Aaron, "You shall have no inheritance in their land, neither shall you have any portion among them. I am your portion and your inheritance among the children of Israel.'),
  ('a2325f14-5cd7-5e5e-ac4a-4e686896165f', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 21, 21, '"To the children of Levi, behold, I have given all the tithe in Israel for an inheritance, in return for their service which they serve, even the service of the Tent of Meeting.'),
  ('fa91633f-82a9-50ef-a587-ca5d62de5cc7', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 22, 22, 'Henceforth the children of Israel shall not come near the Tent of Meeting, lest they bear sin, and die.'),
  ('5c6e340b-1004-57ee-a5bd-68d3158dad68', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 23, 23, 'But the Levites shall do the service of the Tent of Meeting, and they shall bear their iniquity: it shall be a statute forever throughout your generations; and among the children of Israel they shall have no inheritance.'),
  ('d31ae230-1dd3-509e-ac80-cb6ac0674694', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 24, 24, 'For the tithe of the children of Israel, which they offer as a wave offering to Yahweh, I have given to the Levites for an inheritance: therefore I have said to them, ''Among the children of Israel they shall have no inheritance.''"'),
  ('e73ab1ab-fd08-5af7-a937-b2d2e7210b32', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 25, 25, 'Yahweh spoke to Moses, saying,'),
  ('bf5473f1-15d4-56e1-ab3d-ffcb8ca514f2', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 26, 26, '"Moreover you shall speak to the Levites, and tell them, ''When you take of the children of Israel the tithe which I have given you from them for your inheritance, then you shall offer up a wave offering of it for Yahweh, a tithe of the tithe.'),
  ('22762aff-d428-56b1-a467-88222603bba7', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 27, 27, 'Your wave offering shall be reckoned to you, as though it were the grain of the threshing floor, and as the fullness of the winepress.'),
  ('ee032f42-5f78-5932-af96-fc2a155449cc', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 28, 28, 'Thus you also shall offer a wave offering to Yahweh of all your tithes, which you receive of the children of Israel; and of it you shall give Yahweh''s wave offering to Aaron the priest.'),
  ('229fab68-e375-5d5c-a8c9-11614abb0a00', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 29, 29, 'Out of all your gifts you shall offer every wave offering of Yahweh, of all its best, even the holy part of it out of it.'''),
  ('38c32f89-2a76-5a95-a053-d679df71d902', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 30, 30, '"Therefore you shall tell them, ''When you heave its best from it, then it shall be reckoned to the Levites as the increase of the threshing floor, and as the increase of the winepress.'),
  ('86652f20-b4cb-5ac3-a015-f94ae1bf971c', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 31, 31, 'You shall eat it in every place, you and your households: for it is your reward in return for your service in the Tent of Meeting.'),
  ('c7010030-fff5-540f-a4cc-24037058269d', '3e89238b-7670-5d1a-a389-b4662398b856', NULL, 32, 32, 'You shall bear no sin by reason of it, when you have heaved from it its best: and you shall not profane the holy things of the children of Israel, that you not die.''"'),
  ('ce4c3399-573f-56d6-a16a-fec918288dd2', '108785b4-6816-5246-af31-503feb886ae9', NULL, 1, 1, 'Yahweh spoke to Moses and to Aaron, saying,'),
  ('59b9061e-6744-55f0-a849-c9cfb1626fd1', '108785b4-6816-5246-af31-503feb886ae9', NULL, 2, 2, '"This is the statute of the law which Yahweh has commanded: Speak to the children of Israel, that they bring you a red heifer without spot, in which is no blemish, [and] on which never came yoke.'),
  ('37ecc323-2e1b-5044-a705-79e90b19a802', '108785b4-6816-5246-af31-503feb886ae9', NULL, 3, 3, 'You shall give her to Eleazar the priest, and he shall bring her forth outside of the camp, and one shall kill her before his face:'),
  ('cbd5b63d-42f5-506c-a4d6-3a9140a5cf8f', '108785b4-6816-5246-af31-503feb886ae9', NULL, 4, 4, 'and Eleazar the priest shall take of her blood with his finger, and sprinkle her blood toward the front of the Tent of Meeting seven times.'),
  ('c5408409-dee3-5258-ad29-d8b672b98e24', '108785b4-6816-5246-af31-503feb886ae9', NULL, 5, 5, 'One shall burn the heifer in his sight; her skin, and her flesh, and her blood, with her dung, shall he burn:'),
  ('817d7b15-8655-5f84-abb1-3667e8373dfa', '108785b4-6816-5246-af31-503feb886ae9', NULL, 6, 6, 'and the priest shall take cedar wood, and hyssop, and scarlet, and cast it into the midst of the burning of the heifer.'),
  ('430124e0-d3f9-54ff-a3be-a9c9b72f0da8', '108785b4-6816-5246-af31-503feb886ae9', NULL, 7, 7, 'Then the priest shall wash his clothes, and he shall bathe his flesh in water, and afterward he shall come into the camp, and the priest shall be unclean until the evening.'),
  ('4013c5a6-8611-5d01-a456-4f9455ed532e', '108785b4-6816-5246-af31-503feb886ae9', NULL, 8, 8, 'He who burns her shall wash his clothes in water, and bathe his flesh in water, and shall be unclean until the evening.'),
  ('d6944b82-d732-59b4-a75f-7ffe281d2352', '108785b4-6816-5246-af31-503feb886ae9', NULL, 9, 9, '"A man who is clean shall gather up the ashes of the heifer, and lay them up outside of the camp in a clean place; and it shall be kept for the congregation of the children of Israel for a water for impurity: it is a sin offering.'),
  ('686435c1-97eb-5001-a91d-4d82181b7060', '108785b4-6816-5246-af31-503feb886ae9', NULL, 10, 10, 'He who gathers the ashes of the heifer shall wash his clothes, and be unclean until the evening: and it shall be to the children of Israel, and to the stranger who lives as a foreigner among them, for a statute forever.'),
  ('ab79348f-2d98-5210-ae89-8db6ca00a529', '108785b4-6816-5246-af31-503feb886ae9', NULL, 11, 11, '"He who touches the dead body of any man shall be unclean seven days:'),
  ('afcb5523-3b4c-51aa-a16e-574c78586c98', '108785b4-6816-5246-af31-503feb886ae9', NULL, 12, 12, 'the same shall purify himself with water on the third day, and on the seventh day he shall be clean: but if he doesn''t purify himself the third day, then the seventh day he shall not be clean.'),
  ('f3ce1363-63ea-526e-a51c-06b35b1e74e5', '108785b4-6816-5246-af31-503feb886ae9', NULL, 13, 13, 'Whoever touches a dead person, the body of a man who has died, and doesn''t purify himself, defiles the tabernacle of Yahweh; and that soul shall be cut off from Israel: because the water for impurity was not sprinkled on him, he shall be unclean; his uncleanness is yet on him.'),
  ('0a951b67-154f-5a43-abbb-dd9bc12de61d', '108785b4-6816-5246-af31-503feb886ae9', NULL, 14, 14, '"This is the law when a man dies in a tent: everyone who comes into the tent, and everyone who is in the tent, shall be unclean seven days.'),
  ('ec35124d-43a1-56f8-ae08-3144632a5268', '108785b4-6816-5246-af31-503feb886ae9', NULL, 15, 15, 'Every open vessel, which has no covering bound on it, is unclean.'),
  ('76b8f2e9-6f89-5efd-a02d-89434d6907bc', '108785b4-6816-5246-af31-503feb886ae9', NULL, 16, 16, '"Whoever in the open field touches one who is slain with a sword, or a dead body, or a bone of a man, or a grave, shall be unclean seven days.'),
  ('3857e932-0e2d-5643-a045-2d1b5b3ddf0e', '108785b4-6816-5246-af31-503feb886ae9', NULL, 17, 17, '"For the unclean they shall take of the ashes of the burning of the sin offering; and running water shall be put thereto in a vessel:'),
  ('3a5eb319-8344-5e6a-ad0f-ca5ad4bba58c', '108785b4-6816-5246-af31-503feb886ae9', NULL, 18, 18, 'and a clean person shall take hyssop, and dip it in the water, and sprinkle it on the tent, and on all the vessels, and on the persons who were there, and on him who touched the bone, or the slain, or the dead, or the grave:'),
  ('13e04f9b-9290-538e-a7eb-95566bd665df', '108785b4-6816-5246-af31-503feb886ae9', NULL, 19, 19, 'and the clean person shall sprinkle on the unclean on the third day, and on the seventh day: and on the seventh day he shall purify him; and he shall wash his clothes, and bathe himself in water, and shall be clean at evening.'),
  ('69b81fd4-2025-57d3-a848-84579a065d02', '108785b4-6816-5246-af31-503feb886ae9', NULL, 20, 20, 'But the man who shall be unclean, and shall not purify himself, that soul shall be cut off from the midst of the assembly, because he has defiled the sanctuary of Yahweh: the water for impurity has not been sprinkled on him; he is unclean.'),
  ('695dee2e-522a-5219-aae9-fe5692192fd4', '108785b4-6816-5246-af31-503feb886ae9', NULL, 21, 21, 'It shall be a perpetual statute to them: and he who sprinkles the water for impurity shall wash his clothes, and he who touches the water for impurity shall be unclean until evening.'),
  ('7117b50c-fa93-51dd-a57d-f51a208483d3', '108785b4-6816-5246-af31-503feb886ae9', NULL, 22, 22, '"Whatever the unclean person touches shall be unclean; and the soul that touches it shall be unclean until evening."'),
  ('339da6b2-4923-5681-afae-85393b6ee498', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 1, 1, 'The children of Israel, even the whole congregation, came into the wilderness of Zin in the first month: and the people stayed in Kadesh; and Miriam died there, and was buried there.'),
  ('cc2406cf-cf4d-58bc-a326-3627c8ab518a', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 2, 2, 'There was no water for the congregation: and they assembled themselves together against Moses and against Aaron.'),
  ('350d27b5-d690-5e2f-a6f9-b55d5d88326c', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 3, 3, 'The people strove with Moses, and spoke, saying, "We wish that we had died when our brothers died before Yahweh!'),
  ('e288b73c-c770-55b8-a8f5-ce4d60193224', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 4, 4, 'Why have you brought the assembly of Yahweh into this wilderness, that we should die there, we and our animals?'),
  ('261c7f00-f102-5131-acda-8bcb817304d6', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 5, 5, 'Why have you made us to come up out of Egypt, to bring us in to this evil place? It is no place of seed, or of figs, or of vines, or of pomegranates; neither is there any water to drink."'),
  ('a1b0525c-5491-5f0d-ab26-973b66230a72', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 6, 6, 'Moses and Aaron went from the presence of the assembly to the door of the Tent of Meeting, and fell on their faces: and the glory of Yahweh appeared to them.'),
  ('1ffe7462-abe3-57d0-a0e3-0fec3bc402fc', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 7, 7, 'Yahweh spoke to Moses, saying,'),
  ('267472c1-c7ac-5ffd-ace6-35bafb1ad8bf', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 8, 8, '"Take the rod, and assemble the congregation, you, and Aaron your brother, and speak to the rock before their eyes, that it give forth its water; and you shall bring forth to them water out of the rock; so you shall give the congregation and their livestock drink."'),
  ('24d7fc94-b387-5a86-ae2b-8fc644386054', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 9, 9, 'Moses took the rod from before Yahweh, as he commanded him.'),
  ('335235b4-ea78-5984-a511-ca5c88c456cb', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 10, 10, 'Moses and Aaron gathered the assembly together before the rock, and he said to them, "Hear now, you rebels; shall we bring you water out of this rock for you?"'),
  ('bd3e95be-427c-5acd-a429-5b9bd23ed128', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 11, 11, 'Moses lifted up his hand, and struck the rock with his rod twice: and water came forth abundantly, and the congregation drank, and their livestock.'),
  ('795b0ba8-4b3f-5b74-acd3-42aab5b3b853', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 12, 12, 'Yahweh said to Moses and Aaron, "Because you didn''t believe in me, to sanctify me in the eyes of the children of Israel, therefore you shall not bring this assembly into the land which I have given them."'),
  ('9ae89bdf-9b10-570d-a14b-e22cf0730e85', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 13, 13, 'These are the waters of Meribah; because the children of Israel strove with Yahweh, and he was sanctified in them.'),
  ('3fdb2e98-0285-562e-af87-5e0dc26a5c57', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 14, 14, 'Moses sent messengers from Kadesh to the king of Edom, saying: "Thus says your brother Israel: You know all the travail that has happened to us:'),
  ('4e4ffa8a-c580-5d8f-a92f-46e15bcf7999', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 15, 15, 'how our fathers went down into Egypt, and we lived in Egypt a long time; and the Egyptians dealt ill with us, and our fathers:'),
  ('f368acfd-1282-5cd8-a87f-00c90b435422', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 16, 16, 'and when we cried to Yahweh, he heard our voice, and sent an angel, and brought us forth out of Egypt: and behold, we are in Kadesh, a city in the uttermost of your border.'),
  ('f876b962-2da7-5648-ab50-febd0357e4e0', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 17, 17, '"Please let us pass through your land: we will not pass through field or through vineyard, neither will we drink of the water of the wells: we will go along the king''s highway; we will not turn aside to the right hand nor to the left, until we have passed your border."'),
  ('c7c11de1-c835-5561-ab7e-fd2c7b8f9d63', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 18, 18, 'Edom said to him, "You shall not pass through me, lest I come out with the sword against you."'),
  ('37d95905-ed18-5099-a509-7e126d785842', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 19, 19, 'The children of Israel said to him, "We will go up by the highway; and if we drink of your water, I and my livestock, then will I give its price: let me only, without [doing] anything [else], pass through on my feet."'),
  ('edf171e7-6eb5-5532-ae4a-87fc574c509a', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 20, 20, 'He said, "You shall not pass through." Edom came out against him with many people, and with a strong hand.'),
  ('53d0fefe-41f6-5d51-a2e1-20f79d050a45', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 21, 21, 'Thus Edom refused to give Israel passage through his border, so Israel turned away from him.'),
  ('53096a28-ee6d-5bb3-a684-f6d9aa49748b', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 22, 22, 'They traveled from Kadesh: and the children of Israel, even the whole congregation, came to Mount Hor.'),
  ('27068e20-daa9-56aa-a0c3-ef5b9c470c37', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 23, 23, 'Yahweh spoke to Moses and Aaron in Mount Hor, by the border of the land of Edom, saying,'),
  ('4c6f6b41-baec-5e00-ab98-19165ad59a7f', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 24, 24, '"Aaron shall be gathered to his people; for he shall not enter into the land which I have given to the children of Israel, because you rebelled against my word at the waters of Meribah.'),
  ('f3a980eb-85f4-5882-a6a5-dca1977d78b9', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 25, 25, 'Take Aaron and Eleazar his son, and bring them up to Mount Hor;'),
  ('437b25f7-5db7-57ca-af84-fcebd3ce2f1c', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 26, 26, 'and strip Aaron of his garments, and put them on Eleazar his son: and Aaron shall be gathered [to his people], and shall die there."'),
  ('df7ac3e6-930f-5630-aa35-ccbb8ae6750a', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 27, 27, 'Moses did as Yahweh commanded: and they went up into Mount Hor in the sight of all the congregation.'),
  ('605c8abb-3c30-5596-aef5-90b394a50386', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 28, 28, 'Moses stripped Aaron of his garments, and put them on Eleazar his son; and Aaron died there on the top of the mountain: and Moses and Eleazar came down from the mountain.'),
  ('5467988d-6158-5d83-a0e4-8f0b799397f5', '5ba8e69f-4ca9-52f3-a208-13c665a44dc3', NULL, 29, 29, 'When all the congregation saw that Aaron was dead, they wept for Aaron thirty days, even all the house of Israel.'),
  ('18b040cd-f5fb-5b74-a918-fb72a86bb7fa', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 1, 1, 'The Canaanite, the king of Arad, who lived in the South, heard tell that Israel came by the way of Atharim; and he fought against Israel, and took some of them captive.'),
  ('a252ac58-8360-5a17-a9bd-7e8c3e327f82', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 2, 2, 'Israel vowed a vow to Yahweh, and said, "If you will indeed deliver this people into my hand, then I will utterly destroy their cities."'),
  ('7ccbb209-ee9d-5bb1-aaf4-ebb44c632cd3', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 3, 3, 'Yahweh listened to the voice of Israel, and delivered up the Canaanites; and they utterly destroyed them and their cities: and the name of the place was called Hormah.'),
  ('dd1d400b-6abf-59e8-a07f-c236868d9cb1', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 4, 4, 'They traveled from Mount Hor by the way to the Red Sea, to compass the land of Edom: and the soul of the people was much discouraged because of the way.'),
  ('d4d74305-0873-57f9-a1fa-42c284395482', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 5, 5, 'The people spoke against God, and against Moses, "Why have you brought us up out of Egypt to die in the wilderness? For there is no bread, and there is no water; and our soul loathes this light bread."'),
  ('db335517-faac-5f30-ae8d-949c5f4df45a', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 6, 6, 'Yahweh sent fiery serpents among the people, and they bit the people; and many people of Israel died.'),
  ('4bcee24a-c597-50f4-a020-e4300ed26ab0', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 7, 7, 'The people came to Moses, and said, "We have sinned, because we have spoken against Yahweh, and against you. Pray to Yahweh, that he take away the serpents from us." Moses prayed for the people.'),
  ('9c953e81-87f2-56d1-a7a2-184bb497aa69', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 8, 8, 'Yahweh said to Moses, "Make a fiery serpent, and set it on a standard: and it shall happen, that everyone who is bitten, when he sees it, shall live."'),
  ('6fac8350-ea44-5ec6-a94e-f9467fb62410', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 9, 9, 'Moses made a serpent of brass, and set it on the standard: and it happened, that if a serpent had bitten any man, when he looked to the serpent of brass, he lived.'),
  ('e76378ae-d6c4-5541-a4de-2de6a56583c7', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 10, 10, 'The children of Israel traveled, and encamped in Oboth.'),
  ('1030c0cf-f6db-57f0-ab39-9d3b1ebc3383', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 11, 11, 'They traveled from Oboth, and encamped at Iyeabarim, in the wilderness which is before Moab, toward the sunrise.'),
  ('f0901f63-e233-56c9-aae6-bbb6b9ad8d95', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 12, 12, 'From there they traveled, and encamped in the valley of Zered.'),
  ('a71430e1-2824-50c9-ac95-d8a06d68bf44', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 13, 13, 'From there they traveled, and encamped on the other side of the Arnon, which is in the wilderness, that comes out of the border of the Amorites: for the Arnon is the border of Moab, between Moab and the Amorites.'),
  ('5478dbfb-bddb-5b03-aa40-a1ca32812922', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 14, 14, 'Therefore it is said in the book of the Wars of Yahweh, "Vaheb in Suphah, the valleys of the Arnon,'),
  ('06b88a38-cf21-5eaa-a6a4-f12701de1c04', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 15, 15, 'the slope of the valleys that incline toward the dwelling of Ar, leans on the border of Moab."'),
  ('df8be2a8-78bc-589f-a37a-ae5a106d5d48', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 16, 16, 'From there they traveled to Beer: that is the well of which Yahweh said to Moses, "Gather the people together, and I will give them water."'),
  ('d28007c5-e66f-5be1-a513-ea4372ab5009', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 17, 17, 'Then sang Israel this song: "Spring up, well; sing to it:'),
  ('ccd5f2cf-1e54-54fd-a52e-f3262311b383', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 18, 18, 'the well, which the princes dug, which the nobles of the people dug, with the scepter, and with their poles." From the wilderness [they traveled] to Mattanah;'),
  ('daf37e4f-9051-5abc-abba-b7ab1f8175c0', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 19, 19, 'and from Mattanah to Nahaliel; and from Nahaliel to Bamoth;'),
  ('533340d4-d59f-5d58-a4d0-69a6e19c5900', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 20, 20, 'and from Bamoth to the valley that is in the field of Moab, to the top of Pisgah, which looks down on the desert.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8c17203a-c41b-5698-a9ab-f2864a7ab91c', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 21, 21, 'Israel sent messengers to Sihon king of the Amorites, saying,'),
  ('4cf06c4f-5608-55db-a065-f2b7fdefa38e', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 22, 22, '"Let me pass through your land: we will not turn aside into field, or into vineyard; we will not drink of the water of the wells: we will go by the king''s highway, until we have passed your border."'),
  ('ece16357-cd1b-5cf7-a8e9-ec66a59af2b3', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 23, 23, 'Sihon would not allow Israel to pass through his border: but Sihon gathered all his people together, and went out against Israel into the wilderness, and came to Jahaz; and he fought against Israel.'),
  ('e9db2ec5-580c-53a9-afd2-6d280abaf067', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 24, 24, 'Israel struck him with the edge of the sword, and possessed his land from the Arnon to the Jabbok, even to the children of Ammon; for the border of the children of Ammon was strong.'),
  ('80761f6b-eeda-5b5a-a92a-726a0b8a6a2a', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 25, 25, 'Israel took all these cities: and Israel lived in all the cities of the Amorites, in Heshbon, and in all its towns.'),
  ('26720314-cf23-501c-ab2e-2feaf1c375bc', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 26, 26, 'For Heshbon was the city of Sihon the king of the Amorites, who had fought against the former king of Moab, and taken all his land out of his hand, even to the Arnon.'),
  ('546d19df-da4b-5c67-a4ae-ef78ec7235f4', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 27, 27, 'Therefore those who speak in proverbs say, "Come to Heshbon. Let the city of Sihon be built and established;'),
  ('551dae34-a814-5f07-a588-b72fbbc841c0', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 28, 28, 'for a fire has gone out of Heshbon, a flame from the city of Sihon. It has devoured Ar of Moab, The lords of the high places of the Arnon.'),
  ('2f3bc336-99a9-5186-a15a-0cee9444790e', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 29, 29, 'Woe to you, Moab! You are undone, people of Chemosh! He has given his sons as fugitives, and his daughters into captivity, to Sihon king of the Amorites.'),
  ('83359753-f7e3-501f-a795-668bb2ce6baa', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 30, 30, 'We have shot at them. Heshbon has perished even to Dibon. We have laid waste even to Nophah, Which reaches to Medeba."'),
  ('5b472230-fb10-5ea6-ac1f-e0134e87a821', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 31, 31, 'Thus Israel lived in the land of the Amorites.'),
  ('cbd91aea-123f-5355-a58b-1360c9f5041b', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 32, 32, 'Moses sent to spy out Jazer; and they took its towns, and drove out the Amorites who were there.'),
  ('3d02a6a1-6b0e-5ac0-ac16-45c843e65dc7', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 33, 33, 'They turned and went up by the way of Bashan: and Og the king of Bashan went out against them, he and all his people, to battle at Edrei.'),
  ('5b5250b6-410c-59c4-ac3a-93352115ef71', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 34, 34, 'Yahweh said to Moses, "Don''t fear him: for I have delivered him into your hand, and all his people, and his land; and you shall do to him as you did to Sihon king of the Amorites, who lived at Heshbon."'),
  ('d3dda112-7adb-512e-a9f0-18384b14c5cc', '11f255c7-d53d-5b09-ad68-551af8235925', NULL, 35, 35, 'So they struck him, and his sons and all his people, until there was none left him remaining: and they possessed his land.'),
  ('89675148-faf9-5cc8-a8a1-a280d2c0e897', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 1, 1, 'The children of Israel traveled, and encamped in the plains of Moab beyond the Jordan at Jericho.'),
  ('ec3d6626-00e0-5a55-a8c4-42adc0c64709', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 2, 2, 'Balak the son of Zippor saw all that Israel had done to the Amorites.'),
  ('875ea72c-5e2c-5f45-a53d-5121cff955f8', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 3, 3, 'Moab was very afraid of the people, because they were many: and Moab was distressed because of the children of Israel.'),
  ('c2dc3903-0714-56d6-a460-70ce8d8e9b9a', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 4, 4, 'Moab said to the elders of Midian, "Now this multitude will lick up all that is around us, as the ox licks up the grass of the field." Balak the son of Zippor was king of Moab at that time.'),
  ('cd641671-5b42-5fc3-a341-faa4c00ff18a', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 5, 5, 'He sent messengers to Balaam the son of Beor, to Pethor, which is by the River, to the land of the children of his people, to call him, saying, "Behold, there is a people who came out from Egypt. Behold, they cover the surface of the earth, and they are staying opposite me.'),
  ('a9c5c1f2-efa6-5f0c-a632-e18155249eca', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 6, 6, 'Please come now therefore curse me this people; for they are too mighty for me: perhaps I shall prevail, that we may strike them, and that I may drive them out of the land; for I know that he whom you bless is blessed, and he whom you curse is cursed."'),
  ('07a20b97-aaba-5822-a91a-b12981ee0e24', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 7, 7, 'The elders of Moab and the elders of Midian departed with the rewards of divination in their hand; and they came to Balaam, and spoke to him the words of Balak.'),
  ('2e46cc2a-4417-54e0-aedb-d834ac90d7ff', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 8, 8, 'He said to them, "Lodge here this night, and I will bring you word again, as Yahweh shall speak to me." The princes of Moab stayed with Balaam.'),
  ('39f6c8de-355b-52cb-a0de-2df4b1bed225', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 9, 9, 'God came to Balaam, and said, "Who are these men with you?"'),
  ('6776515b-3a0d-5629-ab30-4a0043c6fede', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 10, 10, 'Balaam said to God, "Balak the son of Zippor, king of Moab, has sent to me, [saying],'),
  ('97a65743-c965-5355-a593-cd6612dfc838', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 11, 11, '''Behold, the people that is come out of Egypt, it covers the surface of the earth: now, come curse me them; perhaps I shall be able to fight against them, and shall drive them out.''"'),
  ('ad59ed74-4708-5c4d-ad35-728a9be47a28', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 12, 12, 'God said to Balaam, "You shall not go with them. You shall not curse the people; for they are blessed."'),
  ('31ba46b3-c88a-5737-a5c5-82b2869bb6f9', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 13, 13, 'Balaam rose up in the morning, and said to the princes of Balak, "Go to your land; for Yahweh refuses to permit me to go with you."'),
  ('bd4f4308-dfed-5cee-aafc-7965b24f9072', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 14, 14, 'The princes of Moab rose up, and they went to Balak, and said, "Balaam refuses to come with us."'),
  ('a9f33d85-e2c4-5b5a-a59e-3ce51134dbf9', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 15, 15, 'Balak sent yet again princes, more, and more honorable than they.'),
  ('52a934ce-239e-58d4-a9eb-700d049f5b16', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 16, 16, 'They came to Balaam, and said to him, "Thus says Balak the son of Zippor, ''Please let nothing hinder you from coming to me:'),
  ('55f13e79-c56e-555d-ab3c-e68ad875b68d', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 17, 17, 'for I will promote you to very great honor, and whatever you say to me I will do. Please come therefore, and curse this people for me.''"'),
  ('303b86a2-ee09-5452-ab67-043d6d9fd524', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 18, 18, 'Balaam answered the servants of Balak, "If Balak would give me his house full of silver and gold, I can''t go beyond the word of Yahweh my God, to do less or more.'),
  ('217fb9b1-6afe-5e5f-a2e8-610aae47185b', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 19, 19, 'Now therefore, please wait also here this night, that I may know what Yahweh will speak to me more."'),
  ('586bab9c-48b1-55b0-ab8c-49443e648d93', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 20, 20, 'God came to Balaam at night, and said to him, "If the men have come to call you, rise up, go with them; but only the word which I speak to you, that you shall do."'),
  ('109f5207-66bf-5f8d-a7b5-5080d8df788e', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 21, 21, 'Balaam rose up in the morning, and saddled his donkey, and went with the princes of Moab.'),
  ('a5c89260-d00a-5882-a7dc-44ea11b4d3d3', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 22, 22, 'God''s anger was kindled because he went; and the angel of Yahweh placed himself in the way for an adversary against him. Now he was riding on his donkey, and his two servants were with him.'),
  ('96f11f1d-bfbb-5b50-aabe-eeab3dfd4d70', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 23, 23, 'The donkey saw the angel of Yahweh standing in the way, with his sword drawn in his hand; and the donkey turned aside out of the way, and went into the field: and Balaam struck the donkey, to turn her into the way.'),
  ('e532535e-b7b7-5747-aa55-948fe7426aff', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 24, 24, 'Then the angel of Yahweh stood in a narrow path between the vineyards, a wall being on this side, and a wall on that side.'),
  ('0032b8d7-2b05-58e4-a393-3d6011024c00', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 25, 25, 'The donkey saw the angel of Yahweh, and she thrust herself to the wall, and crushed Balaam''s foot against the wall: and he struck her again.'),
  ('9abc5811-4e1f-566b-a3e4-109ec564ef7b', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 26, 26, 'The angel of Yahweh went further, and stood in a narrow place, where there was no way to turn either to the right hand or to the left.'),
  ('8dcc5422-16cc-5d89-a22b-f03fe0f9e5a7', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 27, 27, 'The donkey saw the angel of Yahweh, and she lay down under Balaam: and Balaam''s anger was kindled, and he struck the donkey with his staff.'),
  ('47eb428a-b71d-53cb-ab11-5fa0fe20b7a5', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 28, 28, 'Yahweh opened the mouth of the donkey, and she said to Balaam, "What have I done to you, that you have struck me these three times?"'),
  ('a172e351-3190-5668-ac67-70a68757fca7', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 29, 29, 'Balaam said to the donkey, "Because you have mocked me, I wish there were a sword in my hand, for now I would have killed you."'),
  ('c2fd688c-9c5c-5da8-a0e5-3404f57a2f17', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 30, 30, 'The donkey said to Balaam, "Am I not your donkey, on which you have ridden all your life long to this day? Was I ever in the habit of doing so to you?" He said, "No."'),
  ('0b41b6f1-8441-5c9d-ad78-af378efd97e9', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 31, 31, 'Then Yahweh opened the eyes of Balaam, and he saw the angel of Yahweh standing in the way, with his sword drawn in his hand; and he bowed his head, and fell on his face.'),
  ('68f13546-c3db-519a-a0bf-c875f69c92d7', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 32, 32, 'The angel of Yahweh said to him, "Why have you struck your donkey these three times? Behold, I have come forth as an adversary, because your way is perverse before me:'),
  ('cdec9483-b9c4-5d1e-ae45-0bdd679c517a', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 33, 33, 'and the donkey saw me, and turned aside before me these three times. Unless she had turned aside from me, surely now I would have killed you, and saved her alive."'),
  ('9715e882-ebb3-5a96-a9d9-5899fc3e52c9', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 34, 34, 'Balaam said to the angel of Yahweh, "I have sinned; for I didn''t know that you stood in the way against me. Now therefore, if it displeases you, I will go back again."'),
  ('dea12bbe-9ed4-5c02-a276-a6923a4f766c', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 35, 35, 'The angel of Yahweh said to Balaam, "Go with the men; but only the word that I shall speak to you, that you shall speak." So Balaam went with the princes of Balak.'),
  ('4a60d376-b710-59f4-a610-0e2a4827304a', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 36, 36, 'When Balak heard that Balaam had come, he went out to meet him to the City of Moab, which is on the border of the Arnon, which is in the utmost part of the border.'),
  ('1a894839-e9f7-550f-a081-a82677c79a29', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 37, 37, 'Balak said to Balaam, "Didn''t I earnestly send to you to call you? Why didn''t you come to me? Am I not able indeed to promote you to honor?"'),
  ('f71f78c4-57e8-53c3-a1b6-b9235eb7c56f', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 38, 38, 'Balaam said to Balak, "Behold, I have come to you: have I now any power at all to speak anything? The word that God puts in my mouth, that shall I speak."'),
  ('2de46b2b-69ad-542c-a37c-35bbbb9f2536', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 39, 39, 'Balaam went with Balak, and they came to Kiriath Huzoth.'),
  ('3e8287cc-f1ea-5f84-acd0-33b4618682c7', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 40, 40, 'Balak sacrificed cattle and sheep, and sent to Balaam, and to the princes who were with him.'),
  ('07a121e2-d749-56fe-af68-76fdf2c67041', '2d33681e-dbaf-5f01-ae2c-400e1b1fcd53', NULL, 41, 41, 'It happened in the morning, that Balak took Balaam, and brought him up into the high places of Baal; and he saw from there the utmost part of the people.'),
  ('cb34bd6b-5ede-587f-adb4-9e8ff6e4e096', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 1, 1, 'Balaam said to Balak, "Build me here seven altars, and prepare me here seven bulls and seven rams."'),
  ('2a3223ee-703b-549e-acea-84619379c8c4', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 2, 2, 'Balak did as Balaam had spoken; and Balak and Balaam offered on every altar a bull and a ram.'),
  ('1eaf60a2-2b9d-5045-a168-1efda81de7e9', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 3, 3, 'Balaam said to Balak, "Stand by your burnt offering, and I will go: perhaps Yahweh will come to meet me; and whatever he shows me I will tell you." He went to a bare height.'),
  ('019502bf-318d-5b76-ad01-dddc9ddcdffe', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 4, 4, 'God met Balaam: and he said to him, "I have prepared the seven altars, and I have offered up a bull and a ram on every altar."'),
  ('04bcd8dd-171b-5c86-ab80-c32046a1e0f9', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 5, 5, 'Yahweh put a word in Balaam''s mouth, and said, "Return to Balak, and thus you shall speak."'),
  ('f7a6cab5-8aa5-556e-a5f0-bae5036af23c', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 6, 6, 'He returned to him, and behold, he was standing by his burnt offering, he, and all the princes of Moab.'),
  ('98083ba3-19d4-59a8-a9cd-2decc4b3e852', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 7, 7, 'He took up his parable, and said, "From Aram has Balak brought me, the king of Moab from the mountains of the East. Come, curse Jacob for me. Come, defy Israel.'),
  ('28f2dee6-256b-5572-ab32-26b8be6ab99a', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 8, 8, 'How shall I curse whom God has not cursed? How shall I defy whom Yahweh has not defied?'),
  ('36b27a52-3681-5e8d-a6b7-7280aa6b2cd8', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 9, 9, 'For from the top of the rocks I see him. From the hills I see him. Behold, it is a people that dwells alone, and shall not be reckoned among the nations.'),
  ('786a57cb-852c-51bb-af32-6160fa0ff86e', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 10, 10, 'Who can count the dust of Jacob, or number the fourth part of Israel? Let me die the death of the righteous! Let my last end be like his!"'),
  ('a7cfd360-8237-50a2-a9f0-88f4413dc26f', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 11, 11, 'Balak said to Balaam, "What have you done to me? I took you to curse my enemies, and behold, you have blessed them altogether."'),
  ('e50139ac-cce4-5bd9-abb9-103e9b060519', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 12, 12, 'He answered and said, "Must I not take heed to speak that which Yahweh puts in my mouth?"'),
  ('a8970603-8777-5d2b-a914-d91e6ec17d23', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 13, 13, 'Balak said to him, "Please come with me to another place, where you may see them; you shall see but the utmost part of them, and shall not see them all: and curse me them from there."'),
  ('bea955c1-1b85-56a5-a27f-647f5780d994', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 14, 14, 'He took him into the field of Zophim, to the top of Pisgah, and built seven altars, and offered up a bull and a ram on every altar.'),
  ('0be9c44f-fbd9-5c54-a64c-cae9b2809a6a', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 15, 15, 'He said to Balak, "Stand here by your burnt offering, while I meet [Yahweh] yonder."'),
  ('a0211c15-f23f-5ad4-ab30-b6689729f5f0', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 16, 16, 'Yahweh met Balaam, and put a word in his mouth, and said, "Return to Balak, and say this."'),
  ('28febf12-8903-56b8-afee-b7e204dc3f3f', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 17, 17, 'He came to him, and behold, he was standing by his burnt offering, and the princes of Moab with him. Balak said to him, "What has Yahweh spoken?"'),
  ('4cc91f4c-943d-5fc1-a39e-4f7886973c56', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 18, 18, 'He took up his parable, and said, "Rise up, Balak, and hear! Listen to me, you son of Zippor.'),
  ('f6f70e99-de63-5e9b-a2de-d4834b89f305', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 19, 19, 'God is not a man, that he should lie, nor the son of man, that he should repent. Has he said, and will he not do it? Or has he spoken, and will he not make it good?'),
  ('fb51b198-bb38-53c9-ab6f-66058d927703', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 20, 20, 'Behold, I have received a command to bless. He has blessed, and I can''t reverse it.'),
  ('89114537-db16-5192-ad69-8854ce69cdeb', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 21, 21, 'He has not seen iniquity in Jacob. Neither has he seen perverseness in Israel. Yahweh his God is with him. The shout of a king is among them.'),
  ('6b641bb3-a79e-5fbf-ab17-6a78806a9904', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 22, 22, 'God brings them out of Egypt. He has as it were the strength of the wild ox.'),
  ('14aea88d-60c7-52e9-a4e9-e6117d7614d8', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 23, 23, 'Surely there is no enchantment with Jacob; Neither is there any divination with Israel. Now it shall be said of Jacob and of Israel, What has God done!'),
  ('726af019-9337-501f-a595-2e2615ec6ef3', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 24, 24, 'Behold, the people rises up as a lioness, As a lion he lifts himself up. He shall not lie down until he eat of the prey, and drinks the blood of the slain."'),
  ('6dde8280-aceb-58b9-a36d-2a465b7dfe85', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 25, 25, 'Balak said to Balaam, "Neither curse them at all, nor bless them at all."'),
  ('25cfbc01-8c27-5e72-a192-b4996337ced4', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 26, 26, 'But Balaam answered Balak, "Didn''t I tell you, saying, ''All that Yahweh speaks, that I must do?''"'),
  ('b303a8ef-0ced-5840-a7eb-645ccb3949b6', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 27, 27, 'Balak said to Balaam, "Come now, I will take you to another place; perhaps it will please God that you may curse me them from there."'),
  ('e035b784-fb8b-5693-a9f6-ecdb31d24d9f', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 28, 28, 'Balak took Balaam to the top of Peor, that looks down on the desert.'),
  ('f6b8411c-80e9-528e-a2fa-10e1d79c343c', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 29, 29, 'Balaam said to Balak, "Build me here seven altars, and prepare me here seven bulls and seven rams."'),
  ('5f1592ec-908f-5561-ac53-af951208adb5', '8851635d-8a58-5942-a1ca-4dc8507e4482', NULL, 30, 30, 'Balak did as Balaam had said, and offered up a bull and a ram on every altar.'),
  ('41b344dd-6b5e-5066-a3b3-70bc30b3be07', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 1, 1, 'When Balaam saw that it pleased Yahweh to bless Israel, he didn''t go, as at the other times, to meet with enchantments, but he set his face toward the wilderness.'),
  ('8feac751-12cd-55bc-a001-a95ab7b7fa7e', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 2, 2, 'Balaam lifted up his eyes, and he saw Israel dwelling according to their tribes; and the Spirit of God came on him.'),
  ('12a1a84c-772b-5b43-a12c-2c9909c2aba7', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 3, 3, 'He took up his parable, and said, "Balaam the son of Beor says, the man whose eye was closed says;'),
  ('ae0081b6-42e3-53de-a3f0-ca94345f3df9', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 4, 4, 'he says, who hears the words of God, who sees the vision of the Almighty, falling down, and having his eyes open:'),
  ('0a9f6e31-2cde-5f02-accd-fd18887787b9', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 5, 5, 'How goodly are your tents, Jacob, and your tents, Israel!'),
  ('561439fe-7bbb-51cb-a142-a7d22ef49e0e', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 6, 6, 'As valleys they are spread forth, as gardens by the riverside, as aloes which Yahweh has planted, as cedar trees beside the waters.'),
  ('5ddfb490-d777-5713-aa4c-566121938630', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 7, 7, 'Water shall flow from his buckets. His seed shall be in many waters. His king shall be higher than Agag. His kingdom shall be exalted.'),
  ('efc31fcb-25a4-5b5d-aab2-fafa8007822c', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 8, 8, 'God brings him out of Egypt. He has as it were the strength of the wild ox. He shall eat up the nations his adversaries, shall break their bones in pieces, and pierce them with his arrows.'),
  ('3dbdedcc-68b1-59b7-aa81-9535e71d80ef', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 9, 9, 'He couched, he lay down as a lion, as a lioness; who shall rouse him up? Everyone who blesses you is blessed. Everyone who curses you is cursed."'),
  ('6cc3aa1c-eee2-510c-a29b-895687e38594', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 10, 10, 'Balak''s anger was kindled against Balaam, and he struck his hands together; and Balak said to Balaam, "I called you to curse my enemies, and, behold, you have altogether blessed them these three times.'),
  ('b9ff318e-69e0-571c-a3aa-7e9f4ef068f4', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 11, 11, 'Therefore now flee you to your place! I thought to promote you to great honor; but, behold, Yahweh has kept you back from honor."'),
  ('74b7158e-e77e-5d63-ae7f-b33361146c4f', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 12, 12, 'Balaam said to Balak, "Didn''t I also tell your messengers who you sent to me, saying,'),
  ('c8ee6bda-bb3d-5b50-a0d8-bbfea03bda83', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 13, 13, '''If Balak would give me his house full of silver and gold, I can''t go beyond the word of Yahweh, to do either good or bad of my own mind. I will say what Yahweh says''?'),
  ('6fe34bb5-60c1-5413-a326-d2ff6c3341bf', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 14, 14, 'Now, behold, I go to my people: come, [and] I will inform you what this people shall do to your people in the latter days."'),
  ('2e1bd851-059d-52e1-ac0c-2e277fc0fc73', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 15, 15, 'He took up his parable, and said, "Balaam the son of Beor says, the man whose eye was closed says;'),
  ('19ac4082-8cea-5445-a26c-ca36eb8a4286', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 16, 16, 'he says, who hears the words of God, knows the knowledge of the Most High, and who sees the vision of the Almighty, Falling down, and having his eyes open:'),
  ('28e4b6e2-401a-5883-a387-21832842de94', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 17, 17, 'I see him, but not now. I see him, but not near. A star will come out of Jacob. A scepter will rise out of Israel, and shall strike through the corners of Moab, and break down all the sons of Sheth.'),
  ('dd6ee829-e61d-5f13-a482-fbc3766f09d1', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 18, 18, 'Edom shall be a possession. Seir, his enemies, also shall be a possession, while Israel does valiantly.'),
  ('7bf7ca67-5dc9-51a0-a1b7-470c66175a31', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 19, 19, 'Out of Jacob shall one have dominion, and shall destroy the remnant from the city."'),
  ('9ff10ed1-ffa1-5ddb-a9f3-4f22d147c2c0', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 20, 20, 'He looked at Amalek, and took up his parable, and said, "Amalek was the first of the nations, But his latter end shall come to destruction."'),
  ('221d71b0-36d8-557e-a4e4-f863e885f023', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 21, 21, 'He looked at the Kenite, and took up his parable, and said, "Your dwelling place is strong. Your nest is set in the rock.'),
  ('354dd6c5-6802-5fa3-ac9c-61669c01910a', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 22, 22, 'Nevertheless Kain shall be wasted, until Asshur carries you away captive."'),
  ('9c0f6051-6ca3-5133-a843-355b8683890a', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 23, 23, 'He took up his parable, and said, "Alas, who shall live when God does this?'),
  ('71237f39-32af-50d1-ac12-e0f1052f317d', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 24, 24, 'But ships [shall come] from the coast of Kittim. They shall afflict Asshur, and shall afflict Eber. He also shall come to destruction."'),
  ('9da400d8-fabf-5f1b-a515-425d311b657c', 'a813601b-ad2d-5587-a3d9-8c05c34970f0', NULL, 25, 25, 'Balaam rose up, and went and returned to his place; and Balak also went his way.'),
  ('123851b3-6c9f-52fd-a65b-c545e39ac316', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 1, 1, 'Israel stayed in Shittim; and the people began to play the prostitute with the daughters of Moab:'),
  ('5f5514f3-4387-585f-ab1e-aed741feb1af', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 2, 2, 'for they called the people to the sacrifices of their gods; and the people ate, and bowed down to their gods.'),
  ('550d4884-15d8-57c0-a706-91c2c7f7f623', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 3, 3, 'Israel joined himself to Baal Peor: and the anger of Yahweh was kindled against Israel.'),
  ('8736f480-6a0e-5628-a9e6-ed85084dab6e', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 4, 4, 'Yahweh said to Moses, "Take all the chiefs of the people, and hang them up to Yahweh before the sun, that the fierce anger of Yahweh may turn away from Israel."'),
  ('76f48bbf-3e6e-52ab-a338-dd0d1654067f', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 5, 5, 'Moses said to the judges of Israel, "Everyone kill his men who have joined themselves to Baal Peor."'),
  ('d664bb86-f1ae-5b6b-ab61-3db348754647', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 6, 6, 'Behold, one of the children of Israel came and brought to his brothers a Midianite woman in the sight of Moses, and in the sight of all the congregation of the children of Israel, while they were weeping at the door of the Tent of Meeting.'),
  ('f45cfa7f-1425-5066-a7a9-43adb0e63a02', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 7, 7, 'When Phinehas, the son of Eleazar, the son of Aaron the priest, saw it, he rose up from the midst of the congregation, and took a spear in his hand;'),
  ('93dce9d5-725a-5901-a9c0-0ecba5f69d9e', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 8, 8, 'and he went after the man of Israel into the pavilion, and thrust both of them through, the man of Israel, and the woman through her body. So the plague was stayed from the children of Israel.'),
  ('09307c19-4486-5781-aded-32a2429b15d0', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 9, 9, 'Those who died by the plague were twenty-four thousand.'),
  ('c96f8e5e-d1b8-5059-a26d-8312cdb8d87e', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 10, 10, 'Yahweh spoke to Moses, saying,'),
  ('8cee3262-3972-5ab4-a325-2dc94b193c0c', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 11, 11, '"Phinehas, the son of Eleazar, the son of Aaron the priest, has turned my wrath away from the children of Israel, in that he was jealous with my jealousy among them, so that I didn''t consume the children of Israel in my jealousy.'),
  ('de775382-5a17-5646-a6db-304d3e7cab08', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 12, 12, 'Therefore say, ''Behold, I give to him my covenant of peace:'),
  ('b0af42e7-1b0c-5f6e-ac63-b1c839f35431', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 13, 13, 'and it shall be to him, and to his seed after him, the covenant of an everlasting priesthood; because he was jealous for his God, and made atonement for the children of Israel.''"'),
  ('499a76a8-1474-5259-a14e-a0ad81546dbb', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 14, 14, 'Now the name of the man of Israel that was slain, who was slain with the Midianite woman, was Zimri, the son of Salu, a prince of a fathers'' house among the Simeonites.'),
  ('d3fc9a88-f53c-5064-a17c-c5676e3ef03a', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 15, 15, 'The name of the Midianite woman who was slain was Cozbi, the daughter of Zur; he was head of the people of a fathers'' house in Midian.'),
  ('e3f2bef8-cb4a-5479-a109-c46145d5c979', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 16, 16, 'Yahweh spoke to Moses, saying,'),
  ('ef4d5869-d6fd-5bb8-a01a-fccca2780b6d', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 17, 17, '"Harass the Midianites, and strike them;'),
  ('5b59567c-446d-580b-a702-e10c63ba6564', 'cc9c8c8b-362c-547f-a285-02a260dd030f', NULL, 18, 18, 'for they harassed you with their wiles, with which they have deceived you in the matter of Peor, and in the matter of Cozbi, the daughter of the prince of Midian, their sister, who was slain on the day of the plague in the matter of Peor."'),
  ('1b2a03d5-89a9-59ab-a074-0c4fd49779a1', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 1, 1, 'It happened after the plague, that Yahweh spoke to Moses and to Eleazar the son of Aaron the priest, saying,'),
  ('67269dea-2b48-52b9-a0af-d020f9167a4b', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 2, 2, '"Take a census of all the congregation of the children of Israel, from twenty years old and upward, by their fathers'' houses, all who are able to go forth to war in Israel."'),
  ('34611e43-9949-546f-a551-f815fe2d1867', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 3, 3, 'Moses and Eleazar the priest spoke with them in the plains of Moab by the Jordan at Jericho, saying,'),
  ('4ca68384-0aeb-5fcd-a5cb-f632fba8ec2a', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 4, 4, '"[Take a census of the people], from twenty years old and upward; as Yahweh commanded Moses and the children of Israel." These are those that came out of the land of Egypt.'),
  ('3dd2fcb2-8994-5033-a286-3c34909b0f2e', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 5, 5, 'Reuben, the firstborn of Israel; the sons of Reuben: [of] Hanoch, the family of the Hanochites; of Pallu, the family of the Palluites;'),
  ('79bb234a-21bc-57f9-af38-aa22d46825da', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 6, 6, 'of Hezron, the family of the Hezronites; of Carmi, the family of the Carmites.'),
  ('08e2ddc9-90da-5567-a680-1c8578b14acf', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 7, 7, 'These are the families of the Reubenites; and those who were numbered of them were forty-three thousand seven hundred thirty.'),
  ('ccee5fe8-5148-52e8-af45-5422e2cecca6', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 8, 8, 'The sons of Pallu: Eliab.'),
  ('561310cc-700a-5a0a-ab2e-2f7153498977', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 9, 9, 'The sons of Eliab: Nemuel, and Dathan, and Abiram. These are that Dathan and Abiram, who were called of the congregation, who strove against Moses and against Aaron in the company of Korah, when they strove against Yahweh,'),
  ('2a6ed722-7cb2-5a30-a867-608b74622962', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 10, 10, 'and the earth opened its mouth, and swallowed them up together with Korah, when that company died; what time the fire devoured two hundred fifty men, and they became a sign.'),
  ('0c15fe84-696f-56d9-a4f1-4939b5772ace', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 11, 11, 'Notwithstanding, the sons of Korah didn''t die.'),
  ('f71981f8-ab11-5512-a3cd-7442a1216f05', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 12, 12, 'The sons of Simeon after their families: of Nemuel, the family of the Nemuelites; of Jamin, the family of the Jaminites; of Jachin, the family of the Jachinites;'),
  ('3d1599ef-2ee9-55c3-a5fa-3067a80bad1b', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 13, 13, 'of Zerah, the family of the Zerahites; of Shaul, the family of the Shaulites.'),
  ('1b3e4413-879f-50ea-a694-af91eb1832bd', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 14, 14, 'These are the families of the Simeonites, twenty-two thousand two hundred.'),
  ('5efd1300-c99f-5539-a6f9-fb03bf0c1c32', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 15, 15, 'The sons of Gad after their families: of Zephon, the family of the Zephonites; of Haggi, the family of the Haggites; of Shuni, the family of the Shunites;'),
  ('d54613f1-c4a3-53b8-adcc-b4a67b539687', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 16, 16, 'of Ozni, the family of the Oznites; of Eri, the family of the Erites;'),
  ('89009565-93f0-5ef1-a726-7493d4b94f3f', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 17, 17, 'of Arod, the family of the Arodites; of Areli, the family of the Arelites.'),
  ('b279a640-6112-5e58-adb5-acf7f33ff09e', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 18, 18, 'These are the families of the sons of Gad according to those who were numbered of them, forty thousand and five hundred.'),
  ('3362c223-6345-5e9e-aee0-c28b69ff6130', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 19, 19, 'The sons of Judah: Er and Onan; and Er and Onan died in the land of Canaan.'),
  ('03448777-1a1a-509a-aa9a-831d2d97b7e9', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 20, 20, 'The sons of Judah after their families were: of Shelah, the family of the Shelanites; of Perez, the family of the Perezites; of Zerah, the family of the Zerahites.'),
  ('91aa08a5-4f45-5288-a79e-52d3b993a615', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 21, 21, 'The sons of Perez were: of Hezron, the family of the Hezronites; of Hamul, the family of the Hamulites.'),
  ('41b7d6f6-0ab2-528b-a0c0-d1d8aded2a98', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 22, 22, 'These are the families of Judah according to those who were numbered of them, seventy-six thousand five hundred.'),
  ('f94ced93-9961-5fb8-a299-1747212e3a72', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 23, 23, 'The sons of Issachar after their families: [of] Tola, the family of the Tolaites; of Puvah, the family of the Punites;'),
  ('ce7f3f46-14c1-5b38-a70e-75861531423e', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 24, 24, 'of Jashub, the family of the Jashubites; of Shimron, the family of the Shimronites.'),
  ('88817412-5bfa-5058-a6e1-a4f8fff13251', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 25, 25, 'These are the families of Issachar according to those who were numbered of them, sixty-four thousand three hundred.'),
  ('83cf5ff0-2897-5fc1-a3aa-eb5010be3339', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 26, 26, 'The sons of Zebulun after their families: of Sered, the family of the Seredites; of Elon, the family of the Elonites; of Jahleel, the family of the Jahleelites.'),
  ('31ee2aa2-8774-5862-a9d9-4695ec319c0d', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 27, 27, 'These are the families of the Zebulunites according to those who were numbered of them, sixty thousand five hundred.'),
  ('29d5331c-f002-53c6-a4e2-c5d694a2d463', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 28, 28, 'The sons of Joseph after their families: Manasseh and Ephraim.'),
  ('def6338c-7fff-5df8-af88-0c444090e067', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 29, 29, 'The sons of Manasseh: of Machir, the family of the Machirites; and Machir became the father of Gilead; of Gilead, the family of the Gileadites.'),
  ('313836ef-f826-57ba-aee2-94a1d69b8704', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 30, 30, 'These are the sons of Gilead: [of] Iezer, the family of the Iezerites; of Helek, the family of the Helekites;'),
  ('99440cd8-07c2-5bf6-ad24-86d69c6d661e', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 31, 31, 'and [of] Asriel, the family of the Asrielites; and [of] Shechem, the family of the Shechemites;'),
  ('88c11694-b822-57e5-aa37-bbc6cf69da32', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 32, 32, 'and [of] Shemida, the family of the Shemidaites; and [of] Hepher, the family of the Hepherites.'),
  ('9d98edd8-e8d5-517d-a20e-73a78cf64586', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 33, 33, 'Zelophehad the son of Hepher had no sons, but daughters: and the names of the daughters of Zelophehad were Mahlah, and Noah, Hoglah, Milcah, and Tirzah.'),
  ('3dba1d8d-b6e5-579b-a642-56df73d96fcb', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 34, 34, 'These are the families of Manasseh; and those who were numbered of them were fifty-two thousand seven hundred.'),
  ('61284916-402b-5cd9-ac48-fefeea863191', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 35, 35, 'These are the sons of Ephraim after their families: of Shuthelah, the family of the Shuthelahites; of Becher, the family of the Becherites; of Tahan, the family of the Tahanites.'),
  ('acdf1fcb-e48f-5986-ae34-86e6cae1477c', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 36, 36, 'These are the sons of Shuthelah: of Eran, the family of the Eranites.'),
  ('433fa751-6d72-53ea-a327-6b80de1ec22a', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 37, 37, 'These are the families of the sons of Ephraim according to those who were numbered of them, thirty-two thousand five hundred. These are the sons of Joseph after their families.'),
  ('808ef070-400d-50e0-a8e3-d152638e954a', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 38, 38, 'The sons of Benjamin after their families: of Bela, the family of the Belaites; of Ashbel, the family of the Ashbelites; of Ahiram, the family of the Ahiramites;'),
  ('9dd8c502-3b9c-5cc4-a2cb-164c4f38e78e', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 39, 39, 'of Shephupham, the family of the Shuphamites; of Hupham, the family of the Huphamites.'),
  ('e997e207-ddd7-5ad6-a1d9-fd14ff244a06', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 40, 40, 'The sons of Bela were Ard and Naaman: [of Ard], the family of the Ardites; of Naaman, the family of the Naamites.'),
  ('ccc0c8b2-d513-5972-af2d-eab94e9c9846', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 41, 41, 'These are the sons of Benjamin after their families; and those who were numbered of them were forty-five thousand six hundred.'),
  ('78ebc968-b0b7-5244-ac06-26f1a6e1c575', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 42, 42, 'These are the sons of Dan after their families: of Shuham, the family of the Shuhamites. These are the families of Dan after their families.'),
  ('b8b0bde5-f1db-5e7c-a353-c89c147c5c7a', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 43, 43, 'All the families of the Shuhamites, according to those who were numbered of them, were sixty-four thousand four hundred.'),
  ('188916dd-66b4-5ad7-a5aa-4910a832bb4d', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 44, 44, 'The sons of Asher after their families: of Imnah, the family of the Imnites; of Ishvi, the family of the Ishvites; of Beriah, the family of the Berites.'),
  ('e27ee585-da4d-505a-abf3-041a468f1aea', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 45, 45, 'Of the sons of Beriah: of Heber, the family of the Heberites; of Malchiel, the family of the Malchielites.'),
  ('3b2f850d-135d-591f-ae0d-b49d5b92f386', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 46, 46, 'The name of the daughter of Asher was Serah.'),
  ('e04aab29-1be3-57bb-a359-ec0e60be081d', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 47, 47, 'These are the families of the sons of Asher according to those who were numbered of them, fifty-three thousand and four hundred.'),
  ('0ce45e12-9ded-533d-ab61-edbee7f317ff', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 48, 48, 'The sons of Naphtali after their families: of Jahzeel, the family of the Jahzeelites; of Guni, the family of the Gunites;'),
  ('b7e9af0f-c5df-5eca-a83f-b95ee147e347', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 49, 49, 'of Jezer, the family of the Jezerites; of Shillem, the family of the Shillemites.'),
  ('c2a16342-d412-5383-a27a-77e47404428d', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 50, 50, 'These are the families of Naphtali according to their families; and those who were numbered of them were forty-five thousand four hundred.'),
  ('2ad62506-4dfb-5ee7-ac06-a3c9113a2984', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 51, 51, 'These are those who were numbered of the children of Israel, six hundred one thousand seven hundred thirty.'),
  ('e49d2325-a504-5474-aca6-f609b40d834e', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 52, 52, 'Yahweh spoke to Moses, saying,'),
  ('a59ab7bb-c398-5f16-a00e-b9a9632ca159', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 53, 53, '"To these the land shall be divided for an inheritance according to the number of names.'),
  ('4ea42a71-9bfd-5c75-ac03-a9999ae7001c', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 54, 54, 'To the more you shall give the more inheritance, and to the fewer you shall give the less inheritance: to everyone according to those who were numbered of him shall his inheritance be given.'),
  ('b49fd511-0240-5f17-a4f1-847d22ad6c00', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 55, 55, 'Notwithstanding, the land shall be divided by lot: according to the names of the tribes of their fathers they shall inherit.'),
  ('8f621dcf-9af2-575f-ab7f-f721f6d97eb1', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 56, 56, 'According to the lot shall their inheritance be divided between the more and the fewer."'),
  ('e530e9d2-1710-5fd3-acf5-3e5cf52be9a8', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 57, 57, 'These are those who were numbered of the Levites after their families: of Gershon, the family of the Gershonites; of Kohath, the family of the Kohathites; of Merari, the family of the Merarites.'),
  ('8ceb1e3f-fd77-5ded-ad76-26d153afe681', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 58, 58, 'These are the families of Levi: the family of the Libnites, the family of the Hebronites, the family of the Mahlites, the family of the Mushites, the family of the Korahites. Kohath became the father of Amram.'),
  ('f8869976-deda-51f7-aef4-ed0d0eff95a0', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 59, 59, 'The name of Amram''s wife was Jochebed, the daughter of Levi, who was born to Levi in Egypt: and she bore to Amram Aaron and Moses, and Miriam their sister.'),
  ('9bf98c73-122a-51bc-acbc-58281c0a45b7', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 60, 60, 'To Aaron were born Nadab and Abihu, Eleazar and Ithamar.'),
  ('458a6c77-cf4a-5135-ab8f-1a08b468e0f2', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 61, 61, 'Nadab and Abihu died, when they offered strange fire before Yahweh.'),
  ('d4e89162-9dfb-535d-a715-b763b2833a2d', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 62, 62, 'Those who were numbered of them were twenty-three thousand, every male from a month old and upward: for they were not numbered among the children of Israel, because there was no inheritance given them among the children of Israel.'),
  ('56634567-87e9-5409-abd7-4dfb6cd44252', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 63, 63, 'These are those who were numbered by Moses and Eleazar the priest, who numbered the children of Israel in the plains of Moab by the Jordan at Jericho.'),
  ('f5f8d094-64c6-55c7-a1e6-89c3f6272b47', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 64, 64, 'But among these there was not a man of them who were numbered by Moses and Aaron the priest, who numbered the children of Israel in the wilderness of Sinai.'),
  ('5c380288-0bb9-56e2-a386-6ee294b9c637', '825c1d40-7f1f-5ca9-a57b-ec24d7a271c2', NULL, 65, 65, 'For Yahweh had said of them, They shall surely die in the wilderness. There was not left a man of them, except Caleb the son of Jephunneh, and Joshua the son of Nun.'),
  ('c30f9e93-49f3-5dd3-add4-8efc711d971e', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 1, 1, 'Then drew near the daughters of Zelophehad, the son of Hepher, the son of Gilead, the son of Machir, the son of Manasseh, of the families of Manasseh the son of Joseph; and these are the names of his daughters: Mahlah, Noah, and Hoglah, and Milcah, and Tirzah.'),
  ('cec20902-2d48-5cba-a81f-f6c08550c6a2', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 2, 2, 'They stood before Moses, and before Eleazar the priest, and before the princes and all the congregation, at the door of the Tent of Meeting, saying,'),
  ('4788d70e-17f8-5ccb-a89a-477758ed1c4e', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 3, 3, '"Our father died in the wilderness, and he was not among the company of those who gathered themselves together against Yahweh in the company of Korah: but he died in his own sin; and he had no sons.'),
  ('fc9aac37-3a4f-506e-a1ef-8c533cbf8b33', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 4, 4, 'Why should the name of our father be taken away from among his family, because he had no son? Give to us a possession among the brothers of our father."'),
  ('063a3f03-4894-563c-a0c2-b9c046aa7c69', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 5, 5, 'Moses brought their cause before Yahweh.'),
  ('21f80d45-ac1b-5238-ad26-613ccd55a2f4', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 6, 6, 'Yahweh spoke to Moses, saying,'),
  ('75109dfd-1935-59ce-aede-9d5ed2772c2d', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 7, 7, '"The daughters of Zelophehad speak right: you shall surely give them a possession of an inheritance among their father''s brothers; and you shall cause the inheritance of their father to pass to them.'),
  ('fbe0a2c1-fabc-5a7f-a9be-e8783fcdbd38', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 8, 8, 'You shall speak to the children of Israel, saying, ''If a man dies, and has no son, then you shall cause his inheritance to pass to his daughter.'),
  ('72b9637e-6e20-5752-a99f-09b478269e9b', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 9, 9, 'If he has no daughter, then you shall give his inheritance to his brothers.'),
  ('c3e8cd8d-4760-555a-a155-8f32b0eff6a5', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 10, 10, 'If he has no brothers, then you shall give his inheritance to his father''s brothers.'),
  ('06bab50e-d66a-5635-a772-6c08014c4a04', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 11, 11, 'If his father has no brothers, then you shall give his inheritance to his kinsman who is next to him of his family, and he shall possess it: and it shall be to the children of Israel a statute [and] ordinance, as Yahweh commanded Moses.''"'),
  ('fc595bff-3c31-5ae3-a0a0-45dab910579f', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 12, 12, 'Yahweh said to Moses, "Go up into this mountain of Abarim, and see the land which I have given to the children of Israel.'),
  ('9b340fda-3711-583d-a557-386d0c5a7838', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 13, 13, 'When you have seen it, you also shall be gathered to your people, as Aaron your brother was gathered;'),
  ('6a5dedcc-40d6-54d1-af7a-44c425d80d38', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 14, 14, 'because you rebelled against my word in the wilderness of Zin, in the strife of the congregation, to sanctify me at the waters before their eyes." (These are the waters of Meribah of Kadesh in the wilderness of Zin.)'),
  ('c5f0ba6a-dd1f-595c-a996-019f7b6c2b94', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 15, 15, 'Moses spoke to Yahweh, saying,'),
  ('c38638c3-eaa0-5b7f-a93b-b37d40ea0d9d', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 16, 16, '"Let Yahweh, the God of the spirits of all flesh, appoint a man over the congregation,'),
  ('060131af-1385-5188-a160-87e22b3a2f8c', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 17, 17, 'who may go out before them, and who may come in before them, and who may lead them out, and who may bring them in; that the congregation of Yahweh not be as sheep which have no shepherd."'),
  ('977505ed-9c92-5222-a9a0-f467077c4261', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 18, 18, 'Yahweh said to Moses, "Take Joshua the son of Nun, a man in whom is the Spirit, and lay your hand on him;'),
  ('3309e55d-5011-50c8-ae0a-a01b923bbe25', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 19, 19, 'and set him before Eleazar the priest, and before all the congregation; and commission him in their sight.'),
  ('1d73f0a7-83df-54b4-a950-927d89396c71', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 20, 20, 'You shall put of your honor on him, that all the congregation of the children of Israel may obey.'),
  ('cdcdacc1-2783-597c-a303-e8318d81f7fa', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 21, 21, 'He shall stand before Eleazar the priest, who shall inquire for him by the judgment of the Urim before Yahweh: at his word shall they go out, and at his word they shall come in, both he, and all the children of Israel with him, even all the congregation."'),
  ('d338c01a-1426-5a8b-a72c-88a4aa87573d', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 22, 22, 'Moses did as Yahweh commanded him; and he took Joshua, and set him before Eleazar the priest, and before all the congregation:'),
  ('ba4f1ad6-4af6-5a80-a97d-b537ccc4ccfa', '3285eebe-65df-57b5-a489-e812e81301f7', NULL, 23, 23, 'and he laid his hands on him, and commissioned him, as Yahweh spoke by Moses.'),
  ('11d0f7ad-2078-56b5-ad6f-fbefac4628f1', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('ebfab405-3088-5cea-af4d-c72b5c021a4e', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 2, 2, '"Command the children of Israel, and tell them, ''My offering, my food for my offerings made by fire, of a pleasant aroma to me, you shall observe to offer to me in their due season.'''),
  ('f1bf3199-3701-5d47-a7dc-04720fa4913a', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 3, 3, 'You shall tell them, ''This is the offering made by fire which you shall offer to Yahweh: male lambs a year old without blemish, two day by day, for a continual burnt offering.'),
  ('bac8b20d-0f22-56ec-a6e8-38f72c1eb044', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 4, 4, 'You shall offer the one lamb in the morning, and you shall offer the other lamb at evening;'),
  ('235bd389-9c18-5a77-ae71-5399884f0e2e', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 5, 5, 'with the tenth part of an ephah of fine flour for a meal offering, mixed with the fourth part of a hin of beaten oil.'),
  ('da6c9642-ecb1-5e68-aaa7-d479c139fe86', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 6, 6, 'It is a continual burnt offering, which was ordained in Mount Sinai for a pleasant aroma, an offering made by fire to Yahweh.'),
  ('aac333b6-da4c-5e85-a173-c6a78a1a834b', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 7, 7, 'Its drink offering shall be the fourth part of a hin for the one lamb. You shall pour out a drink offering of strong drink to Yahweh in the holy place.'),
  ('1511d5fb-a24a-5ce8-ae65-b6711eabf88e', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 8, 8, 'The other lamb you shall offer at evening: as the meal offering of the morning, and as the drink offering of it, you shall offer it, an offering made by fire, of a pleasant aroma to Yahweh.'),
  ('34f3282c-3cb4-5d8a-a304-bed224755934', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 9, 9, '"''On the Sabbath day two male lambs a year old without blemish, and two tenth parts [of an ephah] of fine flour for a meal offering, mixed with oil, and the drink offering of it:'),
  ('2345bc1d-1095-5374-a97b-f882c70c6f23', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 10, 10, 'this is the burnt offering of every Sabbath, besides the continual burnt offering, and the drink offering of it.'),
  ('679d9966-84aa-5fdb-aca9-78235e699d1d', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 11, 11, '"''In the beginnings of your months you shall offer a burnt offering to Yahweh: two young bulls, and one ram, seven male lambs a year old without blemish;'),
  ('6b0c5cf1-37c8-5234-ae8b-c599c6b0cbfb', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 12, 12, 'and three tenth parts [of an ephah] of fine flour for a meal offering, mixed with oil, for each bull; and two tenth parts of fine flour for a meal offering, mixed with oil, for the one ram;'),
  ('6d4de6ab-29f6-53d4-a27c-7e7f7b89fd6e', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 13, 13, 'and a tenth part of fine flour mixed with oil for a meal offering to every lamb; for a burnt offering of a pleasant aroma, an offering made by fire to Yahweh.'),
  ('5445c8c1-5bd8-5b37-a4c2-c20e85d908c0', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 14, 14, 'Their drink offerings shall be half a hin of wine for a bull, and the third part of a hin for the ram, and the fourth part of a hin for a lamb: this is the burnt offering of every month throughout the months of the year.'),
  ('a8a09529-eb8f-5618-aea7-02794315913b', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 15, 15, 'One male goat for a sin offering to Yahweh; it shall be offered besides the continual burnt offering, and the drink offering of it.'),
  ('9e46eac4-ca91-55cc-af05-cdfb5b564aab', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 16, 16, '"''In the first month, on the fourteenth day of the month, is Yahweh''s Passover.'),
  ('2acdfef5-a460-56f3-a963-add8cc43076e', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 17, 17, 'On the fifteenth day of this month shall be a feast: seven days shall unleavened bread be eaten.'),
  ('f8798186-f251-5dae-ad01-5611f2f4cc1c', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 18, 18, 'In the first day shall be a holy convocation: you shall do no servile work;'),
  ('4397c7af-ab0c-56c7-a465-a3feffe61e7a', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 19, 19, 'but you shall offer an offering made by fire, a burnt offering to Yahweh: two young bulls, and one ram, and seven male lambs a year old; they shall be to you without blemish;'),
  ('ee3b55c0-d701-576a-a068-4aeb635bb0fe', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 20, 20, 'and their meal offering, fine flour mixed with oil: you shall offer three tenth parts for a bull, and two tenth parts for the ram.'),
  ('0c0d59ff-9e93-5cbe-a9f3-acfa8445608b', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 21, 21, 'You shall offer a tenth part for every lamb of the seven lambs;'),
  ('1560da01-a514-5d76-a4da-064223c98c3b', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 22, 22, 'and one male goat for a sin offering, to make atonement for you.'),
  ('f76a7c7a-0150-5461-a037-2627b60c25ab', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 23, 23, 'You shall offer these besides the burnt offering of the morning, which is for a continual burnt offering.'),
  ('2a8395d9-f454-594c-a8ad-6c68f4e41309', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 24, 24, 'In this way you shall offer daily, for seven days, the food of the offering made by fire, of a pleasant aroma to Yahweh: it shall be offered besides the continual burnt offering, and the drink offering of it.'),
  ('33e72f19-675c-5342-a471-c2afc7860946', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 25, 25, 'On the seventh day you shall have a holy convocation: you shall do no servile work.'),
  ('66e67936-f877-5147-a55f-639c831ffe7d', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 26, 26, '"''Also in the day of the first fruits, when you offer a new meal offering to Yahweh in your [feast of] weeks, you shall have a holy convocation; you shall do no servile work;'),
  ('66299f75-b9dc-52e6-ad6a-93666ea2ebe2', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 27, 27, 'but you shall offer a burnt offering for a pleasant aroma to Yahweh: two young bulls, one ram, seven male lambs a year old;'),
  ('ef23b38f-3ba5-5a65-afa2-d187bc80d5c4', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 28, 28, 'and their meal offering, fine flour mixed with oil, three tenth parts for each bull, two tenth parts for the one ram,'),
  ('df435feb-2184-5a4b-a60c-c31c129173e2', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 29, 29, 'a tenth part for every lamb of the seven lambs;'),
  ('ee86cbe7-5911-5ae7-a5bb-e1e002b04890', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 30, 30, 'one male goat, to make atonement for you.'),
  ('1e7bd323-1904-5d82-a9fe-5f49d7fe290f', '729d67d0-faf1-5722-a6f5-e2677d291114', NULL, 31, 31, 'Besides the continual burnt offering, and the meal offering of it, you shall offer them (they shall be to you without blemish), and their drink offerings.'),
  ('7070a19d-8b10-545d-af93-c7580c786e94', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 1, 1, '"''In the seventh month, on the first day of the month, you shall have a holy convocation; you shall do no servile work: it is a day of blowing of trumpets to you.'),
  ('e17ba4e4-7aa9-5ee3-a660-ab8fe006ea69', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 2, 2, 'You shall offer a burnt offering for a pleasant aroma to Yahweh: one young bull, one ram, seven male lambs a year old without blemish;')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('1ba11277-2116-5984-a775-764d932ce251', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 3, 3, 'and their meal offering, fine flour mixed with oil, three tenth parts for the bull, two tenth parts for the ram,'),
  ('babab313-a4e7-5772-a092-40157e54c8de', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 4, 4, 'and one tenth part for every lamb of the seven lambs;'),
  ('b8f6bb2c-ca91-5398-ae3b-1ea748a83ed3', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 5, 5, 'and one male goat for a sin offering, to make atonement for you;'),
  ('b8df0cf6-0672-55d9-abe3-96eded02a51b', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 6, 6, 'besides the burnt offering of the new moon, and the meal offering of it, and the continual burnt offering and the meal offering of it, and their drink offerings, according to their ordinance, for a pleasant aroma, an offering made by fire to Yahweh.'),
  ('e0b8acb4-2dc3-554e-a5c5-6709be2b9b05', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 7, 7, '"''On the tenth day of this seventh month you shall have a holy convocation; and you shall afflict your souls: you shall do no kind of work;'),
  ('e986bdb1-08e3-5351-a78b-cf252840f76a', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 8, 8, 'but you shall offer a burnt offering to Yahweh for a pleasant aroma: one young bull, one ram, seven male lambs a year old; they shall be to you without blemish;'),
  ('275ce01b-72bc-5e87-aae4-9d59effb0743', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 9, 9, 'and their meal offering, fine flour mixed with oil, three tenth parts for the bull, two tenth parts for the one ram,'),
  ('e7313dd4-ff48-5eac-a3e9-4e811b0b318e', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 10, 10, 'a tenth part for every lamb of the seven lambs:'),
  ('58dc36d1-e68a-58dc-a088-d3caf5447902', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 11, 11, 'one male goat for a sin offering; besides the sin offering of atonement, and the continual burnt offering, and the meal offering of it, and their drink offerings.'),
  ('71c3d88d-4f41-5acd-a0ff-904d8576dd5a', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 12, 12, '"''On the fifteenth day of the seventh month you shall have a holy convocation; you shall do no servile work, and you shall keep a feast to Yahweh seven days:'),
  ('4a8ab016-fc96-503b-a33f-eb2a4255a9d1', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 13, 13, 'and you shall offer a burnt offering, an offering made by fire, of a pleasant aroma to Yahweh; thirteen young bulls, two rams, fourteen male lambs a year old; they shall be without blemish;'),
  ('fa99b174-d776-571e-aafb-69aea8572c61', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 14, 14, 'and their meal offering, fine flour mixed with oil, three tenth parts for every bull of the thirteen bulls, two tenth parts for each ram of the two rams,'),
  ('c851b8f9-73de-5a5b-a0ec-4031b58d1e49', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 15, 15, 'and a tenth part for every lamb of the fourteen lambs;'),
  ('3c829bd5-ccc4-514d-a737-6be7014658f5', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 16, 16, 'and one male goat for a sin offering, besides the continual burnt offering, the meal offering of it, and the drink offering of it.'),
  ('c38179c4-fd94-5678-a26b-58efe1da9b0b', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 17, 17, '"''On the second day [you shall offer] twelve young bulls, two rams, fourteen male lambs a year old without blemish;'),
  ('3d3c7715-d251-5803-a188-12215775fafa', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 18, 18, 'and their meal offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number, after the ordinance;'),
  ('4a6de237-c540-58b9-aa53-ee6184ff5d63', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 19, 19, 'and one male goat for a sin offering; besides the continual burnt offering, and the meal offering of it, and their drink offerings.'),
  ('45cfd121-780a-5428-aa9f-a05175b8a169', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 20, 20, '"''On the third day eleven bulls, two rams, fourteen male lambs a year old without blemish;'),
  ('4ac4b3d5-3c72-5bdf-a141-21a212379553', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 21, 21, 'and their meal offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number, after the ordinance;'),
  ('8510a25d-fac0-541d-aaab-668c51bdd369', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 22, 22, 'and one male goat for a sin offering; besides the continual burnt offering, and the meal offering of it, and the drink offering of it.'),
  ('e255ce7d-7fa2-50bb-a931-8db35633baa4', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 23, 23, '"''On the fourth day ten bulls, two rams, fourteen male lambs a year old without blemish;'),
  ('3e14db90-3de6-5f43-aaf5-39140d2218d7', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 24, 24, 'their meal offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number, after the ordinance;'),
  ('2c28154d-8d7f-5247-ae25-a08150673c12', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 25, 25, 'and one male goat for a sin offering; besides the continual burnt offering, the meal offering of it, and the drink offering of it.'),
  ('e5df2978-fffc-53e3-a0eb-e3186375a1d0', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 26, 26, '"''On the fifth day nine bulls, two rams, fourteen male lambs a year old without blemish;'),
  ('0116f88e-1c26-53ab-ab3e-dc6c9f5b83ed', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 27, 27, 'and their meal offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number, after the ordinance;'),
  ('02ad439d-0de1-5ff1-a823-086d8fdeb662', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 28, 28, 'and one male goat for a sin offering, besides the continual burnt offering, and the meal offering of it, and the drink offering of it.'),
  ('ad778b14-614a-509d-a8f2-0bd69c4749ab', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 29, 29, '"''On the sixth day eight bulls, two rams, fourteen male lambs a year old without blemish;'),
  ('b6c2a051-7052-520c-a678-28b69d13da8d', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 30, 30, 'and their meal offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number, after the ordinance;'),
  ('6adb7e72-45fd-53c4-a9b7-7704c4acfd7b', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 31, 31, 'and one male goat for a sin offering; besides the continual burnt offering, the meal offering of it, and the drink offerings of it.'),
  ('1cba3ca9-b298-54b8-aaf9-877bc32cdf72', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 32, 32, '"''On the seventh day seven bulls, two rams, fourteen male lambs a year old without blemish;'),
  ('67f0cc4f-d079-5b5a-af16-56024407a672', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 33, 33, 'and their meal offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number, after the ordinance;'),
  ('f9a55146-0b89-51d5-a33d-16b6b9aebea1', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 34, 34, 'and one male goat for a sin offering; besides the continual burnt offering, the meal offering of it, and the drink offering of it.'),
  ('aa9ad6ca-7c5a-539d-aa8a-2011af6b8dcc', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 35, 35, '"''On the eighth day you shall have a solemn assembly: you shall do no servile work;'),
  ('6489cbfd-590d-58f3-af89-a052317221c7', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 36, 36, 'but you shall offer a burnt offering, an offering made by fire, of a pleasant aroma to Yahweh: one bull, one ram, seven male lambs a year old without blemish;'),
  ('b936ee93-db78-528a-ac15-82a54cd9843f', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 37, 37, 'their meal offering and their drink offerings for the bull, for the ram, and for the lambs, shall be according to their number, after the ordinance:'),
  ('a111152a-c66b-58be-aa2c-8c8f1e779c83', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 38, 38, 'and one male goat for a sin offering, besides the continual burnt offering, and the meal offering of it, and the drink offering of it.'),
  ('46577d60-0217-57e8-a3bf-e2fd00b741cf', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 39, 39, '"''You shall offer these to Yahweh in your set feasts, besides your vows, and your freewill offerings, for your burnt offerings, and for your meal offerings, and for your drink offerings, and for your peace offerings.''"'),
  ('1f84d1ac-dfea-5fe0-a9ae-22103af27a5c', 'ca5e0e04-260f-5ef0-acc9-e1f3bef08c29', NULL, 40, 40, 'Moses told the children of Israel according to all that Yahweh commanded Moses.'),
  ('98a47671-b55d-5cb4-a53b-b8bc535d1d09', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 1, 1, 'Moses spoke to the heads of the tribes of the children of Israel, saying, "This is the thing which Yahweh has commanded.'),
  ('6d1f7c87-9258-5931-accd-662f01591fc4', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 2, 2, 'When a man vows a vow to Yahweh, or swears an oath to bind his soul with a bond, he shall not break his word; he shall do according to all that proceeds out of his mouth.'),
  ('1ff9b241-262a-5d66-adc0-7c9c879915ec', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 3, 3, '"Also when a woman vows a vow to Yahweh, and binds herself by a bond, being in her father''s house, in her youth,'),
  ('ec9ad58e-aede-583c-ad92-565d10e59a7c', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 4, 4, 'and her father hears her vow, and her bond with which she has bound her soul, and her father holds his peace at her; then all her vows shall stand, and every bond with which she has bound her soul shall stand.'),
  ('ce364146-aa25-5bbc-ae7a-46721ee78414', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 5, 5, 'But if her father disallow her in the day that he hears, none of her vows, or of her bonds with which she has bound her soul, shall stand: and Yahweh will forgive her, because her father disallowed her.'),
  ('fa7749b8-0ff3-5de3-aa59-038240de6882', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 6, 6, '"If she is [married] to a husband, while her vows are on her, or the rash utterance of her lips, with which she has bound her soul,'),
  ('9c093f46-d3a6-550b-a683-226dbb490ad0', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 7, 7, 'and her husband hear it, and hold his peace at her in the day that he hears it; then her vows shall stand, and her bonds with which she has bound her soul shall stand.'),
  ('001ddd6f-faa4-5815-aa97-ffd45e1155e3', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 8, 8, 'But if her husband disallow her in the day that he hears it, then he shall make void her vow which is on her, and the rash utterance of her lips, with which she has bound her soul: and Yahweh will forgive her.'),
  ('638a2034-2ac8-5f49-af52-dbd2df08b4b8', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 9, 9, '"But the vow of a widow, or of her who is divorced, [even] everything with which she has bound her soul, shall stand against her.'),
  ('56865be0-6d36-5009-a81e-ea48960a9428', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 10, 10, '"If she vowed in her husband''s house, or bound her soul by a bond with an oath,'),
  ('2704795a-cdb4-5f84-a093-f7acd8dcbbf0', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 11, 11, 'and her husband heard it, and held his peace at her, and didn''t disallow her; then all her vows shall stand, and every bond with which she bound her soul shall stand.'),
  ('8a0e546f-cd5d-56b4-a504-8b2dc77bab1c', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 12, 12, 'But if her husband made them null and void in the day that he heard them, then whatever proceeded out of her lips concerning her vows, or concerning the bond of her soul, shall not stand: her husband has made them void; and Yahweh will forgive her.'),
  ('da660dab-2e2e-5570-a8e6-ac5e3430e745', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 13, 13, 'Every vow, and every binding oath to afflict the soul, her husband may establish it, or her husband may make it void.'),
  ('dddf7e09-d719-54d1-afd6-55fc6d3060d2', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 14, 14, 'But if her husband altogether hold his peace at her from day to day, then he establishes all her vows, or all her bonds, which are on her: he has established them, because he held his peace at her in the day that he heard them.'),
  ('94372792-e052-53d4-a847-df5c910d6e43', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 15, 15, 'But if he shall make them null and void after that he has heard them, then he shall bear her iniquity."'),
  ('f882d59a-7c52-5c0a-a37f-318f30220e20', '22bef077-e131-5b84-a0dc-8e5d702502b5', NULL, 16, 16, 'These are the statutes, which Yahweh commanded Moses, between a man and his wife, between a father and his daughter, being in her youth, in her father''s house.'),
  ('195f96e5-a01c-5e07-a1c1-128d89edc287', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('b57b84c1-acc8-5f9f-aa1a-41f97799562d', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 2, 2, '"Avenge the children of Israel for the Midianites. Afterward you shall be gathered to your people."'),
  ('f820683c-b788-5f5a-a15c-6b6a9d7a464c', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 3, 3, 'Moses spoke to the people, saying, "Arm men from among you for the war, that they may go against Midian, to execute Yahweh''s vengeance on Midian.'),
  ('5ec6a00a-e616-5ca3-a7da-e67cd01a01b8', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 4, 4, 'Of every tribe one thousand, throughout all the tribes of Israel, you shall send to the war."'),
  ('9838ecca-b5c7-587b-af62-306a93ae9d1e', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 5, 5, 'So there were delivered, out of the thousands of Israel, a thousand of every tribe, twelve thousand armed for war.'),
  ('c610e36a-61b1-5706-acdc-c457eefe1d88', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 6, 6, 'Moses sent them, one thousand of every tribe, to the war, them and Phinehas the son of Eleazar the priest, to the war, with the vessels of the sanctuary and the trumpets for the alarm in his hand.'),
  ('e7a08697-6953-53da-addd-3d346a969e4a', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 7, 7, 'They warred against Midian, as Yahweh commanded Moses; and they killed every male.'),
  ('87a62d8c-8105-53f1-a0cd-1337500fb9fd', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 8, 8, 'They killed the kings of Midian with the rest of their slain: Evi, and Rekem, and Zur, and Hur, and Reba, the five kings of Midian: Balaam also the son of Beor they killed with the sword.'),
  ('dc9dfbb0-69ac-527e-a4bb-8825fb9ea815', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 9, 9, 'The children of Israel took captive the women of Midian and their little ones; and all their livestock, and all their flocks, and all their goods, they took for a prey.'),
  ('61f49792-81ed-5bee-a6b9-dc9fa5c2faab', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 10, 10, 'All their cities in the places in which they lived, and all their encampments, they burnt with fire.'),
  ('5f95d92a-3bc1-57c0-aa41-644612bba4b1', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 11, 11, 'They took all the spoil, and all the prey, both of man and of animal.'),
  ('e88fb136-6d65-529a-a3d1-55443dbabb73', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 12, 12, 'They brought the captives, and the prey, and the spoil, to Moses, and to Eleazar the priest, and to the congregation of the children of Israel, to the camp at the plains of Moab, which are by the Jordan at Jericho.'),
  ('e54b038f-3479-572a-a7fa-463d190d9089', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 13, 13, 'Moses, and Eleazar the priest, and all the princes of the congregation, went forth to meet them outside of the camp.'),
  ('bf8f2796-cc67-5b63-abd2-0db7619c220c', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 14, 14, 'Moses was angry with the officers of the army, the captains of thousands and the captains of hundreds, who came from the service of the war.'),
  ('13924e45-ba6c-5f80-aed0-cb09e08dbccd', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 15, 15, 'Moses said to them, "Have you saved all the women alive?'),
  ('5789dcfc-4279-513a-a30a-5539bff0b3f0', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 16, 16, 'Behold, these caused the children of Israel, through the counsel of Balaam, to commit trespass against Yahweh in the matter of Peor, and so the plague was among the congregation of Yahweh.'),
  ('3943b18d-7a30-5dce-a953-98606b7d7515', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 17, 17, 'Now therefore kill every male among the little ones, and kill every woman who has known man by lying with him.'),
  ('a8e162f4-0592-5542-a787-c60437bd037a', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 18, 18, 'But all the girls, who have not known man by lying with him, keep alive for yourselves.'),
  ('471b43e6-2e35-52cf-ada0-66fd62221502', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 19, 19, '"Encamp outside of the camp seven days: whoever has killed any person, and whoever has touched any slain, purify yourselves on the third day and on the seventh day, you and your captives.'),
  ('4f7b72ce-915a-5eb8-a0df-bdac60f88799', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 20, 20, 'As to every garment, and all that is made of skin, and all work of goats'' [hair], and all things made of wood, you shall purify yourselves."'),
  ('cf380ff2-7643-57be-a3a4-6f3bdde675fb', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 21, 21, 'Eleazar the priest said to the men of war who went to the battle, "This is the statute of the law which Yahweh has commanded Moses:'),
  ('4ddcdf75-3a20-5a97-aa76-6512ab430206', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 22, 22, 'however the gold, and the silver, the brass, the iron, the tin, and the lead,'),
  ('85d234aa-7e1d-5249-a607-ee846f0bdb20', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 23, 23, 'everything that may withstand the fire, you shall make to go through the fire, and it shall be clean; nevertheless it shall be purified with the water for impurity: and all that doesn''t withstand the fire you shall make to go through the water.'),
  ('e3ab9abb-08f9-50e6-adfc-32ba83d5500e', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 24, 24, 'You shall wash your clothes on the seventh day, and you shall be clean; and afterward you shall come into the camp."'),
  ('fb5a50e4-1d3d-5441-a434-152e13e65417', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 25, 25, 'Yahweh spoke to Moses, saying,'),
  ('86cd1a5e-c18b-5df1-a49f-88f806a207c9', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 26, 26, '"Take the sum of the prey that was taken, both of man and of animal, you, and Eleazar the priest, and the heads of the fathers'' [houses] of the congregation;'),
  ('649db623-aebb-5de2-ae66-da6c62e496e3', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 27, 27, 'and divide the prey into two parts: between the men skilled in war, who went out to battle, and all the congregation.'),
  ('f04db681-5449-58a3-a471-c13fd5df3f79', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 28, 28, 'Levy a tribute to Yahweh of the men of war who went out to battle: one soul of five hundred, [both] of the persons, and of the cattle, and of the donkeys, and of the flocks:'),
  ('93c70c2a-31e4-53dd-ab69-4cce36e5b054', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 29, 29, 'take it of their half, and give it to Eleazar the priest, for Yahweh''s wave offering.'),
  ('d00030f6-3e80-57ec-a9f7-e775960a23ec', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 30, 30, 'Of the children of Israel''s half, you shall take one drawn out of every fifty, of the persons, of the cattle, of the donkeys, and of the flocks, [even] of all the livestock, and give them to the Levites, who perform the duty of the tabernacle of Yahweh."'),
  ('7d9590fa-21c4-5cee-a16c-0dac6030d791', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 31, 31, 'Moses and Eleazar the priest did as Yahweh commanded Moses.'),
  ('b02dbc4f-7111-5280-a1a5-e5f82b9bcbc7', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 32, 32, 'Now the prey, over and above the booty which the men of war took, was six hundred seventy-five thousand sheep,'),
  ('3f94ce14-e1f5-5e24-a0f1-4ba114bad463', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 33, 33, 'and seventy-two thousand head of cattle,'),
  ('6e7a8594-5e35-5729-a05f-df05ac1e7392', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 34, 34, 'and sixty-one thousand donkeys,'),
  ('04961f47-5e8f-51c8-aae2-8231194f112a', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 35, 35, 'and thirty-two thousand persons in all, of the women who had not known man by lying with him.'),
  ('ff34355a-7731-5f5f-a83f-30b1e922a1da', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 36, 36, 'The half, which was the portion of those who went out to war, was in number three hundred thirty-seven thousand five hundred sheep:'),
  ('37edfccc-294f-5120-ac25-2d810202280f', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 37, 37, 'and Yahweh''s tribute of the sheep was six hundred seventy-five.'),
  ('411e6239-d7c3-5ebd-a81d-45439d35b40f', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 38, 38, 'The cattle were thirty-six thousand; of which Yahweh''s tribute was seventy-two.'),
  ('e6e22ee9-d84b-5b19-a3f8-ad39e72c0ec4', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 39, 39, 'The donkeys were thirty thousand five hundred; of which Yahweh''s tribute was sixty-one.'),
  ('eb5a88be-35cb-5d1f-a92d-49fa59a720b3', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 40, 40, 'The persons were sixteen thousand; of whom Yahweh''s tribute was thirty-two persons.'),
  ('98f61420-bbe3-508e-ada1-83980d5f1e0c', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 41, 41, 'Moses gave the tribute, which was Yahweh''s wave offering, to Eleazar the priest, as Yahweh commanded Moses.'),
  ('0d7f16c0-788b-5067-a26c-558bfc862495', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 42, 42, 'Of the children of Israel''s half, which Moses divided off from the men who warred'),
  ('f9be7c3d-2cad-57ed-a536-a4f13460d525', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 43, 43, '(now the congregation''s half was three hundred thirty-seven thousand five hundred sheep,'),
  ('aac7c82d-11de-5cf8-a795-db69b38b8918', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 44, 44, 'and thirty-six thousand head of cattle,'),
  ('55bd7405-966b-57fa-a86a-800b9d8f9702', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 45, 45, 'and thirty thousand five hundred donkeys,'),
  ('d19f773f-a1ca-5162-a4fb-2c1503635389', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 46, 46, 'and sixteen thousand persons),'),
  ('ba52ee18-d72b-574e-a8c9-4a10737afcc7', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 47, 47, 'even of the children of Israel''s half, Moses took one drawn out of every fifty, both of man and of animal, and gave them to the Levites, who performed the duty of the tabernacle of Yahweh; as Yahweh commanded Moses.'),
  ('260122c9-a347-569c-af64-932d56939021', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 48, 48, 'The officers who were over the thousands of the army, the captains of thousands, and the captains of hundreds, came near to Moses;'),
  ('bef004f7-330b-5134-ad0a-6820eca5eb6e', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 49, 49, 'and they said to Moses, "Your servants have taken the sum of the men of war who are under our command, and there lacks not one man of us.'),
  ('cf8fd937-4299-5e1f-afaa-b86ff19531b4', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 50, 50, 'We have brought Yahweh''s offering, what every man has gotten, of jewels of gold, armlets, and bracelets, signet rings, earrings, and necklaces, to make atonement for our souls before Yahweh."'),
  ('eec0f2be-1b7e-5c04-a328-fea81dab7f2b', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 51, 51, 'Moses and Eleazar the priest took the gold of them, even all worked jewels.'),
  ('bfe24237-82f6-59ac-abea-07c60178548f', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 52, 52, 'All the gold of the wave offering that they offered up to Yahweh, of the captains of thousands, and of the captains of hundreds, was sixteen thousand seven hundred fifty shekels.'),
  ('799ffe16-626b-5c84-afef-7d51dcab957a', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 53, 53, '([For] the men of war had taken booty, every man for himself.)'),
  ('de735a3b-147f-532e-afd0-5bdad26a4682', '7b2ff092-c558-5be5-a0ef-b7e96a59413b', NULL, 54, 54, 'Moses and Eleazar the priest took the gold of the captains of thousands and of hundreds, and brought it into the Tent of Meeting, for a memorial for the children of Israel before Yahweh.'),
  ('68bd8119-e729-5587-a400-6f3605b28ab1', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 1, 1, 'Now the children of Reuben and the children of Gad had a very great multitude of livestock: and when they saw the land of Jazer, and the land of Gilead, that behold, the place was a place for livestock;'),
  ('17d7f471-1d70-59ee-a242-6e7276e3c6eb', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 2, 2, 'the children of Gad and the children of Reuben came and spoke to Moses, and to Eleazar the priest, and to the princes of the congregation, saying,'),
  ('cba41e27-4678-51b7-a4c8-87b413f24295', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 3, 3, '"Ataroth, and Dibon, and Jazer, and Nimrah, and Heshbon, and Elealeh, and Sebam, and Nebo, and Beon,'),
  ('33ed115b-d551-5ff2-a72a-04b59924a711', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 4, 4, 'the land which Yahweh struck before the congregation of Israel, is a land for livestock; and your servants have livestock."'),
  ('90e35da2-261e-5802-ad63-cbb48034751f', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 5, 5, 'They said, "If we have found favor in your sight, let this land be given to your servants for a possession; don''t bring us over the Jordan."'),
  ('af9ca7b3-747b-593e-a6a8-48354a273764', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 6, 6, 'Moses said to the children of Gad, and to the children of Reuben, "Shall your brothers go to the war, and shall you sit here?'),
  ('10ad2fe0-7750-59b6-a2f9-18617f2c0b91', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 7, 7, 'Why do you discourage the heart of the children of Israel from going over into the land which Yahweh has given them?'),
  ('54969085-90ae-5c3d-ab0f-ef21dd18ce66', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 8, 8, 'Your fathers did so when I sent them from Kadesh Barnea to see the land.'),
  ('b99aa19e-11d5-52ef-a525-a60b32b09599', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 9, 9, 'For when they went up to the valley of Eshcol, and saw the land, they discouraged the heart of the children of Israel, that they should not go into the land which Yahweh had given them.'),
  ('6981f308-d734-5d4e-af5d-38f325da37fd', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 10, 10, 'Yahweh''s anger was kindled in that day, and he swore, saying,'),
  ('8d2444fd-b0b5-50e3-a934-6c17694b114a', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 11, 11, '''Surely none of the men who came up out of Egypt, from twenty years old and upward, shall see the land which I swore to Abraham, to Isaac, and to Jacob; because they have not wholly followed me:'),
  ('20e4c875-8fdb-5af7-a3c1-1cf1d77855e9', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 12, 12, 'except Caleb the son of Jephunneh the Kenizzite, and Joshua the son of Nun; because they have followed Yahweh completely.'''),
  ('8b828f09-97de-5f58-a4f9-7075cdb0c0e7', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 13, 13, 'Yahweh''s anger was kindled against Israel, and he made them wander back and forth in the wilderness forty years, until all the generation, who had done evil in the sight of Yahweh, was consumed.'),
  ('e6d30e33-9690-51e9-a58e-e1f77583ea06', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 14, 14, '"Behold, you have risen up in your fathers'' place, an increase of sinful men, to augment yet the fierce anger of Yahweh toward Israel.'),
  ('54436483-5474-51f8-aa21-a2baaf751eb0', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 15, 15, 'For if you turn away from after him, he will yet again leave them in the wilderness; and you will destroy all this people."'),
  ('aa6b488f-6ad5-5655-a4c4-1b1710c729f4', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 16, 16, 'They came near to him, and said, "We will build sheepfolds here for our livestock, and cities for our little ones:'),
  ('d187ff38-9dca-55f8-a614-e667c67113fd', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 17, 17, 'but we ourselves will be ready armed to go before the children of Israel, until we have brought them to their place: and our little ones shall dwell in the fortified cities because of the inhabitants of the land.'),
  ('ac24f9cb-fd0e-5936-a5e9-12812669036f', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 18, 18, 'We will not return to our houses, until the children of Israel have inherited every man his inheritance.'),
  ('4300a0e0-d623-5610-aed0-94f167d79118', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 19, 19, 'For we will not inherit with them on the other side of the Jordan, and forward; because our inheritance is fallen to us on this side of the Jordan eastward."'),
  ('fc25a0bf-bf27-5278-a1fc-9cd2918eb8c7', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 20, 20, 'Moses said to them, "If you will do this thing, if you will arm yourselves to go before Yahweh to the war,'),
  ('1c048845-9436-5cc1-a95e-5d3c0ad083f9', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 21, 21, 'and every armed man of you will pass over the Jordan before Yahweh, until he has driven out his enemies from before him,'),
  ('f7660e58-2c00-5d9c-a1e3-264d05ccf6fb', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 22, 22, 'and the land is subdued before Yahweh; then afterward you shall return, and be guiltless towards Yahweh, and towards Israel; and this land shall be to you for a possession before Yahweh.'),
  ('affbceda-baf6-5abe-af5c-f3a3ae6a4bc7', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 23, 23, '"But if you will not do so, behold, you have sinned against Yahweh; and be sure your sin will find you out.'),
  ('bd6da3e6-583c-578f-a2e4-16aa39921b58', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 24, 24, 'Build cities for your little ones, and folds for your sheep; and do that which has proceeded out of your mouth."'),
  ('97953521-e239-59ee-ac91-8cee23c61074', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 25, 25, 'The children of Gad and the children of Reuben spoke to Moses, saying, "Your servants will do as my lord commands.'),
  ('7be59834-3c66-5afe-a3bf-2cfb8adc487b', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 26, 26, 'Our little ones, our wives, our flocks, and all our livestock, shall be there in the cities of Gilead;'),
  ('0d89bc95-6956-5f11-a83d-141ee90982f1', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 27, 27, 'but your servants will pass over, every man who is armed for war, before Yahweh to battle, as my lord says."'),
  ('cf0cb355-bf45-5628-af9a-564091992953', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 28, 28, 'So Moses commanded concerning them to Eleazar the priest, and to Joshua the son of Nun, and to the heads of the fathers'' [houses] of the tribes of the children of Israel.'),
  ('6fd1b161-631a-5ea7-ae5f-c5c7357a6106', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 29, 29, 'Moses said to them, "If the children of Gad and the children of Reuben will pass with you over the Jordan, every man who is armed to battle, before Yahweh, and the land shall be subdued before you; then you shall give them the land of Gilead for a possession:'),
  ('86de95fb-9d57-599f-a4bb-71f1b47755f0', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 30, 30, 'but if they will not pass over with you armed, they shall have possessions among you in the land of Canaan."'),
  ('d3c491b2-60a4-56dd-a82e-13d67ee6a51e', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 31, 31, 'The children of Gad and the children of Reuben answered, saying, "As Yahweh has said to your servants, so will we do.'),
  ('e92c5821-8ce8-519b-a55f-fc9d4effddc4', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 32, 32, 'We will pass over armed before Yahweh into the land of Canaan, and the possession of our inheritance [shall remain] with us beyond the Jordan."'),
  ('9fe5330f-ff37-5a22-a479-741bb02a98ce', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 33, 33, 'Moses gave to them, even to the children of Gad, and to the children of Reuben, and to the half-tribe of Manasseh the son of Joseph, the kingdom of Sihon king of the Amorites, and the kingdom of Og king of Bashan, the land, according to the cities of it with [their] borders, even the cities of the surrounding land.'),
  ('635c2c5a-334e-5f92-af75-6c543997ceeb', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 34, 34, 'The children of Gad built Dibon, and Ataroth, and Aroer,'),
  ('b7c8179f-1cfe-5c0e-a70f-b0849e9af67e', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 35, 35, 'and Atrothshophan, and Jazer, and Jogbehah,'),
  ('375ee216-6e8c-5e77-ad2b-33470efaca89', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 36, 36, 'and Beth Nimrah, and Beth Haran: fortified cities, and folds for sheep.'),
  ('3f441323-10bc-5ca2-a823-e02e755c1db9', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 37, 37, 'The children of Reuben built Heshbon, and Elealeh, and Kiriathaim,'),
  ('34864499-d3c2-5db6-adb5-44d0b27fde2a', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 38, 38, 'and Nebo, and Baal Meon, (their names being changed), and Sibmah: and they gave other names to the cities which they built.'),
  ('17e6878a-19f2-5021-ae84-bf596d94864b', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 39, 39, 'The children of Machir the son of Manasseh went to Gilead, and took it, and dispossessed the Amorites who were therein.'),
  ('a79ba58e-5a48-5dd0-a238-5a7e4270ee4f', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 40, 40, 'Moses gave Gilead to Machir the son of Manasseh; and he lived therein.'),
  ('581878b5-eb68-51ae-a960-2a6997df0e18', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 41, 41, 'Jair the son of Manasseh went and took its towns, and called them Havvoth Jair.'),
  ('4adf2e00-5277-5e83-a56b-5efdea9afc1e', 'ec9a6b80-3022-5dc7-ac86-7985256838ba', NULL, 42, 42, 'Nobah went and took Kenath, and its villages, and called it Nobah, after his own name.'),
  ('20b7bcf2-8104-5416-a45f-93c4c3d7f1e7', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 1, 1, 'These are the journeys of the children of Israel, when they went forth out of the land of Egypt by their armies under the hand of Moses and Aaron.'),
  ('a6c5b10f-4454-59c4-a796-169d7c013ea7', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 2, 2, 'Moses wrote their goings out according to their journeys by the commandment of Yahweh: and these are their journeys according to their goings out.'),
  ('61e99fa0-e3f9-5d28-ac32-b153fb42c367', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 3, 3, 'They traveled from Rameses in the first month, on the fifteenth day of the first month; on the next day after the Passover the children of Israel went out with a high hand in the sight of all the Egyptians,'),
  ('53bc4b1a-7d48-512c-a3ca-ff62c054d021', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 4, 4, 'while the Egyptians were burying all their firstborn, whom Yahweh had struck among them: on their gods also Yahweh executed judgments.'),
  ('b0dfe1d4-5376-5fdf-acfb-4d58ffeccec9', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 5, 5, 'The children of Israel traveled from Rameses, and encamped in Succoth.'),
  ('cfb9142f-f161-5d64-aa01-764cbcf1b4a8', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 6, 6, 'They traveled from Succoth, and encamped in Etham, which is in the edge of the wilderness.'),
  ('e36a38d0-7b24-54a2-a2c5-bc77d83cde19', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 7, 7, 'They traveled from Etham, and turned back to Pihahiroth, which is before Baal Zephon: and they encamped before Migdol.'),
  ('52087e5d-9930-553d-a2b6-c4964e573bb2', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 8, 8, 'They traveled from before Hahiroth, and passed through the midst of the sea into the wilderness: and they went three days'' journey in the wilderness of Etham, and encamped in Marah.'),
  ('809bac1c-51c2-51c7-a489-b49f24aa7730', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 9, 9, 'They traveled from Marah, and came to Elim: and in Elim were twelve springs of water, and seventy palm trees; and they encamped there.'),
  ('5129ac5c-a160-5114-a7dc-a765be2eb414', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 10, 10, 'They traveled from Elim, and encamped by the Red Sea.'),
  ('1eb5a666-3d8a-520e-a217-97cac9408962', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 11, 11, 'They traveled from the Red Sea, and encamped in the wilderness of Sin.'),
  ('915fe5c9-1120-5a3f-a384-396b26e76993', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 12, 12, 'They traveled from the wilderness of Sin, and encamped in Dophkah.'),
  ('54571b40-05a8-55bf-a5f6-273e3f464548', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 13, 13, 'They traveled from Dophkah, and encamped in Alush.'),
  ('37603c2f-a350-5058-ac79-31227e4fb93e', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 14, 14, 'They traveled from Alush, and encamped in Rephidim, where there was no water for the people to drink.'),
  ('ec3e4567-a1ba-52bc-a44a-cf131abbf847', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 15, 15, 'They traveled from Rephidim, and encamped in the wilderness of Sinai.'),
  ('dd3860f5-ff7e-5299-a545-525d32694f3a', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 16, 16, 'They traveled from the wilderness of Sinai, and encamped in Kibroth Hattaavah.'),
  ('201540c9-3cae-523b-a64b-1a8ec27a23d9', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 17, 17, 'They traveled from Kibroth Hattaavah, and encamped in Hazeroth.'),
  ('c8590862-6697-5b0d-a2ff-9b4e34ae5546', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 18, 18, 'They traveled from Hazeroth, and encamped in Rithmah.'),
  ('e43547e7-648f-5d23-a22e-4675fc61f2af', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 19, 19, 'They traveled from Rithmah, and encamped in Rimmon Perez.'),
  ('0624b155-f7ff-55e4-acae-eb29dece75d5', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 20, 20, 'They traveled from Rimmon Perez, and encamped in Libnah.'),
  ('ed691d48-1ac6-5478-a686-3f2118cf25a2', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 21, 21, 'They traveled from Libnah, and encamped in Rissah.'),
  ('84e13b01-e373-545c-a956-a1746090d8ea', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 22, 22, 'They traveled from Rissah, and encamped in Kehelathah.'),
  ('edad0b1c-f506-58f6-a45c-3677c399615d', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 23, 23, 'They traveled from Kehelathah, and encamped in Mount Shepher.'),
  ('32eb1827-2a3b-51f9-ae7b-3f93da4b9d0f', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 24, 24, 'They traveled from Mount Shepher, and encamped in Haradah.'),
  ('19e93b9e-00fb-5116-a650-c933b8fda5a1', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 25, 25, 'They traveled from Haradah, and encamped in Makheloth.'),
  ('f409eb37-76ba-5328-ae04-18801d728700', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 26, 26, 'They traveled from Makheloth, and encamped in Tahath.'),
  ('0820a34d-a93e-51e8-ad43-bf343a70ca4a', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 27, 27, 'They traveled from Tahath, and encamped in Terah.'),
  ('c723e101-bb05-51f2-ab25-6ab56a68214a', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 28, 28, 'They traveled from Terah, and encamped in Mithkah.'),
  ('30086b77-60cc-54ba-abdf-9dffb4dd133f', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 29, 29, 'They traveled from Mithkah, and encamped in Hashmonah.'),
  ('ae10a233-72e4-57da-acc3-e0463abfa7f1', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 30, 30, 'They traveled from Hashmonah, and encamped in Moseroth.'),
  ('3307e278-48a4-5b88-a561-cecb40a9b18e', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 31, 31, 'They traveled from Moseroth, and encamped in Bene Jaakan.'),
  ('bb21f80b-f198-5be6-a5b8-05b95547a274', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 32, 32, 'They traveled from Bene Jaakan, and encamped in Hor Haggidgad.'),
  ('e55c06d2-ff3e-5920-a580-142d9d8cd1a6', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 33, 33, 'They traveled from Hor Haggidgad, and encamped in Jotbathah.'),
  ('f91bd8d2-92f6-5762-a8a6-2171d9146649', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 34, 34, 'They traveled from Jotbathah, and encamped in Abronah.'),
  ('8afb390d-8e13-502e-aa91-bc50867fcc55', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 35, 35, 'They traveled from Abronah, and encamped in Ezion Geber.'),
  ('38e4a5b6-f08d-5988-a298-7c2dd4225c5a', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 36, 36, 'They traveled from Ezion Geber, and encamped in the wilderness of Zin (the same is Kadesh).'),
  ('40e86781-5ea5-5da5-a01b-10cc83908bb1', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 37, 37, 'They traveled from Kadesh, and encamped in Mount Hor, in the edge of the land of Edom.'),
  ('7b6b2ebd-6e95-5410-a4ec-f230e55733f6', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 38, 38, 'Aaron the priest went up into Mount Hor at the commandment of Yahweh, and died there, in the fortieth year after the children of Israel were come out of the land of Egypt, in the fifth month, on the first day of the month.'),
  ('180da6bb-ce13-58a4-a82c-ff9d535477de', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 39, 39, 'Aaron was one hundred twenty-three years old when he died in Mount Hor.'),
  ('ded79129-9dbf-59cb-a426-3c8a32298e71', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 40, 40, 'The Canaanite, the king of Arad, who lived in the South in the land of Canaan, heard of the coming of the children of Israel.'),
  ('6e40c807-b257-5df5-afa3-b20d0b2b3e2d', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 41, 41, 'They traveled from Mount Hor, and encamped in Zalmonah.'),
  ('a49da8c0-e24d-5da3-a55f-6f4de72baef5', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 42, 42, 'They traveled from Zalmonah, and encamped in Punon.'),
  ('d2f3bbf6-62ce-59c4-a167-d5e6aa94daae', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 43, 43, 'They traveled from Punon, and encamped in Oboth.'),
  ('28b12dfc-5033-5266-ad27-20750e582cbe', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 44, 44, 'They traveled from Oboth, and encamped in Iye Abarim, in the border of Moab.'),
  ('0e611138-ec8f-58c2-ad74-885b831b1f1a', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 45, 45, 'They traveled from Iyim, and encamped in Dibon Gad.'),
  ('e69deef8-dbf7-5b38-a10b-057b6e95887a', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 46, 46, 'They traveled from Dibon Gad, and encamped in Almon Diblathaim.'),
  ('b58af728-5206-545e-a56c-91401e441b31', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 47, 47, 'They traveled from Almon Diblathaim, and encamped in the mountains of Abarim, before Nebo.'),
  ('5befa5db-eb08-593b-a4a5-27f29ab6bb6a', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 48, 48, 'They traveled from the mountains of Abarim, and encamped in the plains of Moab by the Jordan at Jericho.'),
  ('7499c824-d955-5026-ab00-64988ea940ad', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 49, 49, 'They encamped by the Jordan, from Beth Jeshimoth even to Abel Shittim in the plains of Moab.'),
  ('308642be-dd3b-5bee-a411-1fa4f569ebd8', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 50, 50, 'Yahweh spoke to Moses in the plains of Moab by the Jordan at Jericho, saying,'),
  ('40c46ef3-7046-5beb-aed3-88a1f377a532', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 51, 51, 'Speak to the children of Israel, and tell them, "When you pass over the Jordan into the land of Canaan,'),
  ('2955000d-6acd-5922-aeec-91ae88277c77', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 52, 52, 'then you shall drive out all the inhabitants of the land from before you, and destroy all their figured [stones], and destroy all their molten images, and demolish all their high places:'),
  ('5d03ef1c-2506-5841-a10e-8d545886f454', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 53, 53, 'and you shall take possession of the land, and dwell therein; for I have given given the land to you to possess it.'),
  ('355ed4a4-f0bd-5a8c-aa3d-6718360d1b89', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 54, 54, 'You shall inherit the land by lot according to your families; to the more you shall give the more inheritance, and to the fewer you shall give the less inheritance: wherever the lot falls to any man, that shall be his. You shall inherit according to the tribes of your fathers.'),
  ('9d174904-70aa-5ecd-a7f3-5cf3c23688ab', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 55, 55, '"But if you do not drive out the inhabitants of the land from before you, then those you let remain of them will be as pricks in your eyes and as thorns in your sides, and they will harass you in the land in which you dwell.'),
  ('e948f588-7bf3-5975-a83e-46dd7487ba55', '405e9f44-13f5-52c2-ae19-2aba17b810a2', NULL, 56, 56, 'It shall happen that as I thought to do to them, so will I do to you."'),
  ('61808df3-cb6d-5f06-a69a-1090d35dea28', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 1, 1, 'Yahweh spoke to Moses, saying,'),
  ('d6bba02a-98de-56d4-acdd-7f0af32f8374', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 2, 2, '"Command the children of Israel, and tell them, ''When you come into the land of Canaan (this is the land that shall fall to you for an inheritance, even the land of Canaan according to its borders),'),
  ('29172ee0-682d-597e-a606-f735d49f50a5', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 3, 3, 'then your south quarter shall be from the wilderness of Zin along by the side of Edom, and your south border shall be from the end of the Salt Sea eastward;'),
  ('2db34d72-dcfa-531e-ad79-6d2c0f9b5371', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 4, 4, 'and your border shall turn about southward of the ascent of Akrabbim, and pass along to Zin; and the goings out of it shall be southward of Kadesh Barnea; and it shall go forth to Hazar Addar, and pass along to Azmon;'),
  ('1014ccb0-106e-537c-a9af-910e5694048e', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 5, 5, 'and the border shall turn about from Azmon to the brook of Egypt, and the goings out of it shall be at the sea.'),
  ('0cd3c54f-ceec-5459-ad33-4398c4928d5b', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 6, 6, '"''For the western border, you shall have the great sea and the border [of it]: this shall be your west border.'),
  ('6c315a82-f509-5bca-a0df-cd4748a6f03c', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 7, 7, '"''This shall be your north border: from the great sea you shall mark out for you Mount Hor;'),
  ('19f1bd54-648b-5021-a5a0-8362820c4a13', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 8, 8, 'from Mount Hor you shall mark out to the entrance of Hamath; and the goings out of the border shall be at Zedad;'),
  ('33ec2dc1-fed4-5ebf-a9cc-30199c2c6965', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 9, 9, 'and the border shall go forth to Ziphron, and the goings out of it shall be at Hazar Enan: this shall be your north border.'),
  ('b104c888-30fe-5875-a931-6a6d490229b0', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 10, 10, '"''You shall mark out your east border from Hazar Enan to Shepham;'),
  ('8ca25f22-cf20-5fa6-a910-e3e00cb5e34f', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 11, 11, 'and the border shall go down from Shepham to Riblah, on the east side of Ain; and the border shall go down, and shall reach to the side of the sea of Chinnereth eastward;'),
  ('175d0e74-b54e-59a0-ac05-1111f022ad48', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 12, 12, 'and the border shall go down to the Jordan, and the goings out of it shall be at the Salt Sea. This shall be your land according to its borders around it.''"'),
  ('db5cfa45-3e3c-59b0-a831-693642fc09e6', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 13, 13, 'Moses commanded the children of Israel, saying, "This is the land which you shall inherit by lot, which Yahweh has commanded to give to the nine tribes, and to the half-tribe;'),
  ('96086275-e747-53ac-a59f-a5056eb177da', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 14, 14, 'for the tribe of the children of Reuben according to their fathers'' houses, and the tribe of the children of Gad according to their fathers'' houses, have received, and the half-tribe of Manasseh have received, their inheritance:'),
  ('e42ee3a3-617f-539e-aad2-e56fe547ef71', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 15, 15, 'the two tribes and the half-tribe have received their inheritance beyond the Jordan at Jericho eastward, toward the sunrise."'),
  ('388fd31d-1bb8-5ed8-a19d-adf9d5e0c0e5', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 16, 16, 'Yahweh spoke to Moses, saying,'),
  ('72d864fb-e065-5231-a56a-5c2a98ecd999', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 17, 17, '"These are the names of the men who shall divide the land to you for inheritance: Eleazar the priest, and Joshua the son of Nun.'),
  ('6748dd27-0b19-5361-a7ab-8efff8198f04', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 18, 18, 'You shall take one prince of every tribe, to divide the land for inheritance.'),
  ('49ff8789-97db-57ab-a464-b787067a35e2', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 19, 19, 'These are the names of the men: Of the tribe of Judah, Caleb the son of Jephunneh.'),
  ('6750df13-09e0-5456-ac03-1bc500c111b3', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 20, 20, 'Of the tribe of the children of Simeon, Shemuel the son of Ammihud.'),
  ('6ebb4435-a0a5-5b8c-a7de-2a4a276c0bb5', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 21, 21, 'Of the tribe of Benjamin, Elidad the son of Chislon.'),
  ('96992cc6-3094-58a1-aea1-69252078d34d', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 22, 22, 'Of the tribe of the children of Dan a prince, Bukki the son of Jogli.'),
  ('f6d564f3-6016-5f94-a893-8cf60a7b1b5a', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 23, 23, 'Of the children of Joseph: of the tribe of the children of Manasseh a prince, Hanniel the son of Ephod.'),
  ('ff840102-2b7c-51ee-a3ad-820356044d87', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 24, 24, 'Of the tribe of the children of Ephraim a prince, Kemuel the son of Shiphtan.'),
  ('edb1660f-1b92-55b3-a1d3-1b3d5ca3fbdd', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 25, 25, 'Of the tribe of the children of Zebulun a prince, Elizaphan the son of Parnach.'),
  ('d510eb6f-3cff-5336-a383-7e2bb662ffeb', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 26, 26, 'Of the tribe of the children of Issachar a prince, Paltiel the son of Azzan.'),
  ('a98a0e98-49d1-5fc3-ad60-23378d30c08c', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 27, 27, 'Of the tribe of the children of Asher a prince, Ahihud the son of Shelomi.'),
  ('630ecf18-7de4-59e7-a2f1-1c71d758048b', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 28, 28, 'Of the tribe of the children of Naphtali a prince, Pedahel the son of Ammihud."'),
  ('0de7ae39-3885-5029-a1c6-d817cffe8774', '2d8b85ad-ed96-57b4-a985-06cd8da1e9a1', NULL, 29, 29, 'These are they whom Yahweh commanded to divide the inheritance to the children of Israel in the land of Canaan.'),
  ('331c2e33-7c8c-529f-a71c-154e60bbfe3c', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 1, 1, 'Yahweh spoke to Moses in the plains of Moab by the Jordan at Jericho, saying,'),
  ('04d3c8df-8981-58ce-a793-07dd13a30cbf', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 2, 2, '"Command the children of Israel that they give to the Levites of the inheritance of their possession cities to dwell in; and you shall give suburbs for the cities around them to the Levites.'),
  ('09ebcef1-4483-5073-a8fc-0665431cb467', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 3, 3, 'The cities shall they have to dwell in; and their suburbs shall be for their livestock, and for their substance, and for all their animals.'),
  ('613cda60-ad85-55cc-abdd-1d1914d4605f', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 4, 4, '"The suburbs of the cities, which you shall give to the Levites, shall be from the wall of the city and outward one thousand cubits around it.'),
  ('62bf296e-d705-5b2e-ad0a-1cad311ea042', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 5, 5, 'You shall measure outside of the city for the east side two thousand cubits, and for the south side two thousand cubits, and for the west side two thousand cubits, and for the north side two thousand cubits, the city being in the midst. This shall be to them the suburbs of the cities.'),
  ('d4eaae2b-0c64-52a7-a359-bc39be17a7ed', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 6, 6, '"The cities which you shall give to the Levites, they shall be the six cities of refuge, which you shall give for the manslayer to flee to: and besides them you shall give forty-two cities.'),
  ('12b4e001-f322-5b65-aca3-431fb9bcec98', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 7, 7, 'All the cities which you shall give to the Levites shall be forty-eight cities together with their suburbs.'),
  ('ac73af66-6441-5e22-ae61-96a3e81f96f7', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 8, 8, 'Concerning the cities which you shall give of the possession of the children of Israel, from the many you shall take many; and from the few you shall take few: everyone according to his inheritance which he inherits shall give of his cities to the Levites."'),
  ('6735c372-6b29-5976-a55f-7a6e72cb896f', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 9, 9, 'Yahweh spoke to Moses, saying,'),
  ('8d2aafa9-9e58-5567-a59c-e4a97827f123', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 10, 10, '"Speak to the children of Israel, and tell them, ''When you pass over the Jordan into the land of Canaan,'),
  ('32e821bb-3ed4-5c74-a5a2-416aea9979d8', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 11, 11, 'then you shall appoint you cities to be cities of refuge for you, that the manslayer who kills any person unwittingly may flee there.'),
  ('a3dfe694-7f3d-50ea-a408-8fcf4be79e7d', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 12, 12, 'The cities shall be to you for refuge from the avenger, that the manslayer not die, until he stands before the congregation for judgment.'),
  ('87127a53-f2b7-5996-a0aa-c64fdfdd9e36', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 13, 13, 'The cities which you shall give shall be for you six cities of refuge.'),
  ('2ed6f4f0-2b47-5cce-a454-0df6d60e35f9', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 14, 14, 'You shall give three cities beyond the Jordan, and you shall give three cities in the land of Canaan; they shall be cities of refuge.'),
  ('54b82aa6-db90-5804-aaa1-da3ade221112', '51d40fef-d4ff-598e-a282-137d9ff31d0b', NULL, 15, 15, 'For the children of Israel, and for the stranger and for the foreigner living among them, shall these six cities be for refuge; that everyone who kills any person unwittingly may flee there.')
